INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C1','math',2,2,'u4',2,'5분 단위로 시각 읽기 — 짧은바늘로 시를, 긴바늘이 가리키는 숫자에 5를 곱해 분을 읽어 「몇 시 몇 분」으로 나타내기',ARRAY['2수03-05']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C2','math',2,2,'u4',2,'디지털시계 읽기 — 「:」 왼쪽은 시, 오른쪽은 분임을 알고 「열 시 삼십오 분」처럼 바르게 읽고 바늘 시계와 같은 시각을 찾기',ARRAY['2수03-05']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C3','math',2,2,'u4',3,'1분 단위로 시각 읽기 — 작은 눈금 한 칸이 1분임을 알고, 가까운 숫자에서 몇 칸 더(덜) 갔는지 세어 몇 시 몇 분을 읽기',ARRAY['2수03-05']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C4','math',2,2,'u4',4,'몇 시 몇 분 전 — 정각이 되기까지 남은 분을 세어 「몇 시 몇 분 전」으로 읽고, 「몇 시 몇 분 전」을 「몇 시 몇 분」으로 바꾸기',ARRAY['2수03-05']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C5','math',2,2,'u4',5,'1시간 알기 — 긴바늘이 한 바퀴 도는 데 60분이 걸리고 60분 = 1시간임을 알며, 시간 띠(한 칸 10분)로 걸린 시간을 세기',ARRAY['2수03-06']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C6','math',2,2,'u4',6,'걸린 시간 구하기 — 1시간을 먼저 돌리고 더 간 만큼 세어 걸린 시간을 구하고, 몇 시간 몇 분과 몇 분을 서로 바꾸기',ARRAY['2수03-06']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C7','math',2,2,'u4',7,'하루의 시간 — 하루는 24시간이고 오전·오후가 각각 12시간임을 알며, 생활 계획표로 하는 일의 시간을 알고, 하루가 넘는 시간과 오전·오후를 넘는 시각을 구하기',ARRAY['2수03-06']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C8','math',2,2,'u4',8,'달력과 1주일 — 달력에서 날짜와 요일을 읽고, 1주일 = 7일을 써서 몇째 무슨 요일·며칠 후(전)·요일의 횟수를 찾기',ARRAY['2수03-06']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C9','math',2,2,'u4',8,'1년과 달의 날수 — 1년 = 12개월임을 알고 몇 년 몇 개월과 몇 개월을 바꾸며, 달마다 날수가 다름을 알고 「몇 월」과 「몇 개월」을 가리기',ARRAY['2수03-06']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C10','math',2,2,'u4',10,'시간으로 문제 해결하기 — 성장 이야기와 디데이를 만들며 년·개월·주·일 사이의 관계로 날짜와 기간을 구하기',ARRAY['2수03-06']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X01','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C3']::text[],'짧은바늘과 긴바늘을 바꾸어 읽는다 — 긴바늘이 가리키는 숫자를 시로, 짧은바늘을 분으로 읽는다','짧은바늘은 시, 긴바늘은 분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X02','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C2','M2-2-u4-C3']::text[],'긴바늘이 가리키는 숫자를 그대로 분으로 읽는다(숫자 3 → 3분)','긴바늘 숫자에 5를 곱하기 — 숫자 1이 5분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X03','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C3','M2-2-u4-C4']::text[],'짧은바늘이 다음 숫자 가까이 있으면 다음 시로 읽는다(4시 55분 → 5시 55분)','짧은바늘이 지나온 숫자가 시 — 아직 다음 숫자에 닿지 않았어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X04','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C2','M2-2-u4-C3']::text[],'이웃 눈금·이웃 숫자로 잘못 읽어 1분·5분 어긋나게 읽는다','눈금을 손가락으로 짚으며 한 칸씩 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X05','math',2,'u4',ARRAY['M2-2-u4-C3']::text[],'숫자에서 몇 칸 「더 간」 곳과 「덜 간」 곳을 거꾸로 센다(40분에서 1칸 덜 간 곳 → 41분)','시계 방향은 더 가기, 거꾸로는 덜 가기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X06','math',2,'u4',ARRAY['M2-2-u4-C2']::text[],'디지털시계의 시와 분을 뒤바꾸거나 읽는 말을 잘못 쓴다(10 : 35 → 「십 시」, 「삼십오 시 열 분」)','「:」 왼쪽은 시 「한·두·세」, 오른쪽은 분 「일·이·삼」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X07','math',2,'u4',ARRAY['M2-2-u4-C4']::text[],'「몇 시 몇 분 전」의 시를 곧 될 정각이 아니라 지금 시로 쓴다(8시 55분 → 8시 5분 전)','「전」의 시는 곧 될 정각 — 지금 시보다 하나 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X08','math',2,'u4',ARRAY['M2-2-u4-C4']::text[],'정각까지 남은 분 대신 지난 분을 쓰거나 「전」을 빼고 읽는다(8시 55분 → 9시 55분 전, 9시 5분 전 → 9시 5분)','정각까지 몇 분 남았는지 세기 — 「전」은 꼭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X09','math',2,'u4',ARRAY['M2-2-u4-C5','M2-2-u4-C6']::text[],'1시간을 100분으로 보고 시간과 분을 바꾼다(1시간 10분 → 110분)','1시간은 60분 — 긴바늘 한 바퀴') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X10','math',2,'u4',ARRAY['M2-2-u4-C4','M2-2-u4-C5','M2-2-u4-C6','M2-2-u4-C7','M2-2-u4-C9','M2-2-u4-C10']::text[],'걸린 시간·지난 시각을 셀 때 칸·시간을 하나 더 세거나 덜 센다','시작에서 한 칸씩 짚으며 다시 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X11','math',2,'u4',ARRAY['M2-2-u4-C5','M2-2-u4-C6']::text[],'시각과 시간을 섞는다 — 끝난 시각을 걸린 시간으로 답하거나, 몇 시를 몇 시간으로 읽는다','시각은 「때」, 시간은 「동안」 — 시작과 끝 사이를 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X12','math',2,'u4',ARRAY['M2-2-u4-C7']::text[],'낮 12시를 넘어도 오전으로 쓰거나 13시·14시처럼 그대로 이어 쓰고, 오전·오후를 뒤바꾼다','낮 12시를 지나면 오후 1시부터 다시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X13','math',2,'u4',ARRAY['M2-2-u4-C7']::text[],'하루를 12시간으로 알거나, 하는 일이 많은 쪽이 더 길다고 여긴다','짧은바늘 두 바퀴 = 24시간 — 오전도 오후도 12시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X14','math',2,'u4',ARRAY['M2-2-u4-C8','M2-2-u4-C9','M2-2-u4-C10']::text[],'날짜의 이름과 기간의 길이를 섞는다 — 「12월」과 「12개월」, 그날의 날짜와 지난 날수를 같게 본다','「월·일」은 이름, 「개월·일 동안」은 길이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X15','math',2,'u4',ARRAY['M2-2-u4-C8','M2-2-u4-C9','M2-2-u4-C10']::text[],'1주일·1년의 단위를 모른다 — 1주일을 5일·10일로, 1년을 10개월로 보거나 주와 일을 그냥 더한다','1주일 = 7일, 1년 = 12개월') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X16','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C2','M2-2-u4-C3','M2-2-u4-C4','M2-2-u4-C5','M2-2-u4-C6','M2-2-u4-C7','M2-2-u4-C8','M2-2-u4-C9','M2-2-u4-C10']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔바른, 아닌↔맞는, 이른↔늦은','물음의 「잘못·아닌·이른」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X17','math',2,'u4',ARRAY['M2-2-u4-C8','M2-2-u4-C10']::text[],'달력에서 며칠 후(전)를 셀 때 그날을 넣어 세거나, 요일 칸을 하나 밀려 읽는다','그날은 빼고 다음 날부터 하루씩 — 요일은 세로줄 위를 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X18','math',2,'u4',ARRAY['M2-2-u4-C9','M2-2-u4-C10']::text[],'달마다 날수가 다름을 모른다 — 모든 달을 30일로 보거나 달을 넘어가는 날짜를 그대로 쓴다(7월 47일)','31일·30일 달을 주먹 손등으로 세기 — 넘치면 다음 달') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X20','math',2,'u4',ARRAY['M2-2-u4-C5','M2-2-u4-C7','M2-2-u4-C8','M2-2-u4-C9']::text[],'단위를 보지 않고 숫자만 같은 것끼리 같다고 본다 — 「1시간」과 「1일」, 「1주일」과 「1년」을 잇는다','숫자보다 단위(분·시간·일·개월)를 먼저 읽고, 작은 단위가 몇 개 모여야 큰 단위가 되는지 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X21','math',2,'u4',ARRAY['M2-2-u4-C8','M2-2-u4-C9']::text[],'1주일·1년을 일요일·1월에서 시작해 토요일·12월에 끝나는 것만으로 안다 — 수요일부터 다음 주 화요일, 3월부터 다음 해 2월도 1주일·1년인 것을 모른다','어느 날에서 시작하든 이어진 7일이 1주일, 이어진 열두 달이 1년 — 달력에서 손가락으로 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X22','math',2,'u4',ARRAY['M2-2-u4-C6']::text[],'시는 시끼리, 분은 분끼리 따로 빼서 걸린 시간을 구한다 — 10시 40분부터 12시까지를 「12 − 10 = 2, 분은 40」이라 2시간 40분으로 쓴다','시작한 시각에서 1시간씩 먼저 가 보고, 끝난 시각까지 남은 분을 더 세기 — 시간 띠 칸 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X23','math',2,'u4',ARRAY['M2-2-u4-C9']::text[],'「달」과 「개월」 앞의 수 읽기를 섞는다 — 3개월을 「세 개월」, 3달을 「삼 달」로 읽는다','「달」 앞에는 한·두·세, 「개월」 앞에는 일·이·삼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_basic#1','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'mc','auto','1학년 때 배운 시각을 떠올려요. 짧은바늘이 7, 긴바늘이 12를 가리켜요. 시각을 바르게 쓰고 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06','M2-2-u4-X01']::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"1학년 때 배운 시각을 떠올려요. 짧은바늘이 7, 긴바늘이 12를 가리켜요. 시각을 바르게 쓰고 읽은 것은 어느 것인가요?","options":[{"t":"7시 — 일곱 시","correct":true},{"t":"7시 — 칠 시","mis":"M2-2-u4-X06"},{"t":"12시 — 열두 시","mis":"M2-2-u4-X01"}],"explanation":["긴바늘이 12를 가리키면 「몇 시」예요.","짧은바늘이 7을 가리키니 7시예요.","7시는 「칠 시」가 아니라 「일곱 시」라고 읽어요."],"asset":{"type":"clock2","h":7,"m":0},"variant_rule":{"alt":[{"stem":"짧은바늘이 8과 9 가운데, 긴바늘이 6을 가리켜요. 시각을 바르게 쓰고 읽은 것은 어느 것인가요?","options":[{"t":"8시 30분 — 여덟 시 삼십 분","correct":true},{"t":"8시 30분 — 팔 시 삼십 분","mis":"M2-2-u4-X06"},{"t":"9시 30분 — 아홉 시 삼십 분","mis":"M2-2-u4-X03"}],"explanation":["긴바늘이 6을 가리키면 30분이에요.","짧은바늘이 8과 9 가운데라 8시가 지났어요 — 8시 30분이에요.","「여덟 시 삼십 분」이라고 읽어요 — 시는 「한, 두, 세」, 분은 「일, 이, 삼」이에요."],"asset":{"type":"clock2","h":8,"m":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_basic#2','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'mc','auto','시계의 긴바늘이 가리키는 숫자가 1이면 5분, 2이면 10분이에요. 긴바늘이 숫자 3을 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"시계의 긴바늘이 가리키는 숫자가 1이면 5분, 2이면 10분이에요. 긴바늘이 숫자 3을 가리키면 몇 분인가요?","options":[{"t":"15분","correct":true},{"t":"3분","mis":"M2-2-u4-X02"},{"t":"20분","mis":"M2-2-u4-X04"}],"explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 3까지 5분씩 3번 가요.","5, 10, 15 — 15분이에요."],"variant_rule":{"alt":[{"stem":"시계의 긴바늘이 가리키는 숫자가 1이면 5분이에요. 긴바늘이 숫자 5를 가리키면 몇 분인가요?","options":[{"t":"25분","correct":true},{"t":"5분","mis":"M2-2-u4-X02"},{"t":"30분","mis":"M2-2-u4-X04"}],"explanation":["숫자 하나마다 5분씩 늘어나요.","5, 10, 15, 20, 25 — 5분씩 5번이에요.","그래서 25분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_basic#3','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'mc','auto','지아가 일어나서 시계를 보고 「7시가 조금 지났네. 긴바늘이 숫자 2를 가리키고 있어.」라고 했어요. 지아가 일어난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X01','M2-2-u4-X03']::text[],false,'{"seq":3,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"지아가 일어나서 시계를 보고 「7시가 조금 지났네. 긴바늘이 숫자 2를 가리키고 있어.」라고 했어요. 지아가 일어난 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 10분","correct":true},{"t":"7시 2분","mis":"M2-2-u4-X02"},{"t":"2시 35분","mis":"M2-2-u4-X01"},{"t":"8시 10분","mis":"M2-2-u4-X03"}],"explanation":["7시가 조금 지났으니 짧은바늘은 7과 8 사이예요.","긴바늘이 숫자 2를 가리키면 10분이에요.","그래서 지아가 일어난 시각은 7시 10분이에요."],"asset":{"type":"clock2","h":7,"m":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_basic#4','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 2시 몇 분인가요? 분만 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 2시 몇 분인가요? 분만 쓰세요.","answer":["20"],"explanation":["짧은바늘이 2와 3 사이라 2시가 지났어요.","긴바늘이 숫자 4를 가리키니 5분씩 4번 — 20분이에요.","2시 20분은 「두 시 이십 분」이라고 읽어요."],"asset":{"type":"clock2","h":2,"m":20},"variant_rule":{"alt":[{"stem":"시계가 나타내는 시각은 7시 몇 분인가요? 분만 쓰세요.","answer":["25"],"explanation":["짧은바늘이 7과 8 사이라 7시가 지났어요.","긴바늘이 숫자 5를 가리키니 5분씩 5번 — 25분이에요.","7시 25분은 「일곱 시 이십오 분」이라고 읽어요."],"asset":{"type":"clock2","h":7,"m":25}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_basic#5','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C2',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],false,'{"seq":5,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"열 시 삼십오 분","correct":true},{"t":"십 시 삼십오 분","mis":"M2-2-u4-X06"},{"t":"삼십오 시 열 분","mis":"M2-2-u4-X06"}],"explanation":["「:」 왼쪽 10은 시, 오른쪽 35는 분이에요.","시는 「열 시」, 분은 「삼십오 분」이라고 읽어요.","그래서 「열 시 삼십오 분」이에요."],"asset":{"type":"digital","h":10,"m":35}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_basic#6','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',2,'mc','auto','지아가 일어난 시각(7시 10분)의 시계에서 짧은바늘은 어디를 가리키나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X03']::text[],false,'{"seq":6,"concept":"M2-2-u4-C1","difficulty":2,"kind":"mc","stem":"지아가 일어난 시각(7시 10분)의 시계에서 짧은바늘은 어디를 가리키나요?","options":[{"t":"숫자 7과 8 사이","correct":true},{"t":"숫자 2","mis":"M2-2-u4-X01"},{"t":"숫자 8","mis":"M2-2-u4-X03"}],"explanation":["짧은바늘은 시를 나타내요.","7시가 조금 지났으니 숫자 7과 8 사이에 있어요.","숫자 2를 가리키는 것은 긴바늘이에요."],"asset":{"type":"clock2","h":7,"m":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_basic#7','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',2,'ox','auto','시계에서 긴바늘이 가리키는 작은 눈금 한 칸은 5분을 나타내요.',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":7,"concept":"M2-2-u4-C1","difficulty":2,"kind":"ox","stem":"시계에서 긴바늘이 가리키는 작은 눈금 한 칸은 5분을 나타내요.","answer":"X","reason_options":[{"t":"작은 눈금 한 칸은 1분이고, 작은 눈금 5칸(숫자와 숫자 사이)이 5분이니까","correct":true},{"t":"숫자 1이 5분이니까 작은 눈금 한 칸도 5분이니까","mis":"M2-2-u4-X02"}],"mis":"M2-2-u4-X02","explanation":["작은 눈금 한 칸은 1분이에요.","숫자와 숫자 사이에는 작은 눈금이 5칸 있어서 5분이에요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"시계에서 숫자와 숫자 사이에는 작은 눈금이 5칸 있어서 5분이에요.","answer":"O","reason_options":[{"t":"작은 눈금 한 칸이 1분이라 5칸이면 5분이니까","correct":true},{"t":"숫자와 숫자 사이는 한 칸이라 1분이니까","mis":"M2-2-u4-X02"}],"explanation":["작은 눈금 한 칸은 1분이에요.","숫자와 숫자 사이에는 작은 눈금이 5칸 있어요.","그래서 숫자와 숫자 사이는 5분 — 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_basic#8','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',2,'match','auto','시계의 바늘과 학교에서 한 일을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C1","difficulty":2,"kind":"match","stem":"시계의 바늘과 학교에서 한 일을 알맞게 이어 보세요.","pairs":[{"l":"짧은바늘 8과 9 사이 · 긴바늘 숫자 7","r":"8시 35분 — 교실에 들어와 인사"},{"l":"짧은바늘 10과 11 사이 · 긴바늘 숫자 8","r":"10시 40분 — 운동장에서 줄넘기"},{"l":"짧은바늘 12와 1 사이 · 긴바늘 숫자 5","r":"12시 25분 — 친구들과 수학 공부"}],"mis":"M2-2-u4-X02","explanation":["긴바늘 숫자 7은 35분, 8은 40분, 5는 25분이에요.","짧은바늘이 지나온 숫자가 시 — 8시, 10시, 12시예요.","그래서 8시 35분, 10시 40분, 12시 25분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_basic#9','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',2,'mc','auto','8시 35분에 교실로 들어와서 친구들과 인사를 했어요. 8시 35분을 시계에 나타낼 때 긴바늘은 어느 숫자를 가리키나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X02']::text[],true,'{"seq":9,"concept":"M2-2-u4-C1","difficulty":2,"kind":"mc","stem":"8시 35분에 교실로 들어와서 친구들과 인사를 했어요. 8시 35분을 시계에 나타낼 때 긴바늘은 어느 숫자를 가리키나요?","options":[{"t":"7","correct":true},{"t":"8","mis":"M2-2-u4-X01"},{"t":"3","mis":"M2-2-u4-X02"}],"explanation":["35분은 5분씩 7번이에요.","5, 10, 15, 20, 25, 30, 35 — 숫자 7까지 가요.","숫자 8은 짧은바늘이 지나온 숫자예요."],"variant_rule":{"alt":[{"stem":"10시 40분에 운동장에서 줄넘기를 했어요. 10시 40분을 시계에 나타낼 때 긴바늘은 어느 숫자를 가리키나요?","options":[{"t":"8","correct":true},{"t":"10","mis":"M2-2-u4-X01"},{"t":"4","mis":"M2-2-u4-X02"}],"explanation":["40분은 5분씩 8번이에요.","그래서 긴바늘은 숫자 8을 가리켜요.","숫자 10은 짧은바늘이 지나온 숫자예요."]},{"stem":"12시 25분에 친구들과 수학 공부를 했어요. 12시 25분을 시계에 나타낼 때 긴바늘은 어느 숫자를 가리키나요?","options":[{"t":"5","correct":true},{"t":"12","mis":"M2-2-u4-X01"},{"t":"2","mis":"M2-2-u4-X02"}],"explanation":["25분은 5분씩 5번이에요.","그래서 긴바늘은 숫자 5를 가리켜요.","숫자 12는 짧은바늘이 지나온 숫자예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_basic#10','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',3,'error','auto','슬기가 「지금 몇 시 몇 분일까?」 하고 물었어요. 연우는 「긴바늘이 3을 가리키고 있으니까 7시 3분이야.」라고 했어요. 연우가 잘못 읽은 부분을 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X01']::text[],false,'{"seq":10,"concept":"M2-2-u4-C1","difficulty":3,"kind":"error","stem":"슬기가 「지금 몇 시 몇 분일까?」 하고 물었어요. 연우는 「긴바늘이 3을 가리키고 있으니까 7시 3분이야.」라고 했어요. 연우가 잘못 읽은 부분을 바르게 말한 것은 어느 것인가요?","options":[{"t":"긴바늘 숫자 3을 그대로 3분으로 읽었어요 — 바른 시각은 7시 15분","correct":true,"mis_target":"M2-2-u4-X02"},{"t":"짧은바늘과 긴바늘을 바꾸어 읽었어요 — 바른 시각은 3시 35분","mis":"M2-2-u4-X01"},{"t":"잘못 읽지 않았어요 — 7시 3분이 맞아요","mis":"M2-2-u4-X02"}],"explanation":["짧은바늘이 7과 8 사이라 7시예요.","긴바늘이 숫자 3을 가리키면 5분씩 3번 — 15분이에요.","연우는 숫자 3을 그대로 3분으로 읽었어요 — 바른 시각은 7시 15분이에요."],"asset":{"type":"clock2","h":7,"m":15}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_challenge#1','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',2,'mc','auto','건강 공원 시계탑은 긴바늘이 가려져 있고 짧은바늘은 9와 10 사이예요. 경기장 디지털시계는 9 : 30이에요. 지금은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X03','M2-2-u4-X06']::text[],false,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":2,"kind":"mc","stem":"건강 공원 시계탑은 긴바늘이 가려져 있고 짧은바늘은 9와 10 사이예요. 경기장 디지털시계는 9 : 30이에요. 지금은 몇 시 몇 분인가요?","options":[{"t":"9시 30분","correct":true},{"t":"10시 30분","mis":"M2-2-u4-X03"},{"t":"30시 9분","mis":"M2-2-u4-X06"}],"explanation":["디지털시계의 「:」 왼쪽 9는 시, 오른쪽 30은 분이에요.","시계탑의 짧은바늘도 9와 10 사이 — 9시가 지났어요.","그래서 지금은 9시 30분이에요."],"asset":{"type":"digital","h":9,"m":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_challenge#2','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C2',2,'mc','auto','디지털시계가 10 : 35를 나타내요. 같은 시각을 바늘 시계에 나타내면 긴바늘은 어느 숫자를 가리키나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X02']::text[],false,'{"seq":2,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계가 10 : 35를 나타내요. 같은 시각을 바늘 시계에 나타내면 긴바늘은 어느 숫자를 가리키나요?","options":[{"t":"7","correct":true},{"t":"10","mis":"M2-2-u4-X01"},{"t":"3","mis":"M2-2-u4-X02"}],"explanation":["「:」 오른쪽 35가 분이에요.","35분은 5분씩 7번이라 긴바늘은 숫자 7을 가리켜요.","시 10은 짧은바늘이 나타내요."],"asset":{"type":"digital","h":10,"m":35}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_challenge#3','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'mc','auto','『수학익힘』에서 5씩 뛰어 세었어요. 0, 5, 10, 15, 20, … 처럼 긴바늘이 숫자 8을 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04']::text[],true,'{"seq":3,"concept":"M2-2-u4-C1","difficulty":3,"kind":"mc","stem":"『수학익힘』에서 5씩 뛰어 세었어요. 0, 5, 10, 15, 20, … 처럼 긴바늘이 숫자 8을 가리키면 몇 분인가요?","options":[{"t":"40분","correct":true},{"t":"8분","mis":"M2-2-u4-X02"},{"t":"45분","mis":"M2-2-u4-X04"},{"t":"35분","mis":"M2-2-u4-X04"}],"explanation":["긴바늘이 가리키는 숫자가 하나씩 커질 때마다 5분씩 늘어나요.","숫자 8까지 5씩 8번 뛰어 세면 40이에요.","그래서 40분이에요."],"variant_rule":{"alt":[{"stem":"5씩 뛰어 세어 분을 읽어요. 긴바늘이 숫자 11을 가리키면 몇 분인가요?","options":[{"t":"55분","correct":true},{"t":"11분","mis":"M2-2-u4-X02"},{"t":"50분","mis":"M2-2-u4-X04"},{"t":"60분","mis":"M2-2-u4-X04"}],"explanation":["숫자 하나마다 5분씩 늘어나요.","숫자 11까지 5씩 11번 뛰어 세면 55예요.","그래서 55분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_challenge#4','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'mc','auto','7시 25분을 시계에 나타냈어요. 짧은바늘은 어디를 가리키나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X03']::text[],false,'{"seq":4,"concept":"M2-2-u4-C1","difficulty":3,"kind":"mc","stem":"7시 25분을 시계에 나타냈어요. 짧은바늘은 어디를 가리키나요?","options":[{"t":"숫자 7과 8 사이","correct":true},{"t":"숫자 5","mis":"M2-2-u4-X01"},{"t":"숫자 8과 9 사이","mis":"M2-2-u4-X03"},{"t":"숫자 7을 똑바로","mis":"M2-2-u4-X03"}],"explanation":["짧은바늘은 시를 나타내요.","7시가 지나 25분이 흘렀으니 짧은바늘은 7을 지나 8 쪽으로 조금 갔어요.","그래서 숫자 7과 8 사이예요 — 숫자 5는 긴바늘이 가리켜요."],"asset":{"type":"clock2","h":7,"m":25}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_challenge#5','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'sa','auto','운동장에서 줄넘기를 한 시각이에요. 시계가 나타내는 시각은 10시 몇 분인가요? 분만 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C1","difficulty":3,"kind":"sa","stem":"운동장에서 줄넘기를 한 시각이에요. 시계가 나타내는 시각은 10시 몇 분인가요? 분만 쓰세요.","answer":["40"],"explanation":["짧은바늘이 10과 11 사이라 10시가 지났어요.","긴바늘이 숫자 8을 가리키니 5분씩 8번 — 40분이에요.","그래서 10시 40분이에요."],"asset":{"type":"clock2","h":10,"m":40},"variant_rule":{"alt":[{"stem":"친구들과 수학 공부를 한 시각이에요. 시계가 나타내는 시각은 12시 몇 분인가요? 분만 쓰세요.","answer":["25"],"explanation":["짧은바늘이 12와 1 사이라 12시가 지났어요.","긴바늘이 숫자 5를 가리키니 5분씩 5번 — 25분이에요.","그래서 12시 25분이에요."],"asset":{"type":"clock2","h":12,"m":25}},{"stem":"교실에 들어와 친구들과 인사를 한 시각이에요. 시계가 나타내는 시각은 8시 몇 분인가요? 분만 쓰세요.","answer":["35"],"explanation":["짧은바늘이 8과 9 사이라 8시가 지났어요.","긴바늘이 숫자 7을 가리키니 5분씩 7번 — 35분이에요.","그래서 8시 35분이에요."],"asset":{"type":"clock2","h":8,"m":35}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_challenge#6','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C2',3,'mc','auto','디지털시계와 같은 시각을 나타낸 바늘 시계는 어느 것인가요?',ARRAY['M2-2-u4-X01','M2-2-u4-X03','M2-2-u4-X02']::text[],false,'{"seq":6,"concept":"M2-2-u4-C2","difficulty":3,"kind":"mc","stem":"디지털시계와 같은 시각을 나타낸 바늘 시계는 어느 것인가요?","options":[{"t":"짧은바늘은 12와 1 사이, 긴바늘은 숫자 5","correct":true},{"t":"짧은바늘은 숫자 5, 긴바늘은 숫자 12","mis":"M2-2-u4-X01"},{"t":"짧은바늘은 1과 2 사이, 긴바늘은 숫자 5","mis":"M2-2-u4-X03"},{"t":"짧은바늘은 12와 1 사이, 긴바늘은 숫자 2","mis":"M2-2-u4-X02"}],"explanation":["디지털시계의 시각은 12시 25분이에요.","12시가 지났으니 짧은바늘은 12와 1 사이예요.","25분은 5분씩 5번 — 긴바늘은 숫자 5를 가리켜요."],"asset":{"type":"digital","h":12,"m":25}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_challenge#7','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'ox','auto','3시 30분을 시계에 나타낼 때 짧은바늘은 숫자 3을 똑바로 가리켜요.',ARRAY['M2-2-u4-X03']::text[],false,'{"seq":7,"concept":"M2-2-u4-C1","difficulty":3,"kind":"ox","stem":"3시 30분을 시계에 나타낼 때 짧은바늘은 숫자 3을 똑바로 가리켜요.","answer":"X","reason_options":[{"t":"30분이 지나 짧은바늘은 3과 4 가운데를 가리키니까","correct":true},{"t":"몇 분이든 짧은바늘은 시의 숫자를 똑바로 가리키니까","mis":"M2-2-u4-X03"}],"mis":"M2-2-u4-X03","explanation":["짧은바늘은 긴바늘이 움직이는 만큼 다음 숫자 쪽으로 조금씩 가요.","3시 30분에는 3과 4 가운데를 가리켜요.","정각일 때만 숫자를 똑바로 가리켜요 — 2시에는 숫자 2를 똑바로 가리켜요."],"asset":{"type":"clock2","h":3,"m":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_challenge#8','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',4,'essay','teacher','지아는 이 시계를 보고 「7시 10분」이라고 읽었어요. 짧은바늘과 긴바늘을 각각 어떻게 보고 읽었는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C1","difficulty":4,"kind":"essay","stem":"지아는 이 시계를 보고 「7시 10분」이라고 읽었어요. 짧은바늘과 긴바늘을 각각 어떻게 보고 읽었는지 설명해 보세요.","answer_guide":{"answer":"예: 짧은바늘이 숫자 7과 8 사이를 가리키므로 7시가 지났다. 긴바늘이 숫자 2를 가리키고, 숫자 1이 5분이므로 숫자 2는 10분이다. 그래서 7시 10분이다.","scoring_points":["짧은바늘이 7과 8 사이라 7시라고 썼는가","긴바늘 숫자 2가 10분임을 5분씩 세어 썼는가","7시 10분이라고 바르게 썼는가"]},"explanation":["짧은바늘은 시, 긴바늘은 분을 나타내요.","짧은바늘이 7과 8 사이 — 7시예요.","긴바늘 숫자 2는 5분씩 2번 — 10분이에요."],"asset":{"type":"clock2","h":7,"m":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_challenge#9','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',4,'essay','teacher','이 시계를 보고 한 친구는 「2시 4분」, 다른 친구는 「4시 2분」이라고 읽었어요. 두 친구가 각각 무엇을 잘못했는지 쓰고, 바르게 읽어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C1","difficulty":4,"kind":"essay","stem":"이 시계를 보고 한 친구는 「2시 4분」, 다른 친구는 「4시 2분」이라고 읽었어요. 두 친구가 각각 무엇을 잘못했는지 쓰고, 바르게 읽어 보세요.","answer_guide":{"answer":"예: 「2시 4분」은 긴바늘이 가리키는 숫자 4를 그대로 분으로 읽었다. 「4시 2분」은 짧은바늘과 긴바늘을 바꾸어 읽었다. 긴바늘 숫자 4는 20분이므로 바른 시각은 2시 20분(두 시 이십 분)이다.","scoring_points":["「2시 4분」이 숫자를 그대로 분으로 읽은 잘못임을 썼는가","「4시 2분」이 두 바늘을 바꾸어 읽은 잘못임을 썼는가","2시 20분으로 바르게 읽었는가"]},"explanation":["짧은바늘은 시, 긴바늘은 분이에요.","긴바늘이 가리키는 숫자 4는 5분씩 4번 — 20분이에요.","그래서 바른 시각은 2시 20분이에요."],"asset":{"type":"clock2","h":2,"m":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L02_challenge#10','math',2,2,'u4','L02','tb_g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',4,'mc','auto','8시 35분에 교실로 들어왔어요. 친구들과 인사를 하는 동안 긴바늘이 숫자 한 칸만큼 더 갔어요. 인사를 마친 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04','M2-2-u4-X11']::text[],false,'{"seq":10,"concept":"M2-2-u4-C1","difficulty":4,"kind":"mc","stem":"8시 35분에 교실로 들어왔어요. 친구들과 인사를 하는 동안 긴바늘이 숫자 한 칸만큼 더 갔어요. 인사를 마친 시각은 몇 시 몇 분인가요?","options":[{"t":"8시 40분","correct":true},{"t":"8시 36분","mis":"M2-2-u4-X02"},{"t":"8시 45분","mis":"M2-2-u4-X04"},{"t":"9시 35분","mis":"M2-2-u4-X11"}],"explanation":["긴바늘이 숫자 한 칸을 가면 5분이 지나요.","8시 35분에서 5분이 지나면 8시 40분이에요.","긴바늘은 숫자 7에서 8로 갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_basic#1','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'mc','auto','모형 시계로 1시 10분을 나타낸 다음 긴바늘을 작은 눈금 3칸만큼 움직였어요. 시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04']::text[],false,'{"seq":1,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"모형 시계로 1시 10분을 나타낸 다음 긴바늘을 작은 눈금 3칸만큼 움직였어요. 시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"1시 13분","correct":true},{"t":"1시 25분","mis":"M2-2-u4-X02"},{"t":"1시 12분","mis":"M2-2-u4-X04"}],"explanation":["긴바늘이 가리키는 작은 눈금 한 칸은 1분이에요.","1시 10분에서 3칸 더 가면 3분이 더 지나요.","10 + 3 = 13 — 1시 13분이에요."],"asset":{"type":"clock2","h":1,"m":13}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_basic#2','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'mc','auto','긴바늘이 작은 눈금 3칸을 움직이면 몇 분이 지나나요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04']::text[],true,'{"seq":2,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"긴바늘이 작은 눈금 3칸을 움직이면 몇 분이 지나나요?","options":[{"t":"3분","correct":true},{"t":"15분","mis":"M2-2-u4-X02"},{"t":"13분","mis":"M2-2-u4-X04"}],"explanation":["작은 눈금 한 칸은 1분이에요.","3칸이면 1분씩 3번이에요.","그래서 3분이 지나요 — 숫자 3까지 가는 15분과 달라요."],"variant_rule":{"alt":[{"stem":"긴바늘이 작은 눈금 2칸을 움직이면 몇 분이 지나나요?","options":[{"t":"2분","correct":true},{"t":"10분","mis":"M2-2-u4-X02"},{"t":"12분","mis":"M2-2-u4-X04"}],"explanation":["작은 눈금 한 칸은 1분이에요.","2칸이면 1분씩 2번이에요.","그래서 2분이 지나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_basic#3','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'sa','auto','시계가 나타내는 시각은 7시 몇 분인가요? 분만 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C3","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 7시 몇 분인가요? 분만 쓰세요.","answer":["22"],"explanation":["긴바늘이 숫자 4(20분)에서 작은 눈금 2칸 더 간 곳을 가리켜요.","20 + 2 = 22예요.","7시 22분은 「일곱 시 이십이 분」이라고 읽어요."],"asset":{"type":"clock2","h":7,"m":22},"variant_rule":{"alt":[{"stem":"시계가 나타내는 시각은 3시 몇 분인가요? 분만 쓰세요.","answer":["39"],"explanation":["긴바늘이 숫자 7(35분)에서 작은 눈금 4칸 더 간 곳을 가리켜요.","35 + 4 = 39예요.","3시 39분은 「세 시 삼십구 분」이라고 읽어요."],"asset":{"type":"clock2","h":3,"m":39}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_basic#4','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'mc','auto','긴바늘이 숫자 4와 5 사이를 가리키고 있어요. 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X04','M2-2-u4-X02']::text[],false,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 4와 5 사이를 가리키고 있어요. 시각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"7시 22분","correct":true},{"t":"7시 20분","mis":"M2-2-u4-X04"},{"t":"7시 6분","mis":"M2-2-u4-X02"}],"explanation":["숫자 4는 20분이에요.","긴바늘은 숫자 4에서 작은 눈금 2칸 더 간 곳 — 22분이에요.","가까운 숫자만 보고 20분으로 읽거나, 4 + 2 = 6분으로 읽지 않아요."],"asset":{"type":"clock2","h":7,"m":22}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_basic#5','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C2',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],false,'{"seq":5,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"열한 시 사십삼 분","correct":true},{"t":"십일 시 사십삼 분","mis":"M2-2-u4-X06"},{"t":"열한 시 마흔세 분","mis":"M2-2-u4-X06"}],"explanation":["「:」 왼쪽 11은 시, 오른쪽 43은 분이에요.","시는 「열한 시」, 분은 「사십삼 분」이라고 읽어요.","그래서 「열한 시 사십삼 분」이에요."],"asset":{"type":"digital","h":11,"m":43}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_basic#6','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'mc','auto','긴바늘이 숫자 8에서 작은 눈금 1칸 덜 간 곳을 가리키고, 짧은바늘은 3과 4 사이예요. 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X05','M2-2-u4-X03','M2-2-u4-X04']::text[],false,'{"seq":6,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"긴바늘이 숫자 8에서 작은 눈금 1칸 덜 간 곳을 가리키고, 짧은바늘은 3과 4 사이예요. 몇 시 몇 분인가요?","options":[{"t":"3시 39분","correct":true},{"t":"3시 41분","mis":"M2-2-u4-X05"},{"t":"4시 39분","mis":"M2-2-u4-X03"},{"t":"3시 40분","mis":"M2-2-u4-X04"}],"explanation":["숫자 8은 40분이에요.","1칸 덜 갔으니 40 − 1 = 39분이에요.","짧은바늘이 3과 4 사이라 3시 — 3시 39분이에요."],"asset":{"type":"clock2","h":3,"m":39}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_basic#7','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'mc','auto','긴바늘이 숫자 7에서 작은 눈금 4칸 더 간 곳은 숫자 8에서 몇 칸 덜 간 곳과 같나요?',ARRAY['M2-2-u4-X05','M2-2-u4-X04']::text[],false,'{"seq":7,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"긴바늘이 숫자 7에서 작은 눈금 4칸 더 간 곳은 숫자 8에서 몇 칸 덜 간 곳과 같나요?","options":[{"t":"1칸","correct":true},{"t":"4칸","mis":"M2-2-u4-X05"},{"t":"5칸","mis":"M2-2-u4-X04"}],"explanation":["숫자와 숫자 사이는 작은 눈금 5칸이에요.","7에서 4칸 더 갔으니 8까지 1칸 남았어요.","그래서 숫자 8에서 1칸 덜 간 곳 — 39분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_basic#8','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'ox','auto','긴바늘이 숫자 4와 5 사이를 가리키면 몇 시 20분으로 읽어요.',ARRAY['M2-2-u4-X04']::text[],false,'{"seq":8,"concept":"M2-2-u4-C3","difficulty":2,"kind":"ox","stem":"긴바늘이 숫자 4와 5 사이를 가리키면 몇 시 20분으로 읽어요.","answer":"X","reason_options":[{"t":"숫자 4(20분)에서 작은 눈금이 몇 칸 더 갔는지 세어 분을 더해야 하니까","correct":true},{"t":"가까운 숫자 4만 보고 읽으면 되니까","mis":"M2-2-u4-X04"}],"mis":"M2-2-u4-X04","explanation":["숫자 4는 20분이에요.","숫자와 숫자 사이를 가리키면 작은 눈금을 더 세어야 해요.","그래서 틀린 말이에요 — 2칸 더 갔다면 22분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_basic#9','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'match','auto','시각 읽기 놀이에서 친구가 모형 시계에 나타낸 바늘과 읽은 시각을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C3","difficulty":2,"kind":"match","stem":"시각 읽기 놀이에서 친구가 모형 시계에 나타낸 바늘과 읽은 시각을 알맞게 이어 보세요.","pairs":[{"l":"짧은바늘 1과 2 사이 · 긴바늘 숫자 2에서 3칸 더","r":"1시 13분"},{"l":"짧은바늘 7과 8 사이 · 긴바늘 숫자 4에서 2칸 더","r":"7시 22분"},{"l":"짧은바늘 3과 4 사이 · 긴바늘 숫자 8에서 1칸 덜","r":"3시 39분"}],"mis":"M2-2-u4-X05","explanation":["숫자 2는 10분 — 3칸 더 가서 13분이에요.","숫자 4는 20분 — 2칸 더 가서 22분이에요.","숫자 8은 40분 — 1칸 덜 가서 39분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_basic#10','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',3,'error','auto','시각 읽기 놀이에서 모형 시계의 시각을 친구들이 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['M2-2-u4-X04','M2-2-u4-X16']::text[],false,'{"seq":10,"concept":"M2-2-u4-C3","difficulty":3,"kind":"error","stem":"시각 읽기 놀이에서 모형 시계의 시각을 친구들이 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"도윤 — 「긴바늘이 8과 9 사이니까 11시 40분이야.」","correct":true,"mis_target":"M2-2-u4-X04"},{"t":"서아 — 「숫자 8에서 3칸 더 갔으니 11시 43분이야.」","mis":"M2-2-u4-X16"},{"t":"하루 — 「숫자 9에서 2칸 덜 간 곳이라 11시 43분이야.」","mis":"M2-2-u4-X16"}],"explanation":["긴바늘은 숫자 8(40분)에서 작은 눈금 3칸 더 간 곳이에요.","40 + 3 = 43 — 숫자 9(45분)에서 2칸 덜 간 곳과 같아요.","도윤이는 3칸 더 간 것을 빠뜨렸어요 — 11시 43분이에요."],"asset":{"type":"clock2","h":11,"m":43}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_challenge#1','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',2,'mc','auto','1시 13분을 시계에 나타낼 때 긴바늘은 어디를 가리키나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X04']::text[],false,'{"seq":1,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"1시 13분을 시계에 나타낼 때 긴바늘은 어디를 가리키나요?","options":[{"t":"숫자 2에서 작은 눈금 3칸 더 간 곳","correct":true},{"t":"숫자 1에서 작은 눈금 3칸 더 간 곳","mis":"M2-2-u4-X01"},{"t":"숫자 3에서 작은 눈금 3칸 더 간 곳","mis":"M2-2-u4-X04"}],"explanation":["13분은 10분과 3분이에요.","10분은 숫자 2 — 거기서 작은 눈금 3칸 더 가요.","숫자 1은 짧은바늘이 지나온 숫자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_challenge#2','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',2,'sa','auto','두 사람이 본 시계예요. 「짧은바늘은 3과 4 사이를 가리키고 있어.」 「긴바늘은 7에서 작은 눈금 2칸만큼 더 간 곳을 가리키고 있어.」 시각은 3시 몇 분인가요? 분만 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C3","difficulty":2,"kind":"sa","stem":"두 사람이 본 시계예요. 「짧은바늘은 3과 4 사이를 가리키고 있어.」 「긴바늘은 7에서 작은 눈금 2칸만큼 더 간 곳을 가리키고 있어.」 시각은 3시 몇 분인가요? 분만 쓰세요.","answer":["37"],"explanation":["짧은바늘이 3과 4 사이라 3시예요.","숫자 7은 35분 — 2칸 더 가서 37분이에요.","그래서 3시 37분이에요."],"asset":{"type":"clock2","h":3,"m":37},"variant_rule":{"alt":[{"stem":"「짧은바늘은 3과 4 사이를 가리키고 있어.」 「긴바늘은 7에서 작은 눈금 3칸만큼 더 간 곳을 가리키고 있어.」 시각은 3시 몇 분인가요? 분만 쓰세요.","answer":["38"],"explanation":["짧은바늘이 3과 4 사이라 3시예요.","숫자 7은 35분 — 3칸 더 가서 38분이에요.","그래서 3시 38분이에요."],"asset":{"type":"clock2","h":3,"m":38}},{"stem":"「짧은바늘은 3과 4 사이를 가리키고 있어.」 「긴바늘은 7에서 작은 눈금 1칸만큼 더 간 곳을 가리키고 있어.」 시각은 3시 몇 분인가요? 분만 쓰세요.","answer":["36"],"explanation":["짧은바늘이 3과 4 사이라 3시예요.","숫자 7은 35분 — 1칸 더 가서 36분이에요.","그래서 3시 36분이에요."],"asset":{"type":"clock2","h":3,"m":36}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_challenge#3','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','「짧은바늘은 3과 4 사이, 긴바늘은 7에서 작은 눈금 □칸만큼 더 간 곳」이에요. □에는 1부터 4까지의 수 가운데 하나가 들어가요. 이 시계가 나타낼 수 없는 시각은 어느 것인가요?',ARRAY['M2-2-u4-X16']::text[],false,'{"seq":3,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"「짧은바늘은 3과 4 사이, 긴바늘은 7에서 작은 눈금 □칸만큼 더 간 곳」이에요. □에는 1부터 4까지의 수 가운데 하나가 들어가요. 이 시계가 나타낼 수 없는 시각은 어느 것인가요?","options":[{"t":"3시 40분","correct":true},{"t":"3시 36분","mis":"M2-2-u4-X16"},{"t":"3시 39분","mis":"M2-2-u4-X16"}],"explanation":["숫자 7은 35분이라 1칸부터 4칸까지 더 가면 36분, 37분, 38분, 39분이에요.","40분은 숫자 8 — 7에서 5칸 더 간 곳이에요.","그래서 나타낼 수 없는 시각은 3시 40분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_challenge#4','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','짧은바늘은 11과 12 사이, 긴바늘은 숫자 9에서 작은 눈금 4칸 더 간 곳을 가리켜요. 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X03','M2-2-u4-X05','M2-2-u4-X02']::text[],false,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"짧은바늘은 11과 12 사이, 긴바늘은 숫자 9에서 작은 눈금 4칸 더 간 곳을 가리켜요. 몇 시 몇 분인가요?","options":[{"t":"11시 49분","correct":true},{"t":"12시 49분","mis":"M2-2-u4-X03"},{"t":"11시 41분","mis":"M2-2-u4-X05"},{"t":"11시 13분","mis":"M2-2-u4-X02"}],"explanation":["짧은바늘이 11과 12 사이라 아직 11시예요.","숫자 9는 45분 — 4칸 더 가서 49분이에요.","그래서 11시 49분이에요."],"asset":{"type":"clock2","h":11,"m":49}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_challenge#5','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C2',3,'mc','auto','디지털시계의 시각을 바늘 시계로 나타낼 때 긴바늘은 어디를 가리키나요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04','M2-2-u4-X05']::text[],false,'{"seq":5,"concept":"M2-2-u4-C2","difficulty":3,"kind":"mc","stem":"디지털시계의 시각을 바늘 시계로 나타낼 때 긴바늘은 어디를 가리키나요?","options":[{"t":"숫자 8에서 작은 눈금 3칸 더 간 곳","correct":true},{"t":"숫자 4와 3 사이","mis":"M2-2-u4-X02"},{"t":"숫자 9에서 작은 눈금 3칸 더 간 곳","mis":"M2-2-u4-X04"},{"t":"숫자 8에서 작은 눈금 3칸 덜 간 곳","mis":"M2-2-u4-X05"}],"explanation":["디지털시계의 시각은 11시 43분이에요.","40분은 숫자 8이고 3분이 더 있어요.","그래서 숫자 8에서 3칸 더 간 곳이에요."],"asset":{"type":"digital","h":11,"m":43}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_challenge#6','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'ox','auto','긴바늘이 숫자 7에서 작은 눈금 4칸 더 간 곳과 숫자 8에서 작은 눈금 1칸 덜 간 곳은 같아요.',ARRAY['M2-2-u4-X05']::text[],false,'{"seq":6,"concept":"M2-2-u4-C3","difficulty":3,"kind":"ox","stem":"긴바늘이 숫자 7에서 작은 눈금 4칸 더 간 곳과 숫자 8에서 작은 눈금 1칸 덜 간 곳은 같아요.","answer":"O","reason_options":[{"t":"35 + 4 = 39, 40 − 1 = 39로 같은 곳이니까","correct":true},{"t":"더 간 곳과 덜 간 곳은 언제나 다른 곳이니까","mis":"M2-2-u4-X05"}],"mis":"M2-2-u4-X05","explanation":["숫자 7은 35분이라 4칸 더 가면 39분이에요.","숫자 8은 40분이라 1칸 덜 가면 39분이에요.","둘 다 39분 — 같은 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_challenge#7','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','시각 읽기 놀이에서 지아가 7시 22분을 나타냈어요. 다음 친구는 긴바늘을 작은 눈금 5칸 더 돌려 나타냈어요. 다음 친구가 나타낸 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04','M2-2-u4-X11']::text[],false,'{"seq":7,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시각 읽기 놀이에서 지아가 7시 22분을 나타냈어요. 다음 친구는 긴바늘을 작은 눈금 5칸 더 돌려 나타냈어요. 다음 친구가 나타낸 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 27분","correct":true},{"t":"7시 47분","mis":"M2-2-u4-X02"},{"t":"7시 23분","mis":"M2-2-u4-X04"},{"t":"8시 22분","mis":"M2-2-u4-X11"}],"explanation":["작은 눈금 5칸은 5분이에요.","7시 22분에서 5분이 지나면 7시 27분이에요.","긴바늘은 숫자 4와 5 사이에서 숫자 5와 6 사이로 갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_challenge#8','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',4,'essay','teacher','긴바늘이 숫자 8에서 작은 눈금 1칸 덜 간 곳을 가리켜요. 몇 분인지 가까운 숫자에서 앞으로 세는 방법과 거꾸로 세는 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C3","difficulty":4,"kind":"essay","stem":"긴바늘이 숫자 8에서 작은 눈금 1칸 덜 간 곳을 가리켜요. 몇 분인지 가까운 숫자에서 앞으로 세는 방법과 거꾸로 세는 방법으로 설명해 보세요.","answer_guide":{"answer":"예: 앞으로 세기 — 숫자 7은 35분이고 거기서 4칸 더 갔으므로 35 + 4 = 39분이다. 거꾸로 세기 — 숫자 8은 40분이고 1칸 덜 갔으므로 40 − 1 = 39분이다.","scoring_points":["숫자 7(35분)에서 앞으로 세었는가","숫자 8(40분)에서 거꾸로 세었는가","39분이라고 구했는가"]},"explanation":["숫자 7에서 앞으로 4칸 — 35 + 4 = 39예요.","숫자 8에서 거꾸로 1칸 — 40 − 1 = 39예요.","두 방법 모두 39분이에요."],"asset":{"type":"clock2","h":3,"m":39}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_challenge#9','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',4,'essay','teacher','이 시계를 보고 한 친구는 「7시 20분」, 다른 친구는 「7시 6분」이라고 읽었어요. 두 친구가 각각 무엇을 잘못했는지 쓰고, 바르게 읽어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C3","difficulty":4,"kind":"essay","stem":"이 시계를 보고 한 친구는 「7시 20분」, 다른 친구는 「7시 6분」이라고 읽었어요. 두 친구가 각각 무엇을 잘못했는지 쓰고, 바르게 읽어 보세요.","answer_guide":{"answer":"예: 「7시 20분」은 긴바늘이 숫자 4와 5 사이인데 가까운 숫자 4만 보고 읽었다. 「7시 6분」은 숫자 4에 2칸을 그냥 더해 6으로 읽었다. 숫자 4는 20분이고 2칸 더 갔으므로 7시 22분이다.","scoring_points":["「7시 20분」이 작은 눈금을 세지 않은 잘못임을 썼는가","「7시 6분」이 숫자를 그대로 분으로 본 잘못임을 썼는가","7시 22분으로 바르게 읽었는가"]},"explanation":["숫자 4는 20분이에요.","긴바늘이 숫자 4에서 작은 눈금 2칸 더 갔어요.","20 + 2 = 22 — 7시 22분이에요."],"asset":{"type":"clock2","h":7,"m":22}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L03_challenge#10','math',2,2,'u4','L03','tb_g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',4,'mc','auto','모형 시계로 1시 10분을 나타냈어요. 긴바늘을 작은 눈금 3칸 움직이고, 다시 숫자 한 칸만큼 더 움직였어요. 시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04','M2-2-u4-X01']::text[],false,'{"seq":10,"concept":"M2-2-u4-C3","difficulty":4,"kind":"mc","stem":"모형 시계로 1시 10분을 나타냈어요. 긴바늘을 작은 눈금 3칸 움직이고, 다시 숫자 한 칸만큼 더 움직였어요. 시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"1시 18분","correct":true},{"t":"1시 14분","mis":"M2-2-u4-X02"},{"t":"1시 23분","mis":"M2-2-u4-X04"},{"t":"2시 13분","mis":"M2-2-u4-X01"}],"explanation":["작은 눈금 3칸은 3분 — 1시 13분이 돼요.","숫자 한 칸은 작은 눈금 5칸 — 5분이에요.","13 + 5 = 18 — 1시 18분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_basic#1','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'mc','auto','엄마께서 「곧 9시야.」라고 하셨어요. 시계는 8시 55분이에요. 몇 분 후에 9시가 되나요?',ARRAY['M2-2-u4-X08','M2-2-u4-X02']::text[],false,'{"seq":1,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"엄마께서 「곧 9시야.」라고 하셨어요. 시계는 8시 55분이에요. 몇 분 후에 9시가 되나요?","options":[{"t":"5분","correct":true},{"t":"55분","mis":"M2-2-u4-X08"},{"t":"11분","mis":"M2-2-u4-X02"}],"explanation":["긴바늘이 숫자 11에 있어요.","숫자 12까지 숫자 한 칸 — 5분이 더 지나야 해요.","그래서 5분 후에 9시가 돼요."],"asset":{"type":"clock2","h":8,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_basic#2','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'mc','auto','8시 55분을 다른 방법으로 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],false,'{"seq":2,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"8시 55분을 다른 방법으로 읽은 것은 어느 것인가요?","options":[{"t":"9시 5분 전","correct":true},{"t":"8시 5분 전","mis":"M2-2-u4-X07"},{"t":"9시 55분 전","mis":"M2-2-u4-X08"}],"explanation":["8시 55분에서 5분이 지나면 9시가 돼요.","9시가 되기 5분 전이에요.","그래서 8시 55분을 9시 5분 전이라고도 해요."],"asset":{"type":"digital","h":8,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_basic#3','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'sa','auto','3시 50분은 4시 몇 분 전인가요? 수만 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"3시 50분은 4시 몇 분 전인가요? 수만 쓰세요.","answer":["10"],"explanation":["3시 50분에서 10분이 지나면 4시가 돼요.","4시가 되기 10분 전이에요.","그래서 4시 10분 전이에요."],"asset":{"type":"clock2","h":3,"m":50},"variant_rule":{"alt":[{"stem":"5시 55분은 6시 몇 분 전인가요? 수만 쓰세요.","answer":["5"],"explanation":["5시 55분에서 5분이 지나면 6시가 돼요.","6시가 되기 5분 전이에요.","그래서 6시 5분 전이에요."],"asset":{"type":"clock2","h":5,"m":55}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_basic#4','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'mc','auto','5시 55분을 「몇 시 몇 분 전」으로 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":4,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"5시 55분을 「몇 시 몇 분 전」으로 바르게 읽은 것은 어느 것인가요?","options":[{"t":"여섯 시 오 분 전","correct":true},{"t":"다섯 시 오 분 전","mis":"M2-2-u4-X07"},{"t":"여섯 시 오십오 분 전","mis":"M2-2-u4-X08"}],"explanation":["5시 55분에서 5분이 지나면 6시예요.","「몇 시 전」의 시는 곧 될 정각 6시예요.","그래서 「여섯 시 오 분 전」이라고 읽어요."],"asset":{"type":"clock2","h":5,"m":55},"variant_rule":{"alt":[{"stem":"3시 50분을 「몇 시 몇 분 전」으로 바르게 읽은 것은 어느 것인가요?","options":[{"t":"네 시 십 분 전","correct":true},{"t":"세 시 십 분 전","mis":"M2-2-u4-X07"},{"t":"네 시 오십 분 전","mis":"M2-2-u4-X08"}],"explanation":["3시 50분에서 10분이 지나면 4시예요.","「몇 시 전」의 시는 곧 될 정각 4시예요.","그래서 「네 시 십 분 전」이라고 읽어요."],"asset":{"type":"clock2","h":3,"m":50}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_basic#5','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'mc','auto','7시 5분 전을 시계에 나타내려고 해요. 긴바늘은 어느 숫자를 가리켜야 하나요?',ARRAY['M2-2-u4-X08','M2-2-u4-X01']::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"7시 5분 전을 시계에 나타내려고 해요. 긴바늘은 어느 숫자를 가리켜야 하나요?","options":[{"t":"11","correct":true},{"t":"1","mis":"M2-2-u4-X08"},{"t":"7","mis":"M2-2-u4-X01"}],"explanation":["7시 5분 전은 7시가 되기 5분 전 — 6시 55분이에요.","55분은 5분씩 11번이라 긴바늘은 숫자 11을 가리켜요.","숫자 1을 가리키면 7시 5분이 돼요."],"variant_rule":{"alt":[{"stem":"5시 10분 전을 시계에 나타내려고 해요. 긴바늘은 어느 숫자를 가리켜야 하나요?","options":[{"t":"10","correct":true},{"t":"2","mis":"M2-2-u4-X08"},{"t":"5","mis":"M2-2-u4-X01"}],"explanation":["5시 10분 전은 5시가 되기 10분 전 — 4시 50분이에요.","50분은 5분씩 10번이라 긴바늘은 숫자 10을 가리켜요.","숫자 2를 가리키면 5시 10분이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_basic#6','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'mc','auto','7시 5분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X08','M2-2-u4-X07']::text[],true,'{"seq":6,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"7시 5분 전은 몇 시 몇 분인가요?","options":[{"t":"6시 55분","correct":true},{"t":"7시 5분","mis":"M2-2-u4-X08"},{"t":"7시 55분","mis":"M2-2-u4-X07"}],"explanation":["7시 5분 전은 7시가 되기 5분 전이에요.","7시에서 5분 거꾸로 가면 6시 55분이에요.","「전」을 빼고 7시 5분으로 읽지 않아요."],"variant_rule":{"alt":[{"stem":"5시 10분 전은 몇 시 몇 분인가요?","options":[{"t":"4시 50분","correct":true},{"t":"5시 10분","mis":"M2-2-u4-X08"},{"t":"5시 50분","mis":"M2-2-u4-X07"}],"explanation":["5시 10분 전은 5시가 되기 10분 전이에요.","5시에서 10분 거꾸로 가면 4시 50분이에요.","「전」을 빼고 5시 10분으로 읽지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_basic#7','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'ox','auto','3시 50분은 3시 10분 전이에요.',ARRAY['M2-2-u4-X07']::text[],false,'{"seq":7,"concept":"M2-2-u4-C4","difficulty":2,"kind":"ox","stem":"3시 50분은 3시 10분 전이에요.","answer":"X","reason_options":[{"t":"3시 50분에서 10분이 지나면 4시가 되니 4시 10분 전이니까","correct":true},{"t":"지금 짧은바늘이 3과 4 사이라 3시 10분 전이니까","mis":"M2-2-u4-X07"}],"mis":"M2-2-u4-X07","explanation":["3시 50분에서 10분이 지나면 4시가 돼요.","「몇 시 전」의 시는 곧 될 정각이에요.","그래서 3시 50분은 4시 10분 전이에요."],"asset":{"type":"clock2","h":3,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_basic#8','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'match','auto','같은 시각끼리 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C4","difficulty":2,"kind":"match","stem":"같은 시각끼리 이어 보세요.","pairs":[{"l":"8시 55분","r":"9시 5분 전"},{"l":"3시 50분","r":"4시 10분 전"},{"l":"5시 55분","r":"6시 5분 전"}],"mis":"M2-2-u4-X07","explanation":["8시 55분에서 5분 지나면 9시예요.","3시 50분에서 10분 지나면 4시예요.","5시 55분에서 5분 지나면 6시예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 시각끼리 이어 보세요.","pairs":[{"l":"7시 50분","r":"8시 10분 전"},{"l":"2시 50분","r":"3시 10분 전"},{"l":"9시 55분","r":"10시 5분 전"}],"explanation":["7시 50분에서 10분 지나면 8시예요.","2시 50분에서 10분 지나면 3시예요.","9시 55분에서 5분 지나면 10시예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_basic#9','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'blank','auto','「서둘러야지」 — 아침에 눈을 떴는데 시계가 7시 50분이에요. 엄마께서 「8시 (        )분 전이야. 학교에 가려면 서둘러야지.」라고 하셨어요.',ARRAY['M2-2-u4-X08','M2-2-u4-X04']::text[],false,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"blank","stem":"「서둘러야지」 — 아침에 눈을 떴는데 시계가 7시 50분이에요. 엄마께서 「8시 (        )분 전이야. 학교에 가려면 서둘러야지.」라고 하셨어요.","options":[{"t":"10","correct":true},{"t":"50","mis":"M2-2-u4-X08"},{"t":"5","mis":"M2-2-u4-X04"}],"explanation":["7시 50분에서 10분이 지나면 8시예요.","8시가 되기 10분 전이에요.","그래서 「8시 10분 전이야.」라고 하셨어요."],"asset":{"type":"clock2","h":7,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_basic#10','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',3,'error','auto','시계를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X03','M2-2-u4-X16']::text[],false,'{"seq":10,"concept":"M2-2-u4-C4","difficulty":3,"kind":"error","stem":"시계를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민수 — 「짧은바늘이 10에 가까우니까 10시 55분이야.」","correct":true,"mis_target":"M2-2-u4-X03"},{"t":"지아 — 「9시 55분이야.」","mis":"M2-2-u4-X16"},{"t":"연우 — 「10시 5분 전이야.」","mis":"M2-2-u4-X16"}],"explanation":["짧은바늘이 10에 아주 가까워도 아직 9와 10 사이 — 9시예요.","긴바늘이 숫자 11이니 9시 55분, 곧 10시라 10시 5분 전이에요.","민수는 짧은바늘이 닿지 않은 10을 시로 읽었어요."],"asset":{"type":"clock2","h":9,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_challenge#1','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',2,'blank','auto','「벌써 1시 50분인가?」 하고 시계를 보았어요. 「아니야! 1시 (        )분 전이야.」',ARRAY['M2-2-u4-X08','M2-2-u4-X04']::text[],false,'{"seq":1,"concept":"M2-2-u4-C4","difficulty":2,"kind":"blank","stem":"「벌써 1시 50분인가?」 하고 시계를 보았어요. 「아니야! 1시 (        )분 전이야.」","options":[{"t":"10","correct":true},{"t":"50","mis":"M2-2-u4-X08"},{"t":"5","mis":"M2-2-u4-X04"}],"explanation":["짧은바늘이 12와 1 사이라 아직 12시가 지났을 뿐이에요 — 12시 50분이에요.","10분이 지나면 1시가 돼요.","그래서 1시 10분 전이에요."],"asset":{"type":"clock2","h":12,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_challenge#2','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',2,'mc','auto','쉬는 시간에 신나게 놀고 있는데 시계가 10시 55분이에요. 친구가 「3교시가 시작되려면 5분 남았어.」라고 했어요. 3교시는 몇 시에 시작하나요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],false,'{"seq":2,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"쉬는 시간에 신나게 놀고 있는데 시계가 10시 55분이에요. 친구가 「3교시가 시작되려면 5분 남았어.」라고 했어요. 3교시는 몇 시에 시작하나요?","options":[{"t":"11시","correct":true},{"t":"10시","mis":"M2-2-u4-X07"},{"t":"11시 5분","mis":"M2-2-u4-X08"}],"explanation":["10시 55분에서 5분이 지나면 11시예요.","10시 55분은 11시 5분 전이에요.","그래서 3교시는 11시에 시작해요."],"asset":{"type":"clock2","h":10,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_challenge#3','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','운동장에서 축구를 하는데 시계가 2시 50분이에요. 형이 뛰어와 「집에 가려면 서둘러야지.」라고 했어요. 형이 시각을 「몇 시 몇 분 전」으로 말한 것은 어느 것인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],false,'{"seq":3,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"운동장에서 축구를 하는데 시계가 2시 50분이에요. 형이 뛰어와 「집에 가려면 서둘러야지.」라고 했어요. 형이 시각을 「몇 시 몇 분 전」으로 말한 것은 어느 것인가요?","options":[{"t":"3시 10분 전","correct":true},{"t":"2시 10분 전","mis":"M2-2-u4-X07"},{"t":"3시 50분 전","mis":"M2-2-u4-X08"},{"t":"3시 10분","mis":"M2-2-u4-X08"}],"explanation":["2시 50분에서 10분이 지나면 3시예요.","3시가 되기 10분 전이에요.","그래서 「3시 10분 전이야.」라고 말해요."],"asset":{"type":"clock2","h":2,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_challenge#4','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','「벌써 4시 55분인가?」 하고 시계를 보았는데 친구가 「아니야! □시 5분 전이야.」라고 했어요. □에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u4-X03','M2-2-u4-X07']::text[],false,'{"seq":4,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"「벌써 4시 55분인가?」 하고 시계를 보았는데 친구가 「아니야! □시 5분 전이야.」라고 했어요. □에 알맞은 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"5","mis":"M2-2-u4-X03"},{"t":"3","mis":"M2-2-u4-X07"}],"explanation":["짧은바늘이 4에 가깝지만 아직 3과 4 사이 — 3시 55분이에요.","5분이 지나면 4시가 돼요.","그래서 4시 5분 전이에요 — 「4시 55분」은 짧은바늘을 잘못 읽은 거예요."],"asset":{"type":"clock2","h":3,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_challenge#5','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','같은 시각끼리 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],false,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"같은 시각끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"9시 55분 — 10시 5분 전","correct":true},{"t":"9시 55분 — 9시 5분 전","mis":"M2-2-u4-X07"},{"t":"9시 55분 — 10시 55분 전","mis":"M2-2-u4-X08"}],"explanation":["9시 55분에서 5분이 지나면 10시예요.","그래서 9시 55분은 10시 5분 전이에요.","「전」의 시는 곧 될 정각이고, 분은 정각까지 남은 분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_challenge#6','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'ox','auto','「7시 5분 전」과 「7시 5분」은 같은 시각이에요.',ARRAY['M2-2-u4-X08']::text[],false,'{"seq":6,"concept":"M2-2-u4-C4","difficulty":3,"kind":"ox","stem":"「7시 5분 전」과 「7시 5분」은 같은 시각이에요.","answer":"X","reason_options":[{"t":"7시 5분 전은 6시 55분이고 7시 5분은 7시에서 5분 지난 시각이니까","correct":true},{"t":"「전」은 붙여도 안 붙여도 같은 뜻이니까","mis":"M2-2-u4-X08"}],"mis":"M2-2-u4-X08","explanation":["7시 5분 전은 7시가 되기 5분 전 — 6시 55분이에요.","7시 5분은 7시에서 5분이 지난 시각이에요.","두 시각은 10분 차이가 나요 — 같지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_challenge#7','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','모형 시계에 7시 5분 전, 7시, 7시 5분을 차례로 나타내요. 긴바늘이 가리키는 숫자를 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u4-X08','M2-2-u4-X02','M2-2-u4-X01']::text[],false,'{"seq":7,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"모형 시계에 7시 5분 전, 7시, 7시 5분을 차례로 나타내요. 긴바늘이 가리키는 숫자를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"11, 12, 1","correct":true},{"t":"1, 12, 11","mis":"M2-2-u4-X08"},{"t":"5, 12, 5","mis":"M2-2-u4-X02"},{"t":"11, 7, 1","mis":"M2-2-u4-X01"}],"explanation":["7시 5분 전은 6시 55분 — 긴바늘은 숫자 11이에요.","7시에는 긴바늘이 12, 7시 5분에는 숫자 1을 가리켜요.","긴바늘은 11 → 12 → 1로 시계 방향으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_challenge#8','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',4,'essay','teacher','5시 10분 전을 시계에 나타내는 방법을 설명해 보세요. 짧은바늘과 긴바늘이 각각 어디를 가리키는지도 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C4","difficulty":4,"kind":"essay","stem":"5시 10분 전을 시계에 나타내는 방법을 설명해 보세요. 짧은바늘과 긴바늘이 각각 어디를 가리키는지도 써 보세요.","answer_guide":{"answer":"예: 5시 10분 전은 5시가 되기 10분 전이므로 4시 50분이다. 짧은바늘은 4와 5 사이에서 5에 가까운 곳을, 긴바늘은 숫자 10을 가리키게 그린다.","scoring_points":["5시 10분 전을 4시 50분으로 바꾸었는가","짧은바늘을 4와 5 사이에 그렸는가","긴바늘이 숫자 10을 가리킨다고 썼는가"]},"explanation":["정각 5시를 먼저 생각해요.","5시가 되기 10분 전은 4시 50분이에요.","짧은바늘은 4와 5 사이, 긴바늘은 숫자 10이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_challenge#9','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',4,'essay','teacher','「몇 시 몇 분 전」을 넣어 규칙적인 생활을 하기 위한 나의 다짐 문장을 쓰고, 그 시각을 「몇 시 몇 분」으로도 나타내 보세요. (5분 전이나 10분 전을 써요.)','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":4,"kind":"essay","stem":"「몇 시 몇 분 전」을 넣어 규칙적인 생활을 하기 위한 나의 다짐 문장을 쓰고, 그 시각을 「몇 시 몇 분」으로도 나타내 보세요. (5분 전이나 10분 전을 써요.)","answer_guide":{"answer":"예: 나는 9시 10분 전에 잠자리에 들겠습니다. 9시 10분 전은 8시 50분이다.","scoring_points":["「몇 시 5분 전」이나 「몇 시 10분 전」을 넣어 다짐 문장을 썼는가","그 시각을 「몇 시 몇 분」으로 바르게 바꾸었는가","규칙적인 생활과 이어지는 내용을 썼는가"]},"explanation":["「몇 시 몇 분 전」은 곧 될 정각에서 거꾸로 세요.","9시 10분 전은 9시에서 10분 거꾸로 — 8시 50분이에요.","다짐한 시각을 시계에 나타내 보며 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L04_challenge#10','math',2,2,'u4','L04','tb_g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',4,'mc','auto','형이 「3시 10분 전이야.」라고 말한 뒤 5분이 지났어요. 지금 시각을 「몇 시 몇 분 전」으로 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u4-X08','M2-2-u4-X07']::text[],false,'{"seq":10,"concept":"M2-2-u4-C4","difficulty":4,"kind":"mc","stem":"형이 「3시 10분 전이야.」라고 말한 뒤 5분이 지났어요. 지금 시각을 「몇 시 몇 분 전」으로 바르게 말한 것은 어느 것인가요?","options":[{"t":"3시 5분 전","correct":true},{"t":"3시 15분 전","mis":"M2-2-u4-X08"},{"t":"2시 5분 전","mis":"M2-2-u4-X07"},{"t":"3시 5분","mis":"M2-2-u4-X08"}],"explanation":["3시 10분 전은 2시 50분이에요.","5분이 지나면 2시 55분이에요.","2시 55분은 3시가 되기 5분 전 — 3시 5분 전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_basic#1','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'mc','auto','시계의 긴바늘이 한 바퀴 도는 데 걸린 시간은 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X09']::text[],true,'{"seq":1,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"시계의 긴바늘이 한 바퀴 도는 데 걸린 시간은 몇 분인가요?","options":[{"t":"60분","correct":true},{"t":"12분","mis":"M2-2-u4-X02"},{"t":"100분","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 작은 눈금 한 칸을 가는 데 1분이 걸려요.","시계 한 바퀴에는 작은 눈금이 60칸 있어요.","그래서 한 바퀴는 60분 — 60분은 1시간이에요."],"variant_rule":{"alt":[{"stem":"60분은 몇 시간인가요?","options":[{"t":"1시간","correct":true},{"t":"6시간","mis":"M2-2-u4-X09"},{"t":"10시간","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 한 바퀴 도는 데 60분이 걸려요.","그동안 짧은바늘은 숫자 한 칸을 가요.","그래서 60분은 1시간이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_basic#2','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'mc','auto','자전거를 타고 5시에 출발해서 6시에 도착했어요. 자전거를 타는 데 걸린 시간은 얼마인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X09']::text[],false,'{"seq":2,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"자전거를 타고 5시에 출발해서 6시에 도착했어요. 자전거를 타는 데 걸린 시간은 얼마인가요?","options":[{"t":"1시간","correct":true},{"t":"6시간","mis":"M2-2-u4-X11"},{"t":"100분","mis":"M2-2-u4-X09"}],"explanation":["5시에서 6시까지 긴바늘이 한 바퀴 돌았어요.","긴바늘이 한 바퀴 돌면 60분 — 1시간이에요.","도착한 시각 6시가 걸린 시간은 아니에요."],"asset":{"type":"dpair","a":[5,0],"b":[6,0],"la":"출발한 시각","lb":"도착한 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_basic#3','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'sa','auto','비행기를 타고 이동한 시간을 시간 띠에 색칠했어요. 시간 띠 한 칸은 10분이에요. 비행기를 타고 이동하는 데 걸린 시간은 몇 분인가요?','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"비행기를 타고 이동한 시간을 시간 띠에 색칠했어요. 시간 띠 한 칸은 10분이에요. 비행기를 타고 이동하는 데 걸린 시간은 몇 분인가요?","answer":["60","60분"],"explanation":["10시 30분부터 11시 30분까지 6칸을 색칠했어요.","10분씩 6칸이면 60분이에요.","60분은 1시간이에요."],"asset":{"type":"tbar","from":[10,30],"to":[11,30],"label":"비행기를 타고 이동한 시간"},"variant_rule":{"alt":[{"stem":"공연을 본 시간을 시간 띠에 색칠했어요. 시간 띠 한 칸은 10분이에요. 공연을 보는 데 걸린 시간은 몇 분인가요?","answer":["120","120분"],"explanation":["9시부터 11시까지 12칸을 색칠했어요.","10분씩 12칸이면 120분이에요.","60분이 두 번 — 2시간은 120분이에요."],"asset":{"type":"tbar","from":[9,0],"to":[11,0],"label":"공연을 본 시간"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_basic#4','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'mc','auto','공연이 9시에 시작해서 11시에 끝났어요. 시작된 시각에서 끝난 시각까지 모형 시계의 긴바늘을 몇 바퀴 돌려야 하나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],false,'{"seq":4,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"공연이 9시에 시작해서 11시에 끝났어요. 시작된 시각에서 끝난 시각까지 모형 시계의 긴바늘을 몇 바퀴 돌려야 하나요?","options":[{"t":"2바퀴","correct":true},{"t":"11바퀴","mis":"M2-2-u4-X11"},{"t":"1바퀴","mis":"M2-2-u4-X10"}],"explanation":["긴바늘이 한 바퀴 돌 때마다 1시간이 지나요.","9시 → 10시 → 11시, 한 바퀴씩 두 번이에요.","그래서 2바퀴 — 2시간이에요."],"asset":{"type":"dpair","a":[9,0],"b":[11,0],"la":"시작된 시각","lb":"끝난 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_basic#5','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'mc','auto','2시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":5,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"2시간은 몇 분인가요?","options":[{"t":"120분","correct":true},{"t":"200분","mis":"M2-2-u4-X09"},{"t":"20분","mis":"M2-2-u4-X09"},{"t":"60분","mis":"M2-2-u4-X10"}],"explanation":["1시간은 60분이에요.","2시간은 60분이 2번이에요.","60 + 60 = 120 — 120분이에요."],"variant_rule":{"alt":[{"stem":"120분은 몇 시간인가요?","options":[{"t":"2시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X09"},{"t":"1시간","mis":"M2-2-u4-X10"},{"t":"20시간","mis":"M2-2-u4-X09"}],"explanation":["60분은 1시간이에요.","120분은 60분이 2번이에요.","그래서 2시간이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_basic#6','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'mc','auto','비행기가 10시 30분에 출발해서 11시 30분에 도착했어요. 그동안 모형 시계의 긴바늘은 어떻게 움직였나요?',ARRAY['M2-2-u4-X10','M2-2-u4-X01']::text[],false,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"비행기가 10시 30분에 출발해서 11시 30분에 도착했어요. 그동안 모형 시계의 긴바늘은 어떻게 움직였나요?","options":[{"t":"숫자 6에서 출발해 한 바퀴 돌아 다시 6으로 왔어요","correct":true},{"t":"숫자 6에서 12까지 반 바퀴 갔어요","mis":"M2-2-u4-X10"},{"t":"숫자 10에서 11까지 한 칸 갔어요","mis":"M2-2-u4-X01"}],"explanation":["30분일 때 긴바늘은 숫자 6을 가리켜요.","10시 30분에서 11시 30분까지 긴바늘은 6에서 출발해 다시 6으로 와요.","같은 숫자에서 출발해 같은 숫자로 돌아오면 한 바퀴 — 60분이에요."],"asset":{"type":"dpair","a":[10,30],"b":[11,30],"la":"출발한 시각","lb":"도착한 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_basic#7','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'ox','auto','자전거를 5시에 출발해서 6시에 도착하는 동안 짧은바늘은 시계를 한 바퀴 돌았어요.',ARRAY['M2-2-u4-X01']::text[],false,'{"seq":7,"concept":"M2-2-u4-C5","difficulty":2,"kind":"ox","stem":"자전거를 5시에 출발해서 6시에 도착하는 동안 짧은바늘은 시계를 한 바퀴 돌았어요.","answer":"X","reason_options":[{"t":"긴바늘이 한 바퀴 도는 동안 짧은바늘은 5에서 6으로 숫자 한 칸만 가니까","correct":true},{"t":"1시간 동안 두 바늘이 함께 한 바퀴 도니까","mis":"M2-2-u4-X01"}],"mis":"M2-2-u4-X01","explanation":["1시간 동안 긴바늘은 한 바퀴 돌아요.","그동안 짧은바늘은 5에서 6으로 숫자 한 칸 가요.","짧은바늘이 한 바퀴 돌려면 12시간이 걸려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_basic#8','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'match','auto','같은 길이의 시간끼리 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C5","difficulty":2,"kind":"match","stem":"같은 길이의 시간끼리 이어 보세요.","pairs":[{"l":"긴바늘 한 바퀴","r":"60분"},{"l":"긴바늘 두 바퀴","r":"120분"},{"l":"시간 띠 4칸(한 칸 10분)","r":"40분"}],"mis":"M2-2-u4-X10","explanation":["긴바늘 한 바퀴는 60분, 두 바퀴는 120분이에요.","시간 띠 한 칸은 10분 — 4칸이면 40분이에요.","학교 수업 시간 40분은 1시간보다 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_basic#9','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'mc','auto','비행기를 타고 이동한 시간(10시 30분~11시 30분)을 시간 띠에 나타내려고 해요. 시간 띠 한 칸이 10분이면 몇 칸을 색칠해야 하나요?',ARRAY['M2-2-u4-X10','M2-2-u4-X11']::text[],false,'{"seq":9,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"비행기를 타고 이동한 시간(10시 30분~11시 30분)을 시간 띠에 나타내려고 해요. 시간 띠 한 칸이 10분이면 몇 칸을 색칠해야 하나요?","options":[{"t":"6칸","correct":true},{"t":"12칸","mis":"M2-2-u4-X10"},{"t":"1칸","mis":"M2-2-u4-X11"}],"explanation":["10시 30분부터 11시까지 3칸, 11시부터 11시 30분까지 3칸이에요.","모두 6칸 — 10분씩 6칸은 60분이에요.","띠의 칸을 모두 칠하거나 도착한 곳만 표시하지 않아요."],"asset":{"type":"tbar","from":[10,30],"to":[11,30],"label":"비행기를 타고 이동한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_basic#10','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',3,'error','auto','비행기가 10시 30분에 출발해서 11시 30분에 도착했어요. 비행기를 타고 이동한 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X16']::text[],false,'{"seq":10,"concept":"M2-2-u4-C5","difficulty":3,"kind":"error","stem":"비행기가 10시 30분에 출발해서 11시 30분에 도착했어요. 비행기를 타고 이동한 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"수찬 — 「도착한 시각이 11시 30분이니까 90분이야.」","correct":true,"mis_target":"M2-2-u4-X11"},{"t":"지아 — 「긴바늘이 한 바퀴 돌았으니 60분이야.」","mis":"M2-2-u4-X16"},{"t":"연우 — 「시간 띠 6칸을 색칠했으니 60분, 1시간이야.」","mis":"M2-2-u4-X16"}],"explanation":["10시 30분에서 11시 30분까지 긴바늘이 한 바퀴 돌았어요.","그래서 걸린 시간은 60분 — 1시간이에요.","수찬이는 출발한 시각을 보지 않고 도착한 시각만 보았어요."],"asset":{"type":"dpair","a":[10,30],"b":[11,30],"la":"출발한 시각","lb":"도착한 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_challenge#1','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',2,'mc','auto','멈춘 시계가 1시 30분을 가리켜요. 현재 시각인 5시 30분으로 맞추려면 긴바늘을 몇 바퀴 돌려야 하나요?',ARRAY['M2-2-u4-X10','M2-2-u4-X02']::text[],false,'{"seq":1,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"멈춘 시계가 1시 30분을 가리켜요. 현재 시각인 5시 30분으로 맞추려면 긴바늘을 몇 바퀴 돌려야 하나요?","options":[{"t":"4바퀴","correct":true},{"t":"5바퀴","mis":"M2-2-u4-X10"},{"t":"30바퀴","mis":"M2-2-u4-X02"},{"t":"3바퀴","mis":"M2-2-u4-X10"}],"explanation":["긴바늘이 한 바퀴 돌 때마다 1시간이 지나요.","1시 30분 → 2시 30분 → 3시 30분 → 4시 30분 → 5시 30분, 4번이에요.","그래서 긴바늘을 4바퀴 돌려요."],"asset":{"type":"clock2","h":1,"m":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_challenge#2','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',2,'sa','auto','자전거를 5시에 출발해서 6시에 도착했어요. 자전거를 타는 데 걸린 시간은 몇 분인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C5","difficulty":2,"kind":"sa","stem":"자전거를 5시에 출발해서 6시에 도착했어요. 자전거를 타는 데 걸린 시간은 몇 분인가요?","answer":["60","60분"],"explanation":["5시에서 6시까지 긴바늘이 한 바퀴 돌았어요.","긴바늘 한 바퀴는 60분이에요.","60분은 1시간이에요."],"asset":{"type":"tbar","from":[5,0],"to":[6,0],"label":"자전거를 탄 시간"},"variant_rule":{"alt":[{"stem":"공연이 9시에 시작해서 11시에 끝났어요. 공연을 보는 데 걸린 시간은 몇 분인가요?","answer":["120","120분"],"explanation":["9시에서 11시까지 긴바늘이 두 바퀴 돌았어요.","한 바퀴는 60분이에요.","60 + 60 = 120 — 120분이에요."],"asset":{"type":"dpair","a":[9,0],"b":[11,0],"la":"시작된 시각","lb":"끝난 시각"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_challenge#3','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','시간 띠로 걸린 시간을 구하는 방법으로 바른 것은 어느 것인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],false,'{"seq":3,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"시간 띠로 걸린 시간을 구하는 방법으로 바른 것은 어느 것인가요?","options":[{"t":"출발한 시각부터 도착한 시각까지 칸을 색칠하고, 색칠한 칸 수에 10분씩 세어요","correct":true},{"t":"도착한 시각이 있는 곳에만 점을 찍어요","mis":"M2-2-u4-X11"},{"t":"시간 띠의 칸을 처음부터 끝까지 모두 색칠해요","mis":"M2-2-u4-X10"}],"explanation":["시간은 「지금」이 아니라 「얼마나 걸렸는지」를 나타내요.","그래서 출발한 시각부터 도착한 시각까지 칸을 색칠해요.","한 칸이 10분이니 칸 수만큼 10분씩 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_challenge#4','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','공연이 9시에 시작해서 11시에 끝났어요. 그동안 짧은바늘은 숫자 몇 칸을 움직였나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X10','M2-2-u4-X09']::text[],false,'{"seq":4,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"공연이 9시에 시작해서 11시에 끝났어요. 그동안 짧은바늘은 숫자 몇 칸을 움직였나요?","options":[{"t":"2칸","correct":true},{"t":"2바퀴","mis":"M2-2-u4-X01"},{"t":"12칸","mis":"M2-2-u4-X10"},{"t":"120칸","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 한 바퀴 돌 때 짧은바늘은 숫자 한 칸을 가요.","긴바늘이 두 바퀴 도는 동안 짧은바늘은 9에서 11로 두 칸 가요.","두 바퀴를 도는 것은 긴바늘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_challenge#5','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','시계 둘레에 시간 띠를 둘렀더니 숫자와 숫자 사이마다 한 칸씩, 모두 12칸이 되었어요. 이 시간 띠의 한 칸은 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X10']::text[],false,'{"seq":5,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"시계 둘레에 시간 띠를 둘렀더니 숫자와 숫자 사이마다 한 칸씩, 모두 12칸이 되었어요. 이 시간 띠의 한 칸은 몇 분인가요?","options":[{"t":"5분","correct":true},{"t":"1분","mis":"M2-2-u4-X02"},{"t":"10분","mis":"M2-2-u4-X10"},{"t":"12분","mis":"M2-2-u4-X02"}],"explanation":["시계를 한 바퀴 두른 시간 띠는 60분이에요.","숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","그래서 한 칸은 5분, 12칸이면 60분 — 1시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_challenge#6','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'ox','auto','출발한 시각이 10시 10분이든 10시 40분이든, 시간 띠 6칸을 색칠하면 걸린 시간은 1시간이에요.',ARRAY['M2-2-u4-X11']::text[],false,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":3,"kind":"ox","stem":"출발한 시각이 10시 10분이든 10시 40분이든, 시간 띠 6칸을 색칠하면 걸린 시간은 1시간이에요.","answer":"O","reason_options":[{"t":"한 칸이 10분이라 6칸은 60분 — 출발한 시각과 상관없이 1시간이니까","correct":true},{"t":"정각에 출발할 때만 6칸이 1시간이니까","mis":"M2-2-u4-X11"}],"mis":"M2-2-u4-X11","explanation":["시간 띠 한 칸은 10분이에요.","6칸이면 10분씩 6번 — 60분이에요.","어느 시각에 출발해도 6칸은 1시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_challenge#7','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','학교 수업 시간은 40분이에요. 1시간은 수업 시간보다 몇 분 더 긴가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10','M2-2-u4-X09']::text[],false,'{"seq":7,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"학교 수업 시간은 40분이에요. 1시간은 수업 시간보다 몇 분 더 긴가요?","options":[{"t":"20분","correct":true},{"t":"같아요","mis":"M2-2-u4-X11"},{"t":"60분","mis":"M2-2-u4-X10"},{"t":"100분","mis":"M2-2-u4-X09"}],"explanation":["1시간은 60분이에요.","수업 시간은 40분이에요.","60분은 40분보다 20분 더 길어요 — 「수업 한 시간」과 1시간은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_challenge#8','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',4,'essay','teacher','자전거를 5시에 출발해서 6시에 도착했어요. 자전거를 탄 시간이 60분이면서 1시간인 까닭을 모형 시계의 두 바늘로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C5","difficulty":4,"kind":"essay","stem":"자전거를 5시에 출발해서 6시에 도착했어요. 자전거를 탄 시간이 60분이면서 1시간인 까닭을 모형 시계의 두 바늘로 설명해 보세요.","answer_guide":{"answer":"예: 긴바늘이 12에서 출발해 한 바퀴를 돌아 다시 12로 왔다. 긴바늘이 한 바퀴 도는 데 60분이 걸린다. 그동안 짧은바늘은 5에서 6으로 숫자 한 칸 가서 1시간이 지났다. 그래서 60분은 1시간이다.","scoring_points":["긴바늘이 한 바퀴 돌았다고 썼는가","한 바퀴가 60분임을 썼는가","짧은바늘이 한 칸 가서 1시간이 지났음을 썼는가"]},"explanation":["긴바늘은 한 바퀴 — 60분이에요.","짧은바늘은 5에서 6으로 — 1시간이에요.","그래서 60분 = 1시간이에요."],"asset":{"type":"dpair","a":[5,0],"b":[6,0],"la":"출발한 시각","lb":"도착한 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_challenge#9','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',4,'essay','teacher','수찬이는 이 시간 띠를 보고 「도착한 시각이 11시 30분이니까 90분 걸렸어.」라고 했어요. 무엇이 잘못되었는지 설명하고 걸린 시간을 바르게 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C5","difficulty":4,"kind":"essay","stem":"수찬이는 이 시간 띠를 보고 「도착한 시각이 11시 30분이니까 90분 걸렸어.」라고 했어요. 무엇이 잘못되었는지 설명하고 걸린 시간을 바르게 구해 보세요.","answer_guide":{"answer":"예: 수찬이는 출발한 시각을 보지 않고 도착한 시각만 보았다. 색칠한 칸은 10시 30분부터 11시 30분까지 6칸이고 한 칸이 10분이므로 60분, 곧 1시간 걸렸다.","scoring_points":["출발한 시각을 보지 않은 잘못을 찾았는가","색칠한 칸이 6칸임을 세었는가","60분(1시간)이라고 바르게 구했는가"]},"explanation":["시간 띠에서 색칠한 칸은 6칸이에요.","10분씩 6칸이면 60분이에요.","걸린 시간은 60분 — 1시간이에요."],"asset":{"type":"tbar","from":[10,30],"to":[11,30],"label":"비행기를 타고 이동한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L05_challenge#10','math',2,2,'u4','L05','tb_g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',4,'mc','auto','멈춘 시계가 1시 30분을 가리켜요. 긴바늘을 4바퀴 돌려 5시 30분으로 맞추었는데, 다시 보니 현재 시각은 그보다 1시간 뒤였어요. 처음부터 긴바늘을 모두 몇 바퀴 돌려야 했나요?',ARRAY['M2-2-u4-X10','M2-2-u4-X11']::text[],false,'{"seq":10,"concept":"M2-2-u4-C5","difficulty":4,"kind":"mc","stem":"멈춘 시계가 1시 30분을 가리켜요. 긴바늘을 4바퀴 돌려 5시 30분으로 맞추었는데, 다시 보니 현재 시각은 그보다 1시간 뒤였어요. 처음부터 긴바늘을 모두 몇 바퀴 돌려야 했나요?","options":[{"t":"5바퀴","correct":true},{"t":"4바퀴","mis":"M2-2-u4-X10"},{"t":"6바퀴","mis":"M2-2-u4-X10"},{"t":"1바퀴","mis":"M2-2-u4-X11"}],"explanation":["5시 30분보다 1시간 뒤는 6시 30분이에요.","1시 30분에서 6시 30분까지는 5시간이에요.","긴바늘은 1시간에 한 바퀴 — 5바퀴를 돌려야 해요."],"asset":{"type":"clock2","h":1,"m":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_basic#1','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'mc','auto','「출발한 시각은 9시야.」 「산 정상에 도착한 시각은 10시 20분이야.」 등산하는 데 걸린 시간은 얼마인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],false,'{"seq":1,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"「출발한 시각은 9시야.」 「산 정상에 도착한 시각은 10시 20분이야.」 등산하는 데 걸린 시간은 얼마인가요?","options":[{"t":"1시간 20분","correct":true},{"t":"10시간 20분","mis":"M2-2-u4-X11"},{"t":"20분","mis":"M2-2-u4-X10"}],"explanation":["9시에서 긴바늘을 한 바퀴 돌리면 10시 — 1시간이에요.","10시에서 10시 20분까지 20분 더 갔어요.","그래서 1시간 20분이에요."],"asset":{"type":"dpair","a":[9,0],"b":[10,20],"la":"출발한 시각","lb":"도착한 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_basic#2','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'sa','auto','등산하는 데 걸린 시간을 시간 띠에 색칠했어요. 한 칸은 10분이에요. 등산하는 데 걸린 시간은 몇 분인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C6","difficulty":1,"kind":"sa","stem":"등산하는 데 걸린 시간을 시간 띠에 색칠했어요. 한 칸은 10분이에요. 등산하는 데 걸린 시간은 몇 분인가요?","answer":["80","80분"],"explanation":["9시부터 10시 20분까지 8칸을 색칠했어요.","10분씩 8칸이면 80분이에요.","80분은 1시간 20분이에요."],"asset":{"type":"tbar","from":[9,0],"to":[10,20],"label":"등산한 시간"},"variant_rule":{"alt":[{"stem":"체험학습에서 열매 줍기를 한 시간을 시간 띠에 색칠했어요. 한 칸은 10분이에요. 열매 줍기를 한 시간은 몇 분인가요?","answer":["70","70분"],"explanation":["9시 30분부터 10시 40분까지 7칸을 색칠했어요.","10분씩 7칸이면 70분이에요.","70분은 1시간 10분이에요."],"asset":{"type":"tbar","from":[9,30],"to":[10,40],"label":"열매 줍기를 한 시간"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_basic#3','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'mc','auto','1시간 20분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":3,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"1시간 20분은 몇 분인가요?","options":[{"t":"80분","correct":true},{"t":"120분","mis":"M2-2-u4-X09"},{"t":"60분","mis":"M2-2-u4-X10"}],"explanation":["1시간은 60분이에요.","1시간 20분은 60분과 20분이에요.","60 + 20 = 80 — 80분이에요."],"variant_rule":{"alt":[{"stem":"1시간 10분은 몇 분인가요?","options":[{"t":"70분","correct":true},{"t":"110분","mis":"M2-2-u4-X09"},{"t":"60분","mis":"M2-2-u4-X10"}],"explanation":["1시간은 60분이에요.","1시간 10분은 60분과 10분이에요.","60 + 10 = 70 — 70분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_basic#4','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'mc','auto','가을 체험학습 시간표 — 9:00~9:30 안전 체험하기 · 9:30~10:40 열매 줍기 · 10:40~12:00 음식 만들어 먹기 · 12:00~12:40 자연물로 작품 만들기. 안전 체험하기는 몇 분 동안 했나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],false,'{"seq":4,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"가을 체험학습 시간표 — 9:00~9:30 안전 체험하기 · 9:30~10:40 열매 줍기 · 10:40~12:00 음식 만들어 먹기 · 12:00~12:40 자연물로 작품 만들기. 안전 체험하기는 몇 분 동안 했나요?","options":[{"t":"30분","correct":true},{"t":"9시 30분","mis":"M2-2-u4-X11"},{"t":"1시간","mis":"M2-2-u4-X10"}],"explanation":["안전 체험하기는 9시에 시작해서 9시 30분에 끝났어요.","긴바늘이 12에서 6까지 반 바퀴 — 30분이에요.","끝난 시각 9시 30분은 걸린 시간이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_basic#5','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'mc','auto','기차가 서울에서 9시에 출발해서 대전에 10시 10분에 도착했어요. 서울에서 대전까지 걸린 시간을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X11']::text[],false,'{"seq":5,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"기차가 서울에서 9시에 출발해서 대전에 10시 10분에 도착했어요. 서울에서 대전까지 걸린 시간을 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1시간 10분 = 70분","correct":true},{"t":"1시간 10분 = 110분","mis":"M2-2-u4-X09"},{"t":"10시간 10분 = 610분","mis":"M2-2-u4-X11"}],"explanation":["9시에서 1시간 뒤는 10시, 10분 더 가서 1시간 10분이에요.","1시간은 60분이에요.","60 + 10 = 70 — 70분이에요."],"asset":{"type":"dpair","a":[9,0],"b":[10,10],"la":"서울","lb":"대전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_basic#6','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'mc','auto','가을 체험학습 시간표 — 9:00~9:30 안전 체험하기 · 9:30~10:40 열매 줍기 · 10:40~12:00 음식 만들어 먹기 · 12:00~12:40 자연물로 작품 만들기. 열매 줍기를 몇 시간 몇 분 동안 했나요?',ARRAY['M2-2-u4-X10','M2-2-u4-X09']::text[],false,'{"seq":6,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"가을 체험학습 시간표 — 9:00~9:30 안전 체험하기 · 9:30~10:40 열매 줍기 · 10:40~12:00 음식 만들어 먹기 · 12:00~12:40 자연물로 작품 만들기. 열매 줍기를 몇 시간 몇 분 동안 했나요?","options":[{"t":"1시간 10분","correct":true},{"t":"2시간 10분","mis":"M2-2-u4-X10"},{"t":"1시간 70분","mis":"M2-2-u4-X09"}],"explanation":["열매 줍기는 9시 30분부터 10시 40분까지예요.","9시 30분에서 1시간 뒤는 10시 30분, 10분 더 가서 10시 40분이에요.","그래서 1시간 10분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_basic#7','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'mc','auto','가을 체험학습 시간표 — 9:00~9:30 안전 체험하기 · 9:30~10:40 열매 줍기 · 10:40~12:00 음식 만들어 먹기 · 12:00~12:40 자연물로 작품 만들기. 걸린 시간이 1시간이 넘는 활동을 모두 고른 것은 어느 것인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],false,'{"seq":7,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"가을 체험학습 시간표 — 9:00~9:30 안전 체험하기 · 9:30~10:40 열매 줍기 · 10:40~12:00 음식 만들어 먹기 · 12:00~12:40 자연물로 작품 만들기. 걸린 시간이 1시간이 넘는 활동을 모두 고른 것은 어느 것인가요?","options":[{"t":"열매 줍기, 음식 만들어 먹기","correct":true},{"t":"음식 만들어 먹기, 자연물로 작품 만들기","mis":"M2-2-u4-X11"},{"t":"안전 체험하기, 열매 줍기","mis":"M2-2-u4-X10"}],"explanation":["안전 체험하기 30분, 열매 줍기 1시간 10분이에요.","음식 만들어 먹기 1시간 20분, 자연물로 작품 만들기 40분이에요.","1시간이 넘는 활동은 열매 줍기와 음식 만들어 먹기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_basic#8','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'ox','auto','1시간 10분은 110분이에요.',ARRAY['M2-2-u4-X09']::text[],true,'{"seq":8,"concept":"M2-2-u4-C6","difficulty":2,"kind":"ox","stem":"1시간 10분은 110분이에요.","answer":"X","reason_options":[{"t":"1시간은 60분이라 1시간 10분은 60 + 10 = 70분이니까","correct":true},{"t":"1과 10을 이어 쓰면 110이니까","mis":"M2-2-u4-X09"}],"mis":"M2-2-u4-X09","explanation":["1시간은 100분이 아니라 60분이에요.","1시간 10분 = 60분 + 10분이에요.","그래서 70분이에요."],"variant_rule":{"alt":[{"stem":"2시간 40분은 240분이에요.","answer":"X","reason_options":[{"t":"2시간은 120분이라 2시간 40분은 120 + 40 = 160분이니까","correct":true},{"t":"2시간은 200분이라 240분이니까","mis":"M2-2-u4-X09"}],"explanation":["1시간은 60분 — 2시간은 120분이에요.","2시간 40분 = 120분 + 40분이에요.","그래서 160분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_basic#9','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'match','auto','같은 시간끼리 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C6","difficulty":2,"kind":"match","stem":"같은 시간끼리 이어 보세요.","pairs":[{"l":"1시간 10분","r":"70분"},{"l":"1시간 20분","r":"80분"},{"l":"2시간 40분","r":"160분"}],"mis":"M2-2-u4-X09","explanation":["1시간은 60분이에요.","1시간 10분 = 70분, 1시간 20분 = 80분이에요.","2시간 40분 = 120 + 40 = 160분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_basic#10','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',3,'error','auto','체험학습에서 음식 만들어 먹기를 10시 40분부터 12시까지 했어요. 걸린 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X22','M2-2-u4-X16']::text[],false,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":3,"kind":"error","stem":"체험학습에서 음식 만들어 먹기를 10시 40분부터 12시까지 했어요. 걸린 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"수찬 — 「12 − 10 = 2, 분은 40이니까 2시간 40분이야.」","correct":true,"mis_target":"M2-2-u4-X22"},{"t":"지아 — 「10시 40분에서 1시간 뒤는 11시 40분, 20분 더 가서 1시간 20분이야.」","mis":"M2-2-u4-X16"},{"t":"연우 — 「음식 만들어 먹기를 하는 데 80분 걸려.」","mis":"M2-2-u4-X16"}],"explanation":["10시 40분에서 1시간 뒤는 11시 40분이에요.","11시 40분에서 12시까지 20분 더 — 1시간 20분, 곧 80분이에요.","수찬이는 시와 분을 따로 빼서 2시간 40분이라고 했어요."],"asset":{"type":"dpair","a":[10,40],"b":[12,0],"la":"시작한 시각","lb":"끝난 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_challenge#1','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',2,'mc','auto','기차가 서울에서 9시에 출발해서 부산에 11시 40분에 도착했어요. 서울에서 부산까지 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],false,'{"seq":1,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"기차가 서울에서 9시에 출발해서 부산에 11시 40분에 도착했어요. 서울에서 부산까지 걸린 시간은 몇 시간 몇 분인가요?","options":[{"t":"2시간 40분","correct":true},{"t":"11시간 40분","mis":"M2-2-u4-X11"},{"t":"1시간 40분","mis":"M2-2-u4-X10"}],"explanation":["9시에서 긴바늘이 두 바퀴 돌면 11시 — 2시간이에요.","11시에서 11시 40분까지 40분 더 갔어요.","그래서 2시간 40분이에요."],"asset":{"type":"dpair","a":[9,0],"b":[11,40],"la":"서울","lb":"부산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_challenge#2','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',2,'sa','auto','서울에서 부산까지 걸린 시간 2시간 40분은 몇 분인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C6","difficulty":2,"kind":"sa","stem":"서울에서 부산까지 걸린 시간 2시간 40분은 몇 분인가요?","answer":["160","160분"],"explanation":["1시간은 60분 — 2시간은 120분이에요.","2시간 40분은 120분과 40분이에요.","120 + 40 = 160 — 160분이에요."],"variant_rule":{"alt":[{"stem":"등산하는 데 걸린 시간 1시간 20분은 몇 분인가요?","answer":["80","80분"],"explanation":["1시간은 60분이에요.","1시간 20분은 60분과 20분이에요.","60 + 20 = 80 — 80분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_challenge#3','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','등산을 9시가 아니라 9시 10분에 출발해서 10시 20분에 산 정상에 도착했다면, 등산하는 데 걸린 시간은 얼마인가요?',ARRAY['M2-2-u4-X10','M2-2-u4-X09','M2-2-u4-X11']::text[],false,'{"seq":3,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"등산을 9시가 아니라 9시 10분에 출발해서 10시 20분에 산 정상에 도착했다면, 등산하는 데 걸린 시간은 얼마인가요?","options":[{"t":"1시간 10분","correct":true},{"t":"1시간 20분","mis":"M2-2-u4-X10"},{"t":"110분","mis":"M2-2-u4-X09"},{"t":"10시간 10분","mis":"M2-2-u4-X11"}],"explanation":["9시 10분에서 1시간 뒤는 10시 10분이에요.","10시 10분에서 10시 20분까지 10분 더 갔어요.","그래서 1시간 10분 — 70분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_challenge#4','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','기차가 대전을 10시 10분에 지나 부산에 11시 40분에 도착했어요. 대전에서 부산까지 걸린 시간은 얼마인가요?',ARRAY['M2-2-u4-X10','M2-2-u4-X09']::text[],false,'{"seq":4,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"기차가 대전을 10시 10분에 지나 부산에 11시 40분에 도착했어요. 대전에서 부산까지 걸린 시간은 얼마인가요?","options":[{"t":"1시간 30분","correct":true},{"t":"2시간 30분","mis":"M2-2-u4-X10"},{"t":"130분","mis":"M2-2-u4-X09"},{"t":"1시간 50분","mis":"M2-2-u4-X10"}],"explanation":["10시 10분에서 1시간 뒤는 11시 10분이에요.","11시 10분에서 11시 40분까지 30분 더 갔어요.","그래서 1시간 30분 — 90분이에요."],"asset":{"type":"dpair","a":[10,10],"b":[11,40],"la":"대전","lb":"부산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_challenge#5','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','슬기는 10시 30분부터 11시 40분까지, 경민이는 10시 40분부터 12시까지 등산을 했어요. 등산을 더 오래 한 사람과 걸린 시간을 바르게 고른 것은 어느 것인가요?',ARRAY['M2-2-u4-X16','M2-2-u4-X22','M2-2-u4-X09']::text[],false,'{"seq":5,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"슬기는 10시 30분부터 11시 40분까지, 경민이는 10시 40분부터 12시까지 등산을 했어요. 등산을 더 오래 한 사람과 걸린 시간을 바르게 고른 것은 어느 것인가요?","options":[{"t":"경민, 1시간 20분","correct":true},{"t":"슬기, 1시간 10분","mis":"M2-2-u4-X16"},{"t":"경민, 2시간 40분","mis":"M2-2-u4-X22"},{"t":"경민, 120분","mis":"M2-2-u4-X09"}],"explanation":["슬기는 10시 30분에서 1시간 뒤 11시 30분, 10분 더 — 1시간 10분(70분)이에요.","경민이는 10시 40분에서 1시간 뒤 11시 40분, 20분 더 — 1시간 20분(80분)이에요.","그래서 경민이가 등산을 더 오래 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_challenge#6','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'ox','auto','가을 체험학습 시간표 — 9:00~9:30 안전 체험하기 · 9:30~10:40 열매 줍기 · 10:40~12:00 음식 만들어 먹기 · 12:00~12:40 자연물로 작품 만들기. 자연물로 작품 만들기는 열매 줍기보다 더 오래 걸렸어요.',ARRAY['M2-2-u4-X11']::text[],false,'{"seq":6,"concept":"M2-2-u4-C6","difficulty":3,"kind":"ox","stem":"가을 체험학습 시간표 — 9:00~9:30 안전 체험하기 · 9:30~10:40 열매 줍기 · 10:40~12:00 음식 만들어 먹기 · 12:00~12:40 자연물로 작품 만들기. 자연물로 작품 만들기는 열매 줍기보다 더 오래 걸렸어요.","answer":"X","reason_options":[{"t":"작품 만들기는 40분, 열매 줍기는 1시간 10분(70분)이라 열매 줍기가 더 오래 걸렸으니까","correct":true},{"t":"시간표에서 더 늦게 하는 활동이 더 오래 걸리니까","mis":"M2-2-u4-X11"}],"mis":"M2-2-u4-X11","explanation":["자연물로 작품 만들기는 12시부터 12시 40분까지 — 40분이에요.","열매 줍기는 9시 30분부터 10시 40분까지 — 70분이에요.","늦게 하는 활동이 더 오래 걸리는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_challenge#7','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','「음식 만들어 먹기를 하는 데 80분 걸려.」 80분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":7,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"「음식 만들어 먹기를 하는 데 80분 걸려.」 80분은 몇 시간 몇 분인가요?","options":[{"t":"1시간 20분","correct":true},{"t":"8시간","mis":"M2-2-u4-X09"},{"t":"1시간 80분","mis":"M2-2-u4-X09"},{"t":"2시간 20분","mis":"M2-2-u4-X10"}],"explanation":["60분은 1시간이에요.","80분은 60분과 20분으로 가를 수 있어요.","그래서 80분은 1시간 20분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_challenge#8','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',4,'essay','teacher','9시에 등산을 시작해서 10시 20분에 산 정상에 도착했어요. 모형 시계의 긴바늘을 돌리는 방법으로 걸린 시간을 「몇 시간 몇 분」과 「몇 분」으로 나타내 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"9시에 등산을 시작해서 10시 20분에 산 정상에 도착했어요. 모형 시계의 긴바늘을 돌리는 방법으로 걸린 시간을 「몇 시간 몇 분」과 「몇 분」으로 나타내 보세요.","answer_guide":{"answer":"예: 9시에서 긴바늘을 한 바퀴 돌리면 10시 — 1시간이다. 10시에서 10시 20분까지 긴바늘이 숫자 4까지 20분 더 갔다. 그래서 1시간 20분이고, 1시간은 60분이므로 60 + 20 = 80분이다.","scoring_points":["긴바늘을 한 바퀴(1시간) 먼저 돌렸는가","남은 20분을 더 세어 1시간 20분을 구했는가","80분으로 바꾸었는가"]},"explanation":["1시간을 먼저 — 9시에서 10시까지예요.","20분 더 갔으니 1시간 20분이에요.","60분 + 20분 = 80분이에요."],"asset":{"type":"tbar","from":[9,0],"to":[10,20],"label":"등산한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_challenge#9','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',4,'essay','teacher','수찬이는 음식 만들어 먹기(10시 40분~12시)에 걸린 시간을 「12 − 10 = 2, 분은 40이니까 2시간 40분」이라고 했어요. 무엇이 잘못되었는지 설명하고 바르게 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"수찬이는 음식 만들어 먹기(10시 40분~12시)에 걸린 시간을 「12 − 10 = 2, 분은 40이니까 2시간 40분」이라고 했어요. 무엇이 잘못되었는지 설명하고 바르게 구해 보세요.","answer_guide":{"answer":"예: 시와 분을 따로 빼면 안 된다. 10시 40분에서 1시간 뒤는 11시 40분이고, 12시까지 20분 더 가야 한다. 그래서 걸린 시간은 1시간 20분, 곧 80분이다.","scoring_points":["시와 분을 따로 뺀 잘못을 찾았는가","10시 40분에서 1시간 뒤 11시 40분을 찾았는가","1시간 20분(80분)이라고 바르게 구했는가"]},"explanation":["시작한 시각에서 1시간씩 먼저 가 봐요.","10시 40분 → 11시 40분, 그리고 20분 더 가요.","그래서 1시간 20분이에요."],"asset":{"type":"tbar","from":[10,40],"to":[12,0],"label":"음식 만들어 먹기를 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L06_challenge#10','math',2,2,'u4','L06','tb_g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',4,'mc','auto','가을 체험학습 시간표 — 9:00~9:30 안전 체험하기 · 9:30~10:40 열매 줍기 · 10:40~12:00 음식 만들어 먹기 · 12:00~12:40 자연물로 작품 만들기. 체험학습을 9시에 시작해서 네 가지 활동을 모두 마쳤어요. 체험학습을 한 시간은 모두 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10','M2-2-u4-X09']::text[],false,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":4,"kind":"mc","stem":"가을 체험학습 시간표 — 9:00~9:30 안전 체험하기 · 9:30~10:40 열매 줍기 · 10:40~12:00 음식 만들어 먹기 · 12:00~12:40 자연물로 작품 만들기. 체험학습을 9시에 시작해서 네 가지 활동을 모두 마쳤어요. 체험학습을 한 시간은 모두 몇 시간 몇 분인가요?","options":[{"t":"3시간 40분","correct":true},{"t":"12시간 40분","mis":"M2-2-u4-X11"},{"t":"4시간 40분","mis":"M2-2-u4-X10"},{"t":"340분","mis":"M2-2-u4-X09"}],"explanation":["9시에 시작해서 12시 40분에 모두 마쳤어요.","9시에서 긴바늘이 세 바퀴 돌면 12시 — 3시간이에요.","12시에서 40분 더 갔으니 3시간 40분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_basic#1','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'mc','auto','하루는 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X09']::text[],true,'{"seq":1,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"하루는 몇 시간인가요?","options":[{"t":"24시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X13"},{"t":"60시간","mis":"M2-2-u4-X09"}],"explanation":["전날 밤 12시부터 낮 12시까지 오전 12시간이에요.","낮 12시부터 밤 12시까지 오후 12시간이에요.","12 + 12 = 24 — 1일은 24시간이에요."],"variant_rule":{"alt":[{"stem":"세미가 계획한 일을 하는 데 걸린 시간을 모두 더하면 몇 시간인가요?","options":[{"t":"24시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X13"},{"t":"22시간","mis":"M2-2-u4-X10"}],"explanation":["아침 식사 1, 블록 놀이 3, 점심 식사 1, 박물관 관람 5시간이에요.","저녁 식사 1, 독서 3, 잠 10시간이에요.","모두 더하면 24시간 — 하루예요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_basic#2','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'mc','auto','전날 밤 12시부터 낮 12시까지를 무엇이라고 하나요?',ARRAY['M2-2-u4-X12','M2-2-u4-X13']::text[],true,'{"seq":2,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"전날 밤 12시부터 낮 12시까지를 무엇이라고 하나요?","options":[{"t":"오전","correct":true},{"t":"오후","mis":"M2-2-u4-X12"},{"t":"하루","mis":"M2-2-u4-X13"}],"explanation":["하루는 낮 12시를 사이에 두고 둘로 나뉘어요.","전날 밤 12시부터 낮 12시까지가 오전이에요.","낮 12시부터 밤 12시까지가 오후예요."],"variant_rule":{"alt":[{"stem":"낮 12시부터 밤 12시까지를 무엇이라고 하나요?","options":[{"t":"오후","correct":true},{"t":"오전","mis":"M2-2-u4-X12"},{"t":"하루","mis":"M2-2-u4-X13"}],"explanation":["하루는 낮 12시를 사이에 두고 둘로 나뉘어요.","낮 12시부터 밤 12시까지가 오후예요.","전날 밤 12시부터 낮 12시까지가 오전이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_basic#3','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'sa','auto','세미의 생활 계획표예요. 박물관 관람을 하는 데 걸린 시간은 몇 시간인가요?','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C7","difficulty":1,"kind":"sa","stem":"세미의 생활 계획표예요. 박물관 관람을 하는 데 걸린 시간은 몇 시간인가요?","answer":["5","5시간"],"explanation":["박물관 관람은 오후 1시에 시작해서 오후 6시에 끝나요.","오후 1시에서 6시까지 칸을 세면 5칸이에요.","그래서 5시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]},"variant_rule":{"alt":[{"stem":"세미의 생활 계획표예요. 블록 놀이를 하는 데 걸린 시간은 몇 시간인가요?","answer":["3","3시간"],"explanation":["블록 놀이는 오전 9시에 시작해서 낮 12시에 끝나요.","9시에서 12시까지 칸을 세면 3칸이에요.","그래서 3시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}},{"stem":"세미의 생활 계획표예요. 독서를 하는 데 걸린 시간은 몇 시간인가요?","answer":["3","3시간"],"explanation":["독서는 오후 7시에 시작해서 오후 10시에 끝나요.","7시에서 10시까지 칸을 세면 3칸이에요.","그래서 3시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_basic#4','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'mc','auto','세미의 생활 계획표에서 세미가 오전에 하는 일이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u4-X16']::text[],true,'{"seq":4,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"세미의 생활 계획표에서 세미가 오전에 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"박물관 관람","correct":true},{"t":"아침 식사","mis":"M2-2-u4-X16"},{"t":"블록 놀이","mis":"M2-2-u4-X16"}],"explanation":["오전은 전날 밤 12시부터 낮 12시까지예요.","아침 식사와 블록 놀이는 낮 12시 전에 해요.","박물관 관람은 오후 1시부터라 오후에 하는 일이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]},"variant_rule":{"alt":[{"stem":"세미의 생활 계획표에서 세미가 오후에 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"블록 놀이","correct":true},{"t":"저녁 식사","mis":"M2-2-u4-X16"},{"t":"독서","mis":"M2-2-u4-X16"}],"explanation":["오후는 낮 12시부터 밤 12시까지예요.","저녁 식사와 독서는 낮 12시가 지나서 해요.","블록 놀이는 오전 9시부터 낮 12시까지라 오전에 하는 일이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_basic#5','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','세미가 계획한 일을 하는 데 걸린 시간을 모두 더하면 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X10']::text[],false,'{"seq":5,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"세미가 계획한 일을 하는 데 걸린 시간을 모두 더하면 몇 시간인가요?","options":[{"t":"24시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X13"},{"t":"22시간","mis":"M2-2-u4-X10"}],"explanation":["잠은 밤 12시~오전 8시 8시간과 오후 10시~밤 12시 2시간 — 10시간이에요.","1 + 3 + 1 + 5 + 1 + 3 + 10 = 24예요.","하루를 모두 채웠으니 24시간 — 1일이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_basic#6','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','세미의 생활 계획표에서 점심 식사를 하는 때를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u4-X12','M2-2-u4-X10']::text[],false,'{"seq":6,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"세미의 생활 계획표에서 점심 식사를 하는 때를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"낮 12시부터 오후 1시까지","correct":true},{"t":"오전 12시부터 오전 1시까지","mis":"M2-2-u4-X12"},{"t":"오전 11시부터 낮 12시까지","mis":"M2-2-u4-X10"}],"explanation":["점심 식사는 블록 놀이가 끝난 낮 12시에 시작해요.","1시간 동안 먹고 오후 1시에 끝나요.","낮 12시가 지나면 오후 1시, 2시 …로 다시 세요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_basic#7','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'ox','auto','세미는 오후에 하는 일이 더 많으니까 오후가 오전보다 더 길어요.',ARRAY['M2-2-u4-X13']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":2,"kind":"ox","stem":"세미는 오후에 하는 일이 더 많으니까 오후가 오전보다 더 길어요.","answer":"X","reason_options":[{"t":"오전도 12시간, 오후도 12시간으로 길이가 같으니까","correct":true},{"t":"하는 일이 많을수록 시간이 길어지니까","mis":"M2-2-u4-X13"}],"mis":"M2-2-u4-X13","explanation":["오전은 전날 밤 12시부터 낮 12시까지 12시간이에요.","오후는 낮 12시부터 밤 12시까지 12시간이에요.","하는 일이 많아도 시간의 길이는 같아요 — 오전에는 잠을 오래 자서 하는 일이 적어 보여요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_basic#8','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','모형 시계의 짧은바늘이 한 바퀴 돌면 몇 시간이 지나나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X13']::text[],true,'{"seq":8,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"모형 시계의 짧은바늘이 한 바퀴 돌면 몇 시간이 지나나요?","options":[{"t":"12시간","correct":true},{"t":"1시간","mis":"M2-2-u4-X01"},{"t":"24시간","mis":"M2-2-u4-X13"}],"explanation":["짧은바늘은 1시간에 숫자 한 칸을 가요.","시계의 숫자는 12개예요.","그래서 한 바퀴는 12시간 — 두 바퀴 돌면 하루예요."],"variant_rule":{"alt":[{"stem":"모형 시계의 짧은바늘이 두 바퀴 돌면 몇 시간이 지나나요?","options":[{"t":"24시간","correct":true},{"t":"2시간","mis":"M2-2-u4-X01"},{"t":"12시간","mis":"M2-2-u4-X13"}],"explanation":["짧은바늘이 한 바퀴 돌면 12시간이에요.","두 바퀴면 12시간이 2번이에요.","그래서 24시간 — 하루예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_basic#9','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','「우리 가족은 어제 오전 9시에 출발해서 오늘 오전 11시에 집에 도착했어.」 세미네 가족이 여행한 시간은 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X10']::text[],false,'{"seq":9,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"「우리 가족은 어제 오전 9시에 출발해서 오늘 오전 11시에 집에 도착했어.」 세미네 가족이 여행한 시간은 몇 시간인가요?","options":[{"t":"26시간","correct":true},{"t":"2시간","mis":"M2-2-u4-X13"},{"t":"14시간","mis":"M2-2-u4-X10"}],"explanation":["어제 오전 9시에서 하루(24시간)가 지나면 오늘 오전 9시예요.","오늘 오전 9시에서 11시까지 2시간 더 갔어요.","24 + 2 = 26 — 26시간이에요."],"asset":{"type":"dpair","a":[9,0],"b":[11,0],"la":"어제 출발한 시각","lb":"오늘 도착한 시각","ampm":["오전","오전"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_basic#10','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',3,'error','auto','세미네 가족은 어제 오전 9시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X16']::text[],false,'{"seq":10,"concept":"M2-2-u4-C7","difficulty":3,"kind":"error","stem":"세미네 가족은 어제 오전 9시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"연우 — 「9시부터 11시까지니까 2시간이야.」","correct":true,"mis_target":"M2-2-u4-X13"},{"t":"지아 — 「어제 오전 9시에서 하루 지나면 오늘 오전 9시, 2시간 더 가서 26시간이야.」","mis":"M2-2-u4-X16"},{"t":"수찬 — 「짧은바늘이 두 바퀴 돌고 숫자 두 칸을 더 갔어.」","mis":"M2-2-u4-X16"}],"explanation":["어제 오전 9시에서 오늘 오전 9시까지는 하루, 24시간이에요.","거기서 2시간 더 가면 오늘 오전 11시예요.","24 + 2 = 26시간 — 연우는 하루를 빠뜨렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_challenge#1','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',2,'sa','auto','다현이네 가족이 야영을 다녀왔어요. 첫째 날 오전 8시에 출발해서 둘째 날 오전 11시에 도착했어요. 야영을 다녀오는 데 걸린 시간은 몇 시간인가요?','{}'::text[],false,'{"seq":1,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"다현이네 가족이 야영을 다녀왔어요. 첫째 날 오전 8시에 출발해서 둘째 날 오전 11시에 도착했어요. 야영을 다녀오는 데 걸린 시간은 몇 시간인가요?","answer":["27","27시간"],"explanation":["첫째 날 오전 8시에서 둘째 날 오전 8시까지는 24시간이에요.","둘째 날 오전 8시에서 11시까지 3시간 더 갔어요.","24 + 3 = 27 — 하루보다 더 긴 27시간이에요."],"asset":{"type":"dpair","a":[8,0],"b":[11,0],"la":"첫째 날 출발","lb":"둘째 날 도착","ampm":["오전","오전"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_challenge#2','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',2,'mc','auto','오전 11시에서 2시간이 지난 시각을 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u4-X12']::text[],false,'{"seq":2,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 11시에서 2시간이 지난 시각을 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"오후 1시","correct":true},{"t":"오후 13시","mis":"M2-2-u4-X12"},{"t":"오전 1시","mis":"M2-2-u4-X12"}],"explanation":["오전 11시에서 1시간 뒤는 낮 12시예요.","낮 12시에서 1시간 더 가면 오후 1시예요.","12시를 넘으면 다시 1시부터 세요 — 13시는 시계에 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_challenge#3','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','세미의 생활 계획표에서 박물관 관람을 하는 때를 오전·오후를 넣어 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u4-X12','M2-2-u4-X10']::text[],false,'{"seq":3,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"세미의 생활 계획표에서 박물관 관람을 하는 때를 오전·오후를 넣어 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"오후 1시부터 오후 6시까지","correct":true},{"t":"오후 13시부터 오후 18시까지","mis":"M2-2-u4-X12"},{"t":"오전 1시부터 오전 6시까지","mis":"M2-2-u4-X12"},{"t":"낮 12시부터 오후 5시까지","mis":"M2-2-u4-X10"}],"explanation":["박물관 관람은 점심 식사가 끝난 뒤 시작해요.","낮 12시 다음 칸부터 1, 2, 3 … 다시 세면 1시부터 6시까지예요.","낮 12시가 지났으니 오후 1시부터 오후 6시까지예요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_challenge#4','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','하루 동안 모형 시계의 짧은바늘은 몇 바퀴 도나요?',ARRAY['M2-2-u4-X13','M2-2-u4-X01']::text[],false,'{"seq":4,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"하루 동안 모형 시계의 짧은바늘은 몇 바퀴 도나요?","options":[{"t":"2바퀴","correct":true},{"t":"1바퀴","mis":"M2-2-u4-X13"},{"t":"24바퀴","mis":"M2-2-u4-X01"}],"explanation":["짧은바늘은 12시간에 한 바퀴 돌아요.","하루는 24시간 — 12시간이 2번이에요.","그래서 2바퀴 돌아요 — 24바퀴는 긴바늘이 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_challenge#5','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','오전과 오후를 낮과 밤의 말로 견주어 보아요. 「밤 11시」를 오전·오후를 넣어 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u4-X12']::text[],false,'{"seq":5,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"오전과 오후를 낮과 밤의 말로 견주어 보아요. 「밤 11시」를 오전·오후를 넣어 나타낸 것은 어느 것인가요?","options":[{"t":"오후 11시","correct":true},{"t":"오전 11시","mis":"M2-2-u4-X12"},{"t":"오후 23시","mis":"M2-2-u4-X12"}],"explanation":["낮 12시부터 밤 12시까지가 오후예요.","밤 11시는 밤 12시가 되기 전 — 오후예요.","그래서 오후 11시예요 — 낮 11시는 오전 11시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_challenge#6','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'ox','auto','어제 오전 9시부터 오늘 오전 9시까지는 24시간이에요.',ARRAY['M2-2-u4-X13']::text[],false,'{"seq":6,"concept":"M2-2-u4-C7","difficulty":3,"kind":"ox","stem":"어제 오전 9시부터 오늘 오전 9시까지는 24시간이에요.","answer":"O","reason_options":[{"t":"짧은바늘이 두 바퀴 돌아 다시 9로 왔으니 하루, 24시간이니까","correct":true},{"t":"하루는 밤 12시부터 밤 12시까지만 말하니까","mis":"M2-2-u4-X13"}],"mis":"M2-2-u4-X13","explanation":["어제 오전 9시에서 짧은바늘이 한 바퀴 돌면 어제 오후 9시예요.","한 바퀴 더 돌면 오늘 오전 9시 — 두 바퀴, 24시간이에요.","어느 때에서 시작해도 24시간이 지나면 하루가 지난 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_challenge#7','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','세미의 생활 계획표에서 잠을 자는 데 걸린 시간이 10시간인 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u4-X10','M2-2-u4-X12']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"세미의 생활 계획표에서 잠을 자는 데 걸린 시간이 10시간인 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"밤 12시~오전 8시 8시간과 오후 10시~밤 12시 2시간을 더해서","correct":true},{"t":"오전 8시까지 잔 8시간만 세어서","mis":"M2-2-u4-X10"},{"t":"오후 10시와 오전 8시의 차가 2라서","mis":"M2-2-u4-X12"}],"explanation":["잠은 계획표의 처음과 끝, 두 군데에 있어요.","밤 12시~오전 8시는 8시간, 오후 10시~밤 12시는 2시간이에요.","8 + 2 = 10 — 10시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_challenge#8','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',4,'essay','teacher','세미네 가족은 어제 오전 9시에 출발해서 오늘 오전 11시에 도착했어요. 모형 시계를 돌리는 방법으로 여행한 시간을 구하고 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C7","difficulty":4,"kind":"essay","stem":"세미네 가족은 어제 오전 9시에 출발해서 오늘 오전 11시에 도착했어요. 모형 시계를 돌리는 방법으로 여행한 시간을 구하고 설명해 보세요.","answer_guide":{"answer":"예: 어제 오전 9시에서 짧은바늘을 두 바퀴 돌리면 오늘 오전 9시이고, 그동안 하루(24시간)가 지났다. 오늘 오전 9시에서 11시까지 짧은바늘이 두 칸 더 가서 2시간이다. 24 + 2 = 26시간이다.","scoring_points":["하루(24시간)가 지났음을 썼는가","2시간을 더 셈했는가","26시간이라고 구했는가"]},"explanation":["하루가 지나면 같은 시각이 돼요 — 24시간이에요.","거기서 2시간 더 갔어요.","24 + 2 = 26시간이에요."],"asset":{"type":"dpair","a":[9,0],"b":[11,0],"la":"어제 출발한 시각","lb":"오늘 도착한 시각","ampm":["오전","오전"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_challenge#9','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',4,'essay','teacher','세미의 생활 계획표를 본 친구가 「세미는 오후에 하는 일이 더 많으니까 오후가 오전보다 길어.」라고 했어요. 친구의 말이 맞는지 쓰고, 그렇게 생각한 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C7","difficulty":4,"kind":"essay","stem":"세미의 생활 계획표를 본 친구가 「세미는 오후에 하는 일이 더 많으니까 오후가 오전보다 길어.」라고 했어요. 친구의 말이 맞는지 쓰고, 그렇게 생각한 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 오전은 전날 밤 12시부터 낮 12시까지 12시간이고, 오후도 낮 12시부터 밤 12시까지 12시간이다. 세미는 오전에 잠을 8시간 자서 하는 일이 적어 보일 뿐, 시간의 길이는 같다.","scoring_points":["친구의 말이 맞지 않다고 했는가","오전·오후가 각각 12시간임을 썼는가","하는 일의 수와 시간의 길이는 다르다고 썼는가"]},"explanation":["오전은 12시간이에요.","오후도 12시간이에요.","하는 일이 많다고 시간이 길어지지 않아요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L07_challenge#10','math',2,2,'u4','L07','tb_g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',4,'mc','auto','다현이네 가족이 야영을 다녀오는 데 27시간이 걸렸어요. 27시간은 며칠 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C7","difficulty":4,"kind":"mc","stem":"다현이네 가족이 야영을 다녀오는 데 27시간이 걸렸어요. 27시간은 며칠 몇 시간인가요?","options":[{"t":"1일 3시간","correct":true},{"t":"1일 15시간","mis":"M2-2-u4-X13"},{"t":"2일 7시간","mis":"M2-2-u4-X09"},{"t":"3일","mis":"M2-2-u4-X10"}],"explanation":["1일은 24시간이에요.","27시간은 24시간과 3시간으로 가를 수 있어요.","그래서 1일 3시간 — 하루보다 3시간 더 걸렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_basic#1','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',1,'mc','auto','1주일은 며칠인가요?',ARRAY['M2-2-u4-X15']::text[],true,'{"seq":1,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"1주일은 며칠인가요?","options":[{"t":"7일","correct":true},{"t":"5일","mis":"M2-2-u4-X15"},{"t":"10일","mis":"M2-2-u4-X15"}],"explanation":["일요일부터 토요일까지 요일이 일곱 개 있어요.","일, 월, 화, 수, 목, 금, 토 — 7일이에요.","그래서 1주일은 7일이에요."],"variant_rule":{"alt":[{"stem":"지아는 10월 11일 일요일부터 17일 토요일까지 날마다 운동했어요. 지아가 운동한 기간은 며칠인가요?","options":[{"t":"7일","correct":true},{"t":"6일","mis":"M2-2-u4-X17"},{"t":"17일","mis":"M2-2-u4-X14"}],"explanation":["11, 12, 13, 14, 15, 16, 17일 — 하루씩 세면 7일이에요.","일요일부터 토요일까지 요일이 한 번씩 — 1주일이에요.","그래서 지아는 1주일, 7일 동안 운동했어요."],"asset":{"type":"cal","mon":10,"start":4,"days":31,"marks":{"11":"⛰️","12":"🎵","13":"🏃","14":"🎵","15":"🏊","16":"🏃","17":"🏊"}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_basic#2','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',1,'mc','auto','10월 달력이에요. 10월은 모두 며칠인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X15']::text[],false,'{"seq":2,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"10월 달력이에요. 10월은 모두 며칠인가요?","options":[{"t":"31일","correct":true},{"t":"30일","mis":"M2-2-u4-X18"},{"t":"7일","mis":"M2-2-u4-X15"}],"explanation":["10월 달력의 마지막 날짜를 보아요.","10월은 31일까지 있어요.","그래서 10월은 모두 31일이에요."],"asset":{"type":"cal","mon":10,"start":4,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_basic#3','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',1,'mc','auto','1년은 몇 개월인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X18']::text[],true,'{"seq":3,"concept":"M2-2-u4-C9","difficulty":1,"kind":"mc","stem":"1년은 몇 개월인가요?","options":[{"t":"12개월","correct":true},{"t":"10개월","mis":"M2-2-u4-X15"},{"t":"31개월","mis":"M2-2-u4-X18"}],"explanation":["1년에는 1월부터 12월까지 달이 있어요.","모두 열두 달이에요.","그래서 1년은 12개월이에요."],"variant_rule":{"alt":[{"stem":"12개월은 몇 년인가요?","options":[{"t":"1년","correct":true},{"t":"12년","mis":"M2-2-u4-X15"},{"t":"2년","mis":"M2-2-u4-X15"}],"explanation":["1월부터 12월까지가 1년이에요.","열두 달 — 12개월이에요.","그래서 12개월은 1년이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_basic#4','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',1,'mc','auto','지아가 운동한 날을 10월 달력에 표시했어요. 지아가 등산을 한 10월 11일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":4,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"지아가 운동한 날을 10월 달력에 표시했어요. 지아가 등산을 한 10월 11일은 무슨 요일인가요?","options":[{"t":"일요일","correct":true},{"t":"토요일","mis":"M2-2-u4-X17"},{"t":"월요일","mis":"M2-2-u4-X17"}],"explanation":["11일이 있는 세로줄 맨 위를 보아요.","맨 왼쪽 줄이라 일요일이에요.","그래서 10월 11일은 일요일이에요."],"asset":{"type":"cal","mon":10,"start":4,"days":31,"marks":{"11":"⛰️","12":"🎵","13":"🏃","14":"🎵","15":"🏊","16":"🏃","17":"🏊"}},"variant_rule":{"alt":[{"stem":"지아가 운동한 날을 10월 달력에 표시했어요. 지아가 수영을 한 10월 15일은 무슨 요일인가요?","options":[{"t":"목요일","correct":true},{"t":"수요일","mis":"M2-2-u4-X17"},{"t":"금요일","mis":"M2-2-u4-X17"}],"explanation":["15일이 있는 세로줄 맨 위를 보아요.","그 줄은 목요일이에요.","그래서 10월 15일은 목요일이에요."],"asset":{"type":"cal","mon":10,"start":4,"days":31,"marks":{"11":"⛰️","12":"🎵","13":"🏃","14":"🎵","15":"🏊","16":"🏃","17":"🏊"}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_basic#5','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',2,'sa','auto','슬기의 운동 목표 ① 「매주 월요일과 수요일에 음악 줄넘기하기」를 11월 달력에 표시했어요. 11월에 음악 줄넘기를 하는 날은 모두 며칠인가요?','{}'::text[],false,'{"seq":5,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"슬기의 운동 목표 ① 「매주 월요일과 수요일에 음악 줄넘기하기」를 11월 달력에 표시했어요. 11월에 음악 줄넘기를 하는 날은 모두 며칠인가요?","answer":["9","9일"],"explanation":["월요일은 2, 9, 16, 23, 30일 — 5번이에요.","수요일은 4, 11, 18, 25일 — 4번이에요.","5 + 4 = 9 — 모두 9일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"2":"🎵","4":"🎵","9":"🎵","11":"🎵","16":"🎵","18":"🎵","23":"🎵","25":"🎵","30":"🎵"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_basic#6','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',2,'mc','auto','슬기의 운동 목표 ② 「11월 둘째 토요일부터 2주일마다 등산하기」예요. 11월에 슬기가 등산하는 날을 모두 고른 것은 어느 것인가요?',ARRAY['M2-2-u4-X17','M2-2-u4-X15']::text[],false,'{"seq":6,"concept":"M2-2-u4-C8","difficulty":2,"kind":"mc","stem":"슬기의 운동 목표 ② 「11월 둘째 토요일부터 2주일마다 등산하기」예요. 11월에 슬기가 등산하는 날을 모두 고른 것은 어느 것인가요?","options":[{"t":"11월 14일, 11월 28일","correct":true},{"t":"11월 7일, 11월 21일","mis":"M2-2-u4-X17"},{"t":"11월 14일, 11월 21일","mis":"M2-2-u4-X15"}],"explanation":["11월 1일이 일요일이라 첫째 토요일은 7일, 둘째 토요일은 14일이에요.","2주일은 14일 — 14 + 14 = 28이에요.","그래서 둘째 토요일 14일과 넷째 토요일 28일에 등산해요."],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_basic#7','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',2,'mc','auto','1년 달력에서 각 월의 날수를 알아보았어요. 날수가 30일인 달끼리 짝 지은 것은 어느 것인가요?',ARRAY['M2-2-u4-X18']::text[],true,'{"seq":7,"concept":"M2-2-u4-C9","difficulty":2,"kind":"mc","stem":"1년 달력에서 각 월의 날수를 알아보았어요. 날수가 30일인 달끼리 짝 지은 것은 어느 것인가요?","options":[{"t":"4월, 6월","correct":true},{"t":"7월, 8월","mis":"M2-2-u4-X18"},{"t":"1월, 3월","mis":"M2-2-u4-X18"}],"explanation":["31일인 달은 1, 3, 5, 7, 8, 10, 12월이에요.","30일인 달은 4, 6, 9, 11월이에요.","2월은 28일 또는 29일이에요."],"variant_rule":{"alt":[{"stem":"1년 달력에서 각 월의 날수를 알아보았어요. 날수가 31일인 달끼리 짝 지은 것은 어느 것인가요?","options":[{"t":"7월, 8월","correct":true},{"t":"9월, 11월","mis":"M2-2-u4-X18"},{"t":"2월, 4월","mis":"M2-2-u4-X18"}],"explanation":["주먹을 쥐고 1월부터 세면 위로 올라온 부분이 31일인 달이에요.","7월과 8월은 둘 다 위로 올라온 부분 — 31일이에요.","9월·11월·4월은 30일, 2월은 28일 또는 29일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_basic#8','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',2,'match','auto','같은 것끼리 이어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C9","difficulty":2,"kind":"match","stem":"같은 것끼리 이어 보세요.","pairs":[{"l":"1주일","r":"7일"},{"l":"1년","r":"12개월"},{"l":"2월의 날수","r":"28일 또는 29일"}],"mis":"M2-2-u4-X15","explanation":["1주일은 7일이에요.","1년은 12개월이에요.","2월만 28일 또는 29일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_basic#9','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',2,'ox','auto','1주일은 꼭 일요일부터 토요일까지만 말해요.',ARRAY['M2-2-u4-X21']::text[],false,'{"seq":9,"concept":"M2-2-u4-C8","difficulty":2,"kind":"ox","stem":"1주일은 꼭 일요일부터 토요일까지만 말해요.","answer":"X","reason_options":[{"t":"수요일부터 다음 주 화요일까지처럼 이어진 7일이면 모두 1주일이니까","correct":true},{"t":"달력의 한 줄이 일요일부터 시작하니까","mis":"M2-2-u4-X21"}],"mis":"M2-2-u4-X21","explanation":["1주일은 이어진 7일의 길이예요.","목요일부터 다음 주 수요일까지도 7일 — 1주일이에요.","같은 요일은 7일마다 다시 돌아와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_basic#10','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',3,'error','auto','「달」과 「개월」을 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['M2-2-u4-X23','M2-2-u4-X16']::text[],false,'{"seq":10,"concept":"M2-2-u4-C9","difficulty":3,"kind":"error","stem":"「달」과 「개월」을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"수찬 — 「3개월은 세 개월이라고 읽어.」","correct":true,"mis_target":"M2-2-u4-X23"},{"t":"슬기 — 「3달은 세 달이라고 읽어.」","mis":"M2-2-u4-X16"},{"t":"연우 — 「3월은 삼 월이라고 읽어.」","mis":"M2-2-u4-X16"}],"explanation":["「달」 앞에는 한, 두, 세 — 「세 달」이라고 읽어요.","「개월」 앞에는 일, 이, 삼 — 「삼 개월」이라고 읽어요.","수찬이는 3개월을 「세 개월」로 잘못 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_challenge#1','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',2,'mc','auto','슬기는 11월 둘째 토요일(14일)부터 2주일마다 등산해요. 12월에 슬기가 처음으로 등산하는 날과 요일은 언제인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X18','M2-2-u4-X17']::text[],false,'{"seq":1,"concept":"M2-2-u4-C8","difficulty":2,"kind":"mc","stem":"슬기는 11월 둘째 토요일(14일)부터 2주일마다 등산해요. 12월에 슬기가 처음으로 등산하는 날과 요일은 언제인가요?","options":[{"t":"12월 12일 토요일","correct":true},{"t":"12월 5일 토요일","mis":"M2-2-u4-X15"},{"t":"11월 42일 토요일","mis":"M2-2-u4-X18"},{"t":"12월 14일 월요일","mis":"M2-2-u4-X17"}],"explanation":["11월에는 14일과 28일에 등산해요.","28일에서 2주일(14일) 뒤 — 11월은 30일까지라 2일 지나면 30일, 12일 더 지나면 12월 12일이에요.","2주일 뒤는 같은 요일 — 토요일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"⛰️","28":"⛰️"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_challenge#2','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',2,'mc','auto','오늘이 토요일이면 1주일 뒤는 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],false,'{"seq":2,"concept":"M2-2-u4-C8","difficulty":2,"kind":"mc","stem":"오늘이 토요일이면 1주일 뒤는 무슨 요일인가요?","options":[{"t":"토요일","correct":true},{"t":"금요일","mis":"M2-2-u4-X17"},{"t":"일요일","mis":"M2-2-u4-X17"}],"explanation":["1주일은 7일이에요.","같은 요일은 7일마다 다시 돌아와요.","그래서 토요일의 1주일 뒤도 토요일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_challenge#3','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'mc','auto','목요일부터 다음 주 수요일까지는 며칠인가요?',ARRAY['M2-2-u4-X17','M2-2-u4-X21']::text[],false,'{"seq":3,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"목요일부터 다음 주 수요일까지는 며칠인가요?","options":[{"t":"7일","correct":true},{"t":"6일","mis":"M2-2-u4-X17"},{"t":"1주일이 아니라서 셀 수 없어요","mis":"M2-2-u4-X21"}],"explanation":["목, 금, 토, 일, 월, 화, 수 — 하루씩 세면 7일이에요.","이어진 7일이니 1주일이에요.","1주일이 꼭 일요일부터 시작하는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_challenge#4','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',3,'mc','auto','2학년을 3월에 시작했어요. 3월부터 다음 해 2월까지는 몇 개월인가요?',ARRAY['M2-2-u4-X21','M2-2-u4-X15','M2-2-u4-X17']::text[],false,'{"seq":4,"concept":"M2-2-u4-C9","difficulty":3,"kind":"mc","stem":"2학년을 3월에 시작했어요. 3월부터 다음 해 2월까지는 몇 개월인가요?","options":[{"t":"12개월","correct":true},{"t":"1월부터가 아니라서 1년이 아니에요","mis":"M2-2-u4-X21"},{"t":"10개월","mis":"M2-2-u4-X15"},{"t":"11개월","mis":"M2-2-u4-X17"}],"explanation":["3월부터 12월까지 10개월이에요.","다음 해 1월, 2월 — 2개월 더해 12개월이에요.","어느 달에서 시작해도 열두 달이 지나면 1년이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_challenge#5','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',3,'mc','auto','12월의 다음 달은 무엇인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X21']::text[],false,'{"seq":5,"concept":"M2-2-u4-C9","difficulty":3,"kind":"mc","stem":"12월의 다음 달은 무엇인가요?","options":[{"t":"다음 해 1월","correct":true},{"t":"13월","mis":"M2-2-u4-X18"},{"t":"같은 해 1월","mis":"M2-2-u4-X21"}],"explanation":["1년은 1월부터 12월까지 열두 달이에요.","12월 다음에는 해가 바뀌어요.","그래서 다음 해 1월이에요 — 13월은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_challenge#6','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'ox','auto','11월 28일 토요일의 1주일 후는 12월 5일이고, 12월 첫째 토요일이에요.',ARRAY['M2-2-u4-X18']::text[],false,'{"seq":6,"concept":"M2-2-u4-C8","difficulty":3,"kind":"ox","stem":"11월 28일 토요일의 1주일 후는 12월 5일이고, 12월 첫째 토요일이에요.","answer":"O","reason_options":[{"t":"11월은 30일까지라 28일에서 2일 지나면 30일, 5일 더 지나면 12월 5일이니까","correct":true},{"t":"28 + 7 = 35라서 11월 35일이니까","mis":"M2-2-u4-X18"}],"mis":"M2-2-u4-X18","explanation":["1주일은 7일이에요.","11월 30일까지 2일, 12월로 넘어가 5일 — 12월 5일이에요.","12월 5일은 12월의 첫째 토요일이에요."],"asset":{"type":"cal","mon":12,"start":2,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_challenge#7','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'mc','auto','「선생님, 11월 첫째 월요일에 학예회를 하나요?」 「아니에요. 11월 둘째 월요일에 하기로 했어요.」 학예회를 하는 날은 언제인가요?',ARRAY['M2-2-u4-X16','M2-2-u4-X17']::text[],false,'{"seq":7,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"「선생님, 11월 첫째 월요일에 학예회를 하나요?」 「아니에요. 11월 둘째 월요일에 하기로 했어요.」 학예회를 하는 날은 언제인가요?","options":[{"t":"11월 13일","correct":true},{"t":"11월 6일","mis":"M2-2-u4-X16"},{"t":"11월 14일","mis":"M2-2-u4-X17"},{"t":"11월 20일","mis":"M2-2-u4-X17"}],"explanation":["이 해의 11월 1일은 수요일이에요.","첫째 월요일은 6일, 둘째 월요일은 13일이에요.","그래서 학예회는 11월 13일이에요."],"asset":{"type":"cal","mon":11,"start":3,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_challenge#8','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',4,'mc','auto','「세계 여러 나라 전시회」를 11월 20일부터 12월 2일까지 열기로 했어요. 전시회를 하는 기간은 모두 며칠인가요?',ARRAY['M2-2-u4-X17','M2-2-u4-X18','M2-2-u4-X10']::text[],false,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":4,"kind":"mc","stem":"「세계 여러 나라 전시회」를 11월 20일부터 12월 2일까지 열기로 했어요. 전시회를 하는 기간은 모두 며칠인가요?","options":[{"t":"13일","correct":true},{"t":"12일","mis":"M2-2-u4-X17"},{"t":"11일","mis":"M2-2-u4-X18"},{"t":"14일","mis":"M2-2-u4-X10"}],"explanation":["11월은 30일까지라 11월 20일부터 30일까지 11일이에요.","12월 1일, 2일 — 2일 더해요.","11 + 2 = 13 — 모두 13일이에요."],"asset":{"type":"cal","mon":11,"start":3,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_challenge#9','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',4,'essay','teacher','「12월」과 「12개월」은 어떻게 다른지 쓰고, 「3달」과 「3개월」을 바르게 읽어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C9","difficulty":4,"kind":"essay","stem":"「12월」과 「12개월」은 어떻게 다른지 쓰고, 「3달」과 「3개월」을 바르게 읽어 보세요.","answer_guide":{"answer":"예: 12월은 1년 가운데 마지막 달의 이름이고, 12개월은 열두 달 동안의 길이로 1년과 같다. 3달은 「세 달」, 3개월은 「삼 개월」이라고 읽는다.","scoring_points":["12월이 달의 이름임을 썼는가","12개월이 기간(길이)임을 썼는가","「세 달」·「삼 개월」로 바르게 읽었는가"]},"explanation":["「몇 월」은 달의 이름, 「몇 개월」은 기간의 길이예요.","12개월은 1년과 같아요.","「달」 앞에는 한·두·세, 「개월」 앞에는 일·이·삼을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_L08_challenge#10','math',2,2,'u4','L08','tb_g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',4,'essay','teacher','슬기는 11월 둘째 토요일부터 2주일마다 등산을 해요. 11월과 12월에 등산하는 날을 모두 찾고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-2-u4-C8","difficulty":4,"kind":"essay","stem":"슬기는 11월 둘째 토요일부터 2주일마다 등산을 해요. 11월과 12월에 등산하는 날을 모두 찾고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 11월 1일이 일요일이므로 둘째 토요일은 14일이다. 2주일은 14일이므로 14일, 28일에 등산하고, 28일에서 14일 뒤는 12월 12일, 다시 14일 뒤는 12월 26일이다.","scoring_points":["둘째 토요일이 11월 14일임을 찾았는가","2주일이 14일임을 써서 날짜를 이어 찾았는가","11월 30일 다음 12월로 넘어가 12월 12일·26일을 찾았는가"]},"explanation":["둘째 토요일은 11월 14일이에요.","14일씩 더해요 — 14일, 28일, 12월 12일, 12월 26일.","달이 바뀔 때는 그 달의 날수(11월 30일)를 따져요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"⛰️","28":"⛰️"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#1','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C3',1,'mc','auto','시각을 써 보세요. 시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X03','M2-2-u4-X02']::text[],false,'{"seq":1,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시각을 써 보세요. 시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"11시 55분","correct":true},{"t":"12시 55분","mis":"M2-2-u4-X03"},{"t":"11시 11분","mis":"M2-2-u4-X02"}],"explanation":["짧은바늘이 지나온 숫자 11이 시예요.","긴바늘이 가리키는 곳을 가까운 숫자에서부터 작은 눈금으로 세면 55분이에요.","그래서 11시 55분이에요."],"asset":{"type":"clock2","h":11,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#2','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C9',1,'match','auto','같은 것끼리 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"M2-2-u4-C9","difficulty":1,"kind":"match","stem":"같은 것끼리 이어 보세요.","pairs":[{"l":"1시간","r":"60분"},{"l":"1일","r":"24시간"},{"l":"1주일","r":"7일"},{"l":"1년","r":"12개월"}],"mis":"M2-2-u4-X20","explanation":["1시간은 60분, 1일은 24시간이에요.","1주일은 7일, 1년은 12개월이에요.","숫자만 보고 잇지 않고 단위를 보고 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#3','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C4',1,'mc','auto','9시 5분 전은 몇 시 몇 분과 같나요?',ARRAY['M2-2-u4-X08','M2-2-u4-X07']::text[],false,'{"seq":3,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"9시 5분 전은 몇 시 몇 분과 같나요?","options":[{"t":"8시 55분","correct":true},{"t":"9시 5분","mis":"M2-2-u4-X08"},{"t":"9시 55분","mis":"M2-2-u4-X07"}],"explanation":["9시 5분 전은 9시가 되기 5분 전이에요.","9시에서 5분 거꾸로 가면 8시 55분이에요.","「9시 5분 전」과 「9시 5분」은 같지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#4','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C7',1,'mc','auto','「오전 11시에 친구들을 만나서 2시간 동안 놀고 헤어졌어.」 친구와 헤어진 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],false,'{"seq":4,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"「오전 11시에 친구들을 만나서 2시간 동안 놀고 헤어졌어.」 친구와 헤어진 시각은 언제인가요?","options":[{"t":"오후 1시","correct":true},{"t":"오후 13시","mis":"M2-2-u4-X12"},{"t":"오전 1시","mis":"M2-2-u4-X12"}],"explanation":["오전 11시에서 1시간 뒤는 낮 12시예요.","낮 12시에서 1시간 더 가면 오후 1시예요.","12시를 넘으면 다시 1시부터 — 13시는 시계에 없어요."],"asset":{"type":"digital","h":11,"m":0,"ampm":"오전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#5','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',1,'mc','auto','영화가 시작된 시각이 오후 2시 20분이고 끝난 시각이 오후 3시 30분이에요. 영화를 본 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X11']::text[],false,'{"seq":5,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"영화가 시작된 시각이 오후 2시 20분이고 끝난 시각이 오후 3시 30분이에요. 영화를 본 시간은 몇 분인가요?","options":[{"t":"70분","correct":true},{"t":"110분","mis":"M2-2-u4-X09"},{"t":"3시 30분","mis":"M2-2-u4-X11"}],"explanation":["2시 20분에서 1시간 뒤는 3시 20분이에요.","3시 20분에서 3시 30분까지 10분 더 — 1시간 10분이에요.","1시간은 60분 — 60 + 10 = 70분이에요."],"asset":{"type":"dpair","a":[2,20],"b":[3,30],"la":"시작된 시각","lb":"끝난 시각","ampm":["오후","오후"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#6','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C8',1,'mc','auto','11월 달력에 연우 생일(14일)을 표시했어요. 재이의 생일은 연우 생일의 일주일 전이에요. 재이의 생일은 몇 월 며칠인가요?',ARRAY['M2-2-u4-X17','M2-2-u4-X16']::text[],false,'{"seq":6,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"11월 달력에 연우 생일(14일)을 표시했어요. 재이의 생일은 연우 생일의 일주일 전이에요. 재이의 생일은 몇 월 며칠인가요?","options":[{"t":"11월 7일","correct":true},{"t":"11월 8일","mis":"M2-2-u4-X17"},{"t":"11월 21일","mis":"M2-2-u4-X16"}],"explanation":["일주일은 7일이에요.","14일에서 7일 전은 14 − 7 = 7 — 11월 7일이에요.","달력에서 14일 바로 위 칸이 7일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"🎂"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#7','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 2시 몇 분인가요? 분만 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 2시 몇 분인가요? 분만 쓰세요.","answer":["20"],"explanation":["짧은바늘이 2와 3 사이 — 2시예요.","긴바늘이 숫자 4 — 5분씩 4번, 20분이에요.","2시 20분이에요."],"asset":{"type":"clock2","h":2,"m":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#8','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C5',1,'mc','auto','긴바늘이 한 바퀴 도는 데 걸린 시간은 몇 시간인가요?',ARRAY['M2-2-u4-X01','M2-2-u4-X09']::text[],false,'{"seq":8,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"긴바늘이 한 바퀴 도는 데 걸린 시간은 몇 시간인가요?","options":[{"t":"1시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X01"},{"t":"100시간","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 한 바퀴 도는 데 60분이 걸려요.","60분은 1시간이에요.","그동안 짧은바늘은 숫자 한 칸을 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#9','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C2',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],false,'{"seq":9,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"열 시 삼십오 분","correct":true},{"t":"십 시 삼십오 분","mis":"M2-2-u4-X06"},{"t":"열 시 서른다섯 분","mis":"M2-2-u4-X06"}],"explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","시는 「한, 두, 세 …」, 분은 「일, 이, 삼 …」으로 읽어요.","그래서 「열 시 삼십오 분」이에요."],"asset":{"type":"digital","h":10,"m":35}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#10','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C4',2,'mc','auto','아침에 눈을 떴는데 시계가 7시 50분이에요. 엄마께서 「□시 □분 전이야. 학교에 가려면 서둘러야지.」라고 하셨어요. 엄마께서 하신 말은 어느 것인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],false,'{"seq":10,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"아침에 눈을 떴는데 시계가 7시 50분이에요. 엄마께서 「□시 □분 전이야. 학교에 가려면 서둘러야지.」라고 하셨어요. 엄마께서 하신 말은 어느 것인가요?","options":[{"t":"8시 10분 전","correct":true},{"t":"7시 10분 전","mis":"M2-2-u4-X07"},{"t":"8시 50분 전","mis":"M2-2-u4-X08"}],"explanation":["7시 50분에서 10분이 지나면 8시예요.","8시가 되기 10분 전이에요.","그래서 「8시 10분 전이야.」예요."],"asset":{"type":"clock2","h":7,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#11','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C5',2,'mc','auto','공연이 9시에 시작해서 11시에 끝났어요. 모형 시계의 긴바늘을 몇 바퀴 돌려야 하나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X09']::text[],false,'{"seq":11,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"공연이 9시에 시작해서 11시에 끝났어요. 모형 시계의 긴바늘을 몇 바퀴 돌려야 하나요?","options":[{"t":"2바퀴","correct":true},{"t":"11바퀴","mis":"M2-2-u4-X11"},{"t":"120바퀴","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 한 바퀴 돌면 1시간이에요.","9시에서 11시까지는 2시간이에요.","그래서 2바퀴 돌려요."],"asset":{"type":"dpair","a":[9,0],"b":[11,0],"la":"시작된 시각","lb":"끝난 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#12','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',2,'sa','auto','서울에서 대전까지 걸린 시간 1시간 10분은 몇 분인가요?','{}'::text[],false,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"sa","stem":"서울에서 대전까지 걸린 시간 1시간 10분은 몇 분인가요?","answer":["70","70분"],"explanation":["1시간은 60분이에요.","1시간 10분 = 60분 + 10분이에요.","그래서 70분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#13','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C7',2,'sa','auto','세미의 생활 계획표예요. 박물관 관람을 하는 데 걸린 시간은 몇 시간인가요?','{}'::text[],false,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"세미의 생활 계획표예요. 박물관 관람을 하는 데 걸린 시간은 몇 시간인가요?","answer":["5","5시간"],"explanation":["박물관 관람은 오후 1시부터 오후 6시까지예요.","칸을 세면 5칸이에요.","그래서 5시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#14','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C8',2,'sa','auto','슬기는 매주 월요일과 수요일에 음악 줄넘기를 해요. 11월에 음악 줄넘기를 하는 날은 모두 며칠인가요?','{}'::text[],false,'{"seq":14,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"슬기는 매주 월요일과 수요일에 음악 줄넘기를 해요. 11월에 음악 줄넘기를 하는 날은 모두 며칠인가요?","answer":["9","9일"],"explanation":["월요일은 2, 9, 16, 23, 30일 — 5번이에요.","수요일은 4, 11, 18, 25일 — 4번이에요.","5 + 4 = 9 — 9일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"2":"🎵","4":"🎵","9":"🎵","11":"🎵","16":"🎵","18":"🎵","23":"🎵","25":"🎵","30":"🎵"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#15','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C9',2,'mc','auto','2년은 몇 개월인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X20']::text[],false,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"mc","stem":"2년은 몇 개월인가요?","options":[{"t":"24개월","correct":true},{"t":"20개월","mis":"M2-2-u4-X15"},{"t":"2개월","mis":"M2-2-u4-X20"}],"explanation":["1년은 12개월이에요.","2년은 12개월이 2번이에요.","12 + 12 = 24 — 24개월이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#16','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',2,'mc','auto','처음 두발자전거를 탄 날은 2024년 7월 12일, 처음 혼자서 수영한 날은 2024년 7월 26일이에요. 몇 주 후인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X14']::text[],false,'{"seq":16,"concept":"M2-2-u4-C10","difficulty":2,"kind":"mc","stem":"처음 두발자전거를 탄 날은 2024년 7월 12일, 처음 혼자서 수영한 날은 2024년 7월 26일이에요. 몇 주 후인가요?","options":[{"t":"2주 후","correct":true},{"t":"14주 후","mis":"M2-2-u4-X15"},{"t":"26주 후","mis":"M2-2-u4-X14"}],"explanation":["12일에서 26일까지는 14일이에요.","1주일은 7일 — 14일은 2주일이에요.","그래서 2주 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#17','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C3',3,'mc','auto','시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X03','M2-2-u4-X02','M2-2-u4-X01']::text[],false,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"11시 55분","correct":true},{"t":"12시 55분","mis":"M2-2-u4-X03"},{"t":"11시 11분","mis":"M2-2-u4-X02"},{"t":"12시 5분","mis":"M2-2-u4-X01"}],"explanation":["짧은바늘이 12에 아주 가깝지만 아직 11과 12 사이 — 11시예요.","긴바늘이 숫자 11을 가리키니 55분이에요.","그래서 11시 55분이에요 — 12시 5분 전이라고도 해요."],"asset":{"type":"clock2","h":11,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#18','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',3,'mc','auto','열매 줍기를 9시 30분에 시작해서 1시간 10분 동안 했어요. 열매 줍기가 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X10']::text[],false,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"열매 줍기를 9시 30분에 시작해서 1시간 10분 동안 했어요. 열매 줍기가 끝난 시각은 언제인가요?","options":[{"t":"10시 40분","correct":true},{"t":"10시 30분","mis":"M2-2-u4-X10"},{"t":"9시 40분","mis":"M2-2-u4-X10"},{"t":"10시 10분","mis":"M2-2-u4-X10"}],"explanation":["9시 30분에서 1시간 뒤는 10시 30분이에요.","10분 더 가면 10시 40분이에요.","체험학습 시간표의 9:30~10:40과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#19','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C7',3,'sa','auto','어제 오전 9시에 출발해서 오늘 오전 11시에 도착했어요. 여행한 시간은 몇 시간인가요?','{}'::text[],false,'{"seq":19,"concept":"M2-2-u4-C7","difficulty":3,"kind":"sa","stem":"어제 오전 9시에 출발해서 오늘 오전 11시에 도착했어요. 여행한 시간은 몇 시간인가요?","answer":["26","26시간"],"explanation":["어제 오전 9시에서 오늘 오전 9시까지 24시간이에요.","오늘 오전 9시에서 11시까지 2시간 더 갔어요.","24 + 2 = 26 — 26시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#20','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C8',3,'mc','auto','「선생님, 11월 첫째 월요일에 학예회를 하나요?」 「아니에요. 11월 둘째 월요일에 하기로 했어요.」 학예회를 하는 날은 언제인가요?',ARRAY['M2-2-u4-X16','M2-2-u4-X17']::text[],false,'{"seq":20,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"「선생님, 11월 첫째 월요일에 학예회를 하나요?」 「아니에요. 11월 둘째 월요일에 하기로 했어요.」 학예회를 하는 날은 언제인가요?","options":[{"t":"11월 13일","correct":true},{"t":"11월 6일","mis":"M2-2-u4-X16"},{"t":"11월 14일","mis":"M2-2-u4-X17"}],"explanation":["이 해의 11월 1일은 수요일이에요.","첫째 월요일은 6일, 둘째 월요일은 13일이에요.","그래서 학예회는 11월 13일이에요."],"asset":{"type":"cal","mon":11,"start":3,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#21','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C9',3,'mc','auto','1월부터 12월까지 각 월의 날수를 모두 더했어요(2월은 28일). 1년은 며칠인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X20']::text[],false,'{"seq":21,"concept":"M2-2-u4-C9","difficulty":3,"kind":"mc","stem":"1월부터 12월까지 각 월의 날수를 모두 더했어요(2월은 28일). 1년은 며칠인가요?","options":[{"t":"365일","correct":true},{"t":"360일","mis":"M2-2-u4-X18"},{"t":"12일","mis":"M2-2-u4-X20"}],"explanation":["31일인 달 7개, 30일인 달 4개, 2월 28일이에요.","217 + 120 + 28 = 365예요.","그래서 1년은 12개월이면서 365일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#22','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',3,'mc','auto','슬기가 처음 줄넘기를 성공한 날은 2024년 5월 12일이에요. 그날 이후 6개월 후는 언제인가요?',ARRAY['M2-2-u4-X14','M2-2-u4-X15']::text[],false,'{"seq":22,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"슬기가 처음 줄넘기를 성공한 날은 2024년 5월 12일이에요. 그날 이후 6개월 후는 언제인가요?","options":[{"t":"2024년 11월 12일","correct":true},{"t":"2024년 5월 18일","mis":"M2-2-u4-X14"},{"t":"2025년 5월 12일","mis":"M2-2-u4-X15"}],"explanation":["6개월 후는 월만 6 커져요.","5월에서 6개월 뒤는 11월이에요.","그래서 2024년 11월 12일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#23','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C4',4,'essay','teacher','친구가 「9시 5분 전은 9시 5분과 같아요.」라고 했어요. 친구의 말이 맞는지 쓰고, 모형 시계의 긴바늘 자리를 들어 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C4","difficulty":4,"kind":"essay","stem":"친구가 「9시 5분 전은 9시 5분과 같아요.」라고 했어요. 친구의 말이 맞는지 쓰고, 모형 시계의 긴바늘 자리를 들어 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 9시 5분 전은 9시가 되기 5분 전인 8시 55분이라 긴바늘이 숫자 11을 가리킨다. 9시 5분은 9시에서 5분이 지나 긴바늘이 숫자 1을 가리킨다. 두 시각은 10분 차이가 난다.","scoring_points":["친구의 말이 맞지 않다고 했는가","9시 5분 전이 8시 55분(긴바늘 11)임을 썼는가","9시 5분은 긴바늘이 1을 가리켜 다른 시각임을 썼는가"]},"explanation":["9시 5분 전은 8시 55분이에요.","9시 5분은 9시에서 5분 지난 시각이에요.","「전」이 붙으면 다른 시각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#24','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',4,'essay','teacher','나의 성장 이야기예요. 2024년 12월 1일에 수영을 배웠고, 3주 후에 스케이트를, 그로부터 4개월 후에 배드민턴을, 다시 1년 후에 처음 줄넘기 2단 뛰기를 성공했어요. 각 날짜를 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C10","difficulty":4,"kind":"essay","stem":"나의 성장 이야기예요. 2024년 12월 1일에 수영을 배웠고, 3주 후에 스케이트를, 그로부터 4개월 후에 배드민턴을, 다시 1년 후에 처음 줄넘기 2단 뛰기를 성공했어요. 각 날짜를 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 3주는 21일이므로 2024년 12월 22일에 스케이트를 탔다. 12월에서 4개월 후는 다음 해 4월이므로 2025년 4월 22일에 배드민턴을 했다. 1년 후는 년만 1 커지므로 2026년 4월 22일에 2단 뛰기를 성공했다.","scoring_points":["3주 = 21일을 써서 12월 22일을 구했는가","12월에서 4개월 후 해가 바뀌어 2025년 4월 22일을 구했는가","1년 후 2026년 4월 22일을 구했는가"]},"explanation":["주는 7일씩, 개월은 달을, 년은 해를 세요.","12월 다음 달은 다음 해 1월이에요.","1년 후는 년만 1 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_a#25','math',2,2,'u4','','tb_g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',4,'mc','auto','처음 세발자전거를 탄 날 2022년 5월 12일에서 2년 후, 다시 2개월 후, 다시 2주 후는 언제인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X10','M2-2-u4-X14']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"처음 세발자전거를 탄 날 2022년 5월 12일에서 2년 후, 다시 2개월 후, 다시 2주 후는 언제인가요?","options":[{"t":"2024년 7월 26일","correct":true},{"t":"2024년 7월 14일","mis":"M2-2-u4-X15"},{"t":"2024년 5월 26일","mis":"M2-2-u4-X10"},{"t":"2024년 9월 12일","mis":"M2-2-u4-X14"}],"explanation":["2년 후는 2024년 5월 12일, 2개월 후는 2024년 7월 12일이에요.","2주는 14일 — 12 + 14 = 26이에요.","그래서 2024년 7월 26일 — 처음 혼자서 수영한 날이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#1','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C3',1,'mc','auto','시각을 써 보세요. 시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X04','M2-2-u4-X03']::text[],false,'{"seq":1,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시각을 써 보세요. 시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"4시 28분","correct":true},{"t":"4시 25분","mis":"M2-2-u4-X04"},{"t":"5시 28분","mis":"M2-2-u4-X03"}],"explanation":["짧은바늘이 지나온 숫자 4가 시예요.","긴바늘이 가리키는 곳을 가까운 숫자에서부터 작은 눈금으로 세면 28분이에요.","그래서 4시 28분이에요."],"asset":{"type":"clock2","h":4,"m":28}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#2','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C9',1,'match','auto','같은 것끼리 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"M2-2-u4-C9","difficulty":1,"kind":"match","stem":"같은 것끼리 이어 보세요.","pairs":[{"l":"24시간","r":"1일"},{"l":"12개월","r":"1년"},{"l":"60분","r":"1시간"},{"l":"7일","r":"1주일"}],"mis":"M2-2-u4-X20","explanation":["24시간은 1일, 12개월은 1년이에요.","60분은 1시간, 7일은 1주일이에요.","작은 단위가 몇 개 모이면 큰 단위가 되는지 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#3','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C4',1,'mc','auto','10시 50분은 몇 시 몇 분 전과 같나요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],false,'{"seq":3,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"10시 50분은 몇 시 몇 분 전과 같나요?","options":[{"t":"11시 10분 전","correct":true},{"t":"10시 10분 전","mis":"M2-2-u4-X07"},{"t":"11시 50분 전","mis":"M2-2-u4-X08"}],"explanation":["10시 50분에서 10분이 지나면 11시예요.","「몇 시 전」의 시는 곧 될 정각 11시예요.","그래서 10시 50분은 11시 10분 전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#4','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C7',1,'mc','auto','세미는 오후 1시에 박물관 관람을 시작해서 5시간 동안 했어요. 박물관 관람이 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],false,'{"seq":4,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"세미는 오후 1시에 박물관 관람을 시작해서 5시간 동안 했어요. 박물관 관람이 끝난 시각은 언제인가요?","options":[{"t":"오후 6시","correct":true},{"t":"오후 18시","mis":"M2-2-u4-X12"},{"t":"오전 6시","mis":"M2-2-u4-X12"}],"explanation":["오후 1시에서 5시간 뒤를 세어요.","오후 2시, 3시, 4시, 5시, 6시 — 오후 6시예요.","오후의 시도 12시까지만 세요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#5','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',1,'mc','auto','체험학습에서 열매 줍기를 9시 30분부터 10시 40분까지 했어요. 열매 줍기를 한 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":5,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"체험학습에서 열매 줍기를 9시 30분부터 10시 40분까지 했어요. 열매 줍기를 한 시간은 몇 분인가요?","options":[{"t":"70분","correct":true},{"t":"110분","mis":"M2-2-u4-X09"},{"t":"10분","mis":"M2-2-u4-X10"}],"explanation":["9시 30분에서 1시간 뒤는 10시 30분이에요.","10분 더 가서 1시간 10분이에요.","60 + 10 = 70 — 70분이에요."],"asset":{"type":"dpair","a":[9,30],"b":[10,40],"la":"시작한 시각","lb":"끝난 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#6','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C8',1,'mc','auto','11월 달력에 연우 생일(14일 토요일)을 표시했어요. 수찬이의 생일은 연우 생일의 10일 후예요. 수찬이의 생일은 몇 월 며칠이고 무슨 요일인가요?',ARRAY['M2-2-u4-X17','M2-2-u4-X16']::text[],false,'{"seq":6,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"11월 달력에 연우 생일(14일 토요일)을 표시했어요. 수찬이의 생일은 연우 생일의 10일 후예요. 수찬이의 생일은 몇 월 며칠이고 무슨 요일인가요?","options":[{"t":"11월 24일 화요일","correct":true},{"t":"11월 23일 월요일","mis":"M2-2-u4-X17"},{"t":"11월 4일 수요일","mis":"M2-2-u4-X16"}],"explanation":["연우 생일은 빼고 다음 날부터 세어요 — 15일이 1일 후예요.","14 + 10 = 24 — 11월 24일이에요.","24일은 화요일 줄에 있어요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"🎂"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#7','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 7시 몇 분인가요? 분만 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 7시 몇 분인가요? 분만 쓰세요.","answer":["25"],"explanation":["짧은바늘이 7과 8 사이 — 7시예요.","긴바늘이 숫자 5 — 5분씩 5번, 25분이에요.","7시 25분이에요."],"asset":{"type":"clock2","h":7,"m":25}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#8','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C5',1,'mc','auto','60분은 몇 시간인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X20']::text[],false,'{"seq":8,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"60분은 몇 시간인가요?","options":[{"t":"1시간","correct":true},{"t":"6시간","mis":"M2-2-u4-X09"},{"t":"60시간","mis":"M2-2-u4-X20"}],"explanation":["긴바늘이 한 바퀴 도는 데 60분이 걸려요.","긴바늘이 한 바퀴 돌면 1시간이 지나요.","그래서 60분은 1시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#9','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C2',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],false,'{"seq":9,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"열한 시 사십삼 분","correct":true},{"t":"십일 시 사십삼 분","mis":"M2-2-u4-X06"},{"t":"사십삼 시 열한 분","mis":"M2-2-u4-X06"}],"explanation":["「:」 왼쪽 11은 시, 오른쪽 43은 분이에요.","「열한 시 사십삼 분」이라고 읽어요.","시와 분을 바꾸어 읽지 않아요."],"asset":{"type":"digital","h":11,"m":43}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#10','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C4',2,'mc','auto','운동장에서 축구를 하는데 시계가 2시 50분이에요. 형이 「□시 □분 전이야. 집에 가려면 서둘러야지.」라고 했어요. 형이 한 말은 어느 것인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],false,'{"seq":10,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"운동장에서 축구를 하는데 시계가 2시 50분이에요. 형이 「□시 □분 전이야. 집에 가려면 서둘러야지.」라고 했어요. 형이 한 말은 어느 것인가요?","options":[{"t":"3시 10분 전","correct":true},{"t":"2시 10분 전","mis":"M2-2-u4-X07"},{"t":"3시 50분 전","mis":"M2-2-u4-X08"}],"explanation":["2시 50분에서 10분이 지나면 3시예요.","3시가 되기 10분 전이에요.","그래서 「3시 10분 전이야.」예요."],"asset":{"type":"clock2","h":2,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#11','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C5',2,'mc','auto','멈춘 시계가 1시 30분이에요. 현재 시각 5시 30분으로 맞추려면 긴바늘을 몇 바퀴 돌려야 하나요?',ARRAY['M2-2-u4-X10','M2-2-u4-X02']::text[],false,'{"seq":11,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"멈춘 시계가 1시 30분이에요. 현재 시각 5시 30분으로 맞추려면 긴바늘을 몇 바퀴 돌려야 하나요?","options":[{"t":"4바퀴","correct":true},{"t":"5바퀴","mis":"M2-2-u4-X10"},{"t":"30바퀴","mis":"M2-2-u4-X02"}],"explanation":["긴바늘이 한 바퀴 돌 때마다 1시간이 지나요.","1시 30분에서 5시 30분까지는 4시간이에요.","그래서 4바퀴 돌려요."],"asset":{"type":"clock2","h":1,"m":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#12','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',2,'sa','auto','등산하는 데 걸린 시간 1시간 20분은 몇 분인가요?','{}'::text[],false,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"sa","stem":"등산하는 데 걸린 시간 1시간 20분은 몇 분인가요?","answer":["80","80분"],"explanation":["1시간은 60분이에요.","1시간 20분 = 60분 + 20분이에요.","그래서 80분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#13','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C7',2,'sa','auto','세미의 생활 계획표예요. 블록 놀이를 하는 데 걸린 시간은 몇 시간인가요?','{}'::text[],false,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"세미의 생활 계획표예요. 블록 놀이를 하는 데 걸린 시간은 몇 시간인가요?","answer":["3","3시간"],"explanation":["블록 놀이는 오전 9시부터 낮 12시까지예요.","칸을 세면 3칸이에요.","그래서 3시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#14','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C8',2,'sa','auto','슬기는 11월 둘째 토요일부터 2주일마다 등산해요. 11월에 넷째 토요일에도 등산해요. 넷째 토요일은 11월 며칠인가요?','{}'::text[],false,'{"seq":14,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"슬기는 11월 둘째 토요일부터 2주일마다 등산해요. 11월에 넷째 토요일에도 등산해요. 넷째 토요일은 11월 며칠인가요?","answer":["28","28일"],"explanation":["둘째 토요일은 11월 14일이에요.","2주일은 14일 — 14 + 14 = 28이에요.","그래서 넷째 토요일은 11월 28일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#15','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C9',2,'mc','auto','처음 세발자전거를 탄 날은 2022년 5월 12일, 처음 줄넘기를 성공한 날은 2024년 5월 12일이에요. 몇 년 후인가요?',ARRAY['M2-2-u4-X14']::text[],false,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"mc","stem":"처음 세발자전거를 탄 날은 2022년 5월 12일, 처음 줄넘기를 성공한 날은 2024년 5월 12일이에요. 몇 년 후인가요?","options":[{"t":"2년 후","correct":true},{"t":"2개월 후","mis":"M2-2-u4-X14"},{"t":"12년 후","mis":"M2-2-u4-X14"}],"explanation":["월과 일은 5월 12일로 같아요.","2022년에서 2024년으로 년만 2 커졌어요.","그래서 2년 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#16','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',2,'mc','auto','수영을 배운 날은 2024년 12월 1일이에요. 3주 후에 스케이트를 탔어요. 스케이트를 탄 날은 언제인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X14']::text[],false,'{"seq":16,"concept":"M2-2-u4-C10","difficulty":2,"kind":"mc","stem":"수영을 배운 날은 2024년 12월 1일이에요. 3주 후에 스케이트를 탔어요. 스케이트를 탄 날은 언제인가요?","options":[{"t":"2024년 12월 22일","correct":true},{"t":"2024년 12월 4일","mis":"M2-2-u4-X15"},{"t":"2025년 3월 1일","mis":"M2-2-u4-X14"}],"explanation":["3주는 7일이 3번 — 21일이에요.","1 + 21 = 22예요.","그래서 2024년 12월 22일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#17','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C3',3,'mc','auto','시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X03','M2-2-u4-X02','M2-2-u4-X01']::text[],false,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"9시 55분","correct":true},{"t":"10시 55분","mis":"M2-2-u4-X03"},{"t":"9시 11분","mis":"M2-2-u4-X02"},{"t":"11시 50분","mis":"M2-2-u4-X01"}],"explanation":["짧은바늘이 10에 가깝지만 아직 9와 10 사이 — 9시예요.","긴바늘이 숫자 11 — 55분이에요.","그래서 9시 55분이에요."],"asset":{"type":"clock2","h":9,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#18','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',3,'mc','auto','음식 만들어 먹기를 10시 40분에 시작해서 1시간 20분 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"음식 만들어 먹기를 10시 40분에 시작해서 1시간 20분 동안 했어요. 끝난 시각은 언제인가요?","options":[{"t":"12시","correct":true},{"t":"11시 60분","mis":"M2-2-u4-X09"},{"t":"11시 40분","mis":"M2-2-u4-X10"},{"t":"12시 20분","mis":"M2-2-u4-X10"}],"explanation":["10시 40분에서 1시간 뒤는 11시 40분이에요.","20분 더 가면 12시예요.","60분이 되면 다음 시로 넘어가요 — 11시 60분은 12시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#19','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C7',3,'sa','auto','첫째 날 오전 8시에 출발해서 둘째 날 오전 11시에 도착했어요. 걸린 시간은 몇 시간인가요?','{}'::text[],false,'{"seq":19,"concept":"M2-2-u4-C7","difficulty":3,"kind":"sa","stem":"첫째 날 오전 8시에 출발해서 둘째 날 오전 11시에 도착했어요. 걸린 시간은 몇 시간인가요?","answer":["27","27시간"],"explanation":["첫째 날 오전 8시에서 둘째 날 오전 8시까지 24시간이에요.","둘째 날 오전 8시에서 11시까지 3시간 더 갔어요.","24 + 3 = 27 — 27시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#20','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C8',3,'mc','auto','「세계 여러 나라 전시회」를 11월 20일부터 12월 2일까지 열어요. 전시회를 하는 기간은 모두 며칠인가요?',ARRAY['M2-2-u4-X17','M2-2-u4-X18']::text[],false,'{"seq":20,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"「세계 여러 나라 전시회」를 11월 20일부터 12월 2일까지 열어요. 전시회를 하는 기간은 모두 며칠인가요?","options":[{"t":"13일","correct":true},{"t":"12일","mis":"M2-2-u4-X17"},{"t":"11일","mis":"M2-2-u4-X18"}],"explanation":["11월 20일부터 30일까지는 11일이에요.","12월 1일, 2일 — 2일 더해요.","11 + 2 = 13 — 13일이에요."],"asset":{"type":"cal","mon":11,"start":3,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#21','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C9',3,'mc','auto','2학년을 3월에 시작했어요. 1년이 지나 3학년이 되는 때는 언제인가요?',ARRAY['M2-2-u4-X21','M2-2-u4-X17']::text[],false,'{"seq":21,"concept":"M2-2-u4-C9","difficulty":3,"kind":"mc","stem":"2학년을 3월에 시작했어요. 1년이 지나 3학년이 되는 때는 언제인가요?","options":[{"t":"다음 해 3월","correct":true},{"t":"같은 해 12월","mis":"M2-2-u4-X21"},{"t":"다음 해 2월","mis":"M2-2-u4-X17"}],"explanation":["1년은 12개월이에요.","3월에서 열두 달이 지나면 다음 해 3월이에요.","1년은 꼭 1월에 시작하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#22','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',3,'mc','auto','슬기가 처음 혼자서 수영한 날은 2024년 7월 26일이에요. 그날 이후 3주 후는 언제인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X15']::text[],false,'{"seq":22,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"슬기가 처음 혼자서 수영한 날은 2024년 7월 26일이에요. 그날 이후 3주 후는 언제인가요?","options":[{"t":"2024년 8월 16일","correct":true},{"t":"2024년 7월 47일","mis":"M2-2-u4-X18"},{"t":"2024년 7월 29일","mis":"M2-2-u4-X15"}],"explanation":["3주는 21일이에요.","7월은 31일까지라 26일에서 5일 지나면 7월 31일이에요.","16일 더 지나면 8월 16일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#23','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',4,'essay','teacher','영화가 시작된 시각이 오후 2시 20분이고 끝난 시각이 오후 3시 30분이에요. 영화를 본 시간을 몇 분으로 구하고, 구한 방법을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"영화가 시작된 시각이 오후 2시 20분이고 끝난 시각이 오후 3시 30분이에요. 영화를 본 시간을 몇 분으로 구하고, 구한 방법을 설명해 보세요.","answer_guide":{"answer":"예: 2시 20분에서 1시간 뒤는 3시 20분이고, 3시 30분까지 10분 더 갔으므로 1시간 10분이다. 1시간은 60분이므로 60 + 10 = 70분이다.","scoring_points":["1시간을 먼저 찾고 남은 분을 더 세었는가","1시간 10분을 구했는가","70분으로 바꾸었는가"]},"explanation":["2시 20분에서 1시간 뒤는 3시 20분이에요.","10분 더 가서 1시간 10분이에요.","60 + 10 = 70분이에요."],"asset":{"type":"dpair","a":[2,20],"b":[3,30],"la":"시작된 시각","lb":"끝난 시각","ampm":["오후","오후"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#24','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C8',4,'essay','teacher','수찬이의 생일은 연우 생일(11월 14일)의 10일 후예요. 한 친구가 수찬이의 생일을 「11월 23일」이라고 썼어요. 무엇이 잘못되었는지 설명하고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C8","difficulty":4,"kind":"essay","stem":"수찬이의 생일은 연우 생일(11월 14일)의 10일 후예요. 한 친구가 수찬이의 생일을 「11월 23일」이라고 썼어요. 무엇이 잘못되었는지 설명하고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 연우 생일인 14일을 넣어 세었다. 10일 후는 연우 생일을 빼고 다음 날부터 15일(1일 후), 16일(2일 후) … 로 세어야 하므로 14 + 10 = 24, 수찬이의 생일은 11월 24일 화요일이다.","scoring_points":["연우 생일을 넣어 센 잘못을 찾았는가","그날은 빼고 다음 날부터 센다고 썼는가","11월 24일로 바르게 고쳤는가"]},"explanation":["「10일 후」는 그날을 빼고 다음 날부터 세요.","15일이 1일 후, 24일이 10일 후예요.","그래서 11월 24일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"🎂"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_b#25','math',2,2,'u4','','tb_g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',4,'mc','auto','2024년 12월 1일에서 3주 후, 다시 4개월 후는 언제인가요?',ARRAY['M2-2-u4-X21','M2-2-u4-X15','M2-2-u4-X17']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"2024년 12월 1일에서 3주 후, 다시 4개월 후는 언제인가요?","options":[{"t":"2025년 4월 22일","correct":true},{"t":"2024년 4월 22일","mis":"M2-2-u4-X21"},{"t":"2025년 4월 4일","mis":"M2-2-u4-X15"},{"t":"2025년 3월 22일","mis":"M2-2-u4-X17"}],"explanation":["3주는 21일 — 2024년 12월 22일이에요.","12월에서 4개월 후는 다음 해 4월이에요.","그래서 2025년 4월 22일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#1','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C3',1,'mc','auto','시각을 써 보세요. 시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X04','M2-2-u4-X02']::text[],false,'{"seq":1,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시각을 써 보세요. 시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 22분","correct":true},{"t":"7시 20분","mis":"M2-2-u4-X04"},{"t":"7시 6분","mis":"M2-2-u4-X02"}],"explanation":["짧은바늘이 지나온 숫자 7이 시예요.","긴바늘이 가리키는 곳을 가까운 숫자에서부터 작은 눈금으로 세면 22분이에요.","그래서 7시 22분이에요."],"asset":{"type":"clock2","h":7,"m":22}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#2','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C9',1,'match','auto','같은 것끼리 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"M2-2-u4-C9","difficulty":1,"kind":"match","stem":"같은 것끼리 이어 보세요.","pairs":[{"l":"2시간","r":"120분"},{"l":"2주일","r":"14일"},{"l":"2년","r":"24개월"}],"mis":"M2-2-u4-X20","explanation":["1시간은 60분 — 2시간은 120분이에요.","1주일은 7일 — 2주일은 14일이에요.","1년은 12개월 — 2년은 24개월이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#3','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C4',1,'mc','auto','3시 50분은 몇 시 몇 분 전과 같나요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],false,'{"seq":3,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"3시 50분은 몇 시 몇 분 전과 같나요?","options":[{"t":"4시 10분 전","correct":true},{"t":"3시 10분 전","mis":"M2-2-u4-X07"},{"t":"4시 50분 전","mis":"M2-2-u4-X08"}],"explanation":["3시 50분에서 10분이 지나면 4시예요.","「몇 시 전」의 시는 곧 될 정각 4시예요.","그래서 3시 50분은 4시 10분 전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#4','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C7',1,'mc','auto','세미는 오전 9시에 블록 놀이를 시작해서 3시간 동안 했어요. 블록 놀이가 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12','M2-2-u4-X10']::text[],false,'{"seq":4,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"세미는 오전 9시에 블록 놀이를 시작해서 3시간 동안 했어요. 블록 놀이가 끝난 시각은 언제인가요?","options":[{"t":"낮 12시","correct":true},{"t":"오전 12시","mis":"M2-2-u4-X12"},{"t":"오후 3시","mis":"M2-2-u4-X10"}],"explanation":["오전 9시에서 3시간 뒤를 세어요.","오전 10시, 11시, 낮 12시예요.","낮 12시부터는 오후가 시작돼요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#5','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',1,'mc','auto','9시에 등산을 시작해서 10시 20분에 산 정상에 도착했어요. 등산하는 데 걸린 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":5,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"9시에 등산을 시작해서 10시 20분에 산 정상에 도착했어요. 등산하는 데 걸린 시간은 몇 분인가요?","options":[{"t":"80분","correct":true},{"t":"120분","mis":"M2-2-u4-X09"},{"t":"20분","mis":"M2-2-u4-X10"}],"explanation":["9시에서 1시간 뒤는 10시예요.","20분 더 가서 1시간 20분이에요.","60 + 20 = 80 — 80분이에요."],"asset":{"type":"dpair","a":[9,0],"b":[10,20],"la":"출발한 시각","lb":"도착한 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#6','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C8',1,'mc','auto','11월 달력에 연우 생일(14일 토요일)을 표시했어요. 연우 생일의 2주일 후는 몇 월 며칠인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X17']::text[],false,'{"seq":6,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"11월 달력에 연우 생일(14일 토요일)을 표시했어요. 연우 생일의 2주일 후는 몇 월 며칠인가요?","options":[{"t":"11월 28일","correct":true},{"t":"11월 16일","mis":"M2-2-u4-X15"},{"t":"11월 27일","mis":"M2-2-u4-X17"}],"explanation":["2주일은 14일이에요.","14 + 14 = 28 — 11월 28일이에요.","2주일 뒤도 같은 토요일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"🎂"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#7','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 10시 몇 분인가요? 분만 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 10시 몇 분인가요? 분만 쓰세요.","answer":["40"],"explanation":["짧은바늘이 10과 11 사이 — 10시예요.","긴바늘이 숫자 8 — 5분씩 8번, 40분이에요.","10시 40분이에요."],"asset":{"type":"clock2","h":10,"m":40}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#8','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C5',1,'mc','auto','1시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X20']::text[],false,'{"seq":8,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"1시간은 몇 분인가요?","options":[{"t":"60분","correct":true},{"t":"100분","mis":"M2-2-u4-X09"},{"t":"1분","mis":"M2-2-u4-X20"}],"explanation":["1시간 동안 긴바늘은 한 바퀴 돌아요.","한 바퀴에는 작은 눈금이 60칸 있어요.","그래서 1시간은 60분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#9','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C2',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],false,'{"seq":9,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"아홉 시 삼십 분","correct":true},{"t":"구 시 삼십 분","mis":"M2-2-u4-X06"},{"t":"아홉 시 서른 분","mis":"M2-2-u4-X06"}],"explanation":["「:」 왼쪽 9는 시, 오른쪽 30은 분이에요.","「아홉 시 삼십 분」이라고 읽어요.","건강 공원 경기장의 시계가 나타낸 시각이에요."],"asset":{"type":"digital","h":9,"m":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#10','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C4',2,'mc','auto','「벌써 10시 55분인가?」 하고 시계를 보았는데 「아니야! □시 5분 전이야.」 □에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u4-X03','M2-2-u4-X07']::text[],false,'{"seq":10,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"「벌써 10시 55분인가?」 하고 시계를 보았는데 「아니야! □시 5분 전이야.」 □에 알맞은 수는 무엇인가요?","options":[{"t":"10","correct":true},{"t":"11","mis":"M2-2-u4-X03"},{"t":"9","mis":"M2-2-u4-X07"}],"explanation":["짧은바늘이 10에 가깝지만 아직 9와 10 사이 — 9시 55분이에요.","5분이 지나면 10시가 돼요.","그래서 10시 5분 전이에요."],"asset":{"type":"clock2","h":9,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#11','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C5',2,'mc','auto','자전거를 5시에 출발해서 6시에 도착했어요. 그동안 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X02']::text[],false,'{"seq":11,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"자전거를 5시에 출발해서 6시에 도착했어요. 그동안 긴바늘은 몇 바퀴 돌았나요?","options":[{"t":"1바퀴","correct":true},{"t":"6바퀴","mis":"M2-2-u4-X11"},{"t":"60바퀴","mis":"M2-2-u4-X02"}],"explanation":["5시에서 6시까지는 1시간이에요.","1시간 동안 긴바늘은 한 바퀴 돌아요.","그래서 1바퀴예요."],"asset":{"type":"dpair","a":[5,0],"b":[6,0],"la":"출발한 시각","lb":"도착한 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#12','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',2,'sa','auto','서울에서 부산까지 걸린 시간 2시간 40분은 몇 분인가요?','{}'::text[],false,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"sa","stem":"서울에서 부산까지 걸린 시간 2시간 40분은 몇 분인가요?","answer":["160","160분"],"explanation":["2시간은 60분이 2번 — 120분이에요.","2시간 40분 = 120분 + 40분이에요.","그래서 160분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#13','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C7',2,'sa','auto','세미의 생활 계획표예요. 잠을 자는 데 걸린 시간은 모두 몇 시간인가요?','{}'::text[],false,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"세미의 생활 계획표예요. 잠을 자는 데 걸린 시간은 모두 몇 시간인가요?","answer":["10","10시간"],"explanation":["밤 12시부터 오전 8시까지 8시간 잤어요.","오후 10시부터 밤 12시까지 2시간 더 잤어요.","8 + 2 = 10 — 10시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#14','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C8',2,'sa','auto','지아는 10월 11일 일요일에 등산을 했어요. 1주일 뒤 같은 요일에 또 등산을 한다면 10월 며칠인가요?','{}'::text[],false,'{"seq":14,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"지아는 10월 11일 일요일에 등산을 했어요. 1주일 뒤 같은 요일에 또 등산을 한다면 10월 며칠인가요?","answer":["18","18일"],"explanation":["1주일은 7일이에요.","11 + 7 = 18이에요.","10월 18일도 일요일이에요."],"asset":{"type":"cal","mon":10,"start":4,"days":31,"marks":{"11":"⛰️","12":"🎵","13":"🏃","14":"🎵","15":"🏊","16":"🏃","17":"🏊"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#15','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C9',2,'mc','auto','처음 줄넘기를 성공한 날 2024년 5월 12일에서 처음 두발자전거를 탄 날 2024년 7월 12일은 몇 개월 후인가요?',ARRAY['M2-2-u4-X14']::text[],false,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"mc","stem":"처음 줄넘기를 성공한 날 2024년 5월 12일에서 처음 두발자전거를 탄 날 2024년 7월 12일은 몇 개월 후인가요?","options":[{"t":"2개월 후","correct":true},{"t":"7개월 후","mis":"M2-2-u4-X14"},{"t":"2년 후","mis":"M2-2-u4-X14"}],"explanation":["년과 일은 그대로예요.","5월에서 7월로 월만 2 커졌어요.","그래서 2개월 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#16','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',2,'mc','auto','배드민턴을 한 날은 2025년 4월 22일이에요. 1년 후에 처음 줄넘기 2단 뛰기를 성공했어요. 그날은 언제인가요?',ARRAY['M2-2-u4-X14','M2-2-u4-X15']::text[],false,'{"seq":16,"concept":"M2-2-u4-C10","difficulty":2,"kind":"mc","stem":"배드민턴을 한 날은 2025년 4월 22일이에요. 1년 후에 처음 줄넘기 2단 뛰기를 성공했어요. 그날은 언제인가요?","options":[{"t":"2026년 4월 22일","correct":true},{"t":"2025년 5월 22일","mis":"M2-2-u4-X14"},{"t":"2025년 4월 23일","mis":"M2-2-u4-X15"}],"explanation":["1년 후는 년만 1 커져요.","월과 일은 그대로예요.","그래서 2026년 4월 22일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#17','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C3',3,'mc','auto','시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X03','M2-2-u4-X02','M2-2-u4-X01']::text[],false,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"3시 55분","correct":true},{"t":"4시 55분","mis":"M2-2-u4-X03"},{"t":"3시 11분","mis":"M2-2-u4-X02"},{"t":"11시 20분","mis":"M2-2-u4-X01"}],"explanation":["짧은바늘이 4에 가깝지만 아직 3과 4 사이 — 3시예요.","긴바늘이 숫자 11 — 55분이에요.","그래서 3시 55분이에요."],"asset":{"type":"clock2","h":3,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#18','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',3,'mc','auto','기차가 서울에서 9시에 출발해 1시간 10분 뒤에 대전에 도착했어요. 대전에 도착한 시각은 언제인가요?',ARRAY['M2-2-u4-X10','M2-2-u4-X09']::text[],false,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"기차가 서울에서 9시에 출발해 1시간 10분 뒤에 대전에 도착했어요. 대전에 도착한 시각은 언제인가요?","options":[{"t":"10시 10분","correct":true},{"t":"9시 10분","mis":"M2-2-u4-X10"},{"t":"10시 1분","mis":"M2-2-u4-X09"},{"t":"11시 10분","mis":"M2-2-u4-X10"}],"explanation":["9시에서 1시간 뒤는 10시예요.","10분 더 가면 10시 10분이에요.","그래서 10시 10분에 대전에 도착해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#19','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C7',3,'mc','auto','세미네 가족이 여행한 시간 26시간은 며칠 몇 시간인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X13']::text[],false,'{"seq":19,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"세미네 가족이 여행한 시간 26시간은 며칠 몇 시간인가요?","options":[{"t":"1일 2시간","correct":true},{"t":"2일 6시간","mis":"M2-2-u4-X09"},{"t":"1일 14시간","mis":"M2-2-u4-X13"}],"explanation":["1일은 24시간이에요.","26시간은 24시간과 2시간이에요.","그래서 1일 2시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#20','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C8',3,'mc','auto','11월 4일과 11월 11일에 달리기를 해요. 「달리기를 하는 날이 11월에 몇 번 있는지」 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u4-X14']::text[],false,'{"seq":20,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"11월 4일과 11월 11일에 달리기를 해요. 「달리기를 하는 날이 11월에 몇 번 있는지」 바르게 말한 것은 어느 것인가요?","options":[{"t":"11월에 2번 있어요","correct":true},{"t":"11월 11일이에요","mis":"M2-2-u4-X14"},{"t":"모두 15일이에요","mis":"M2-2-u4-X14"}],"explanation":["「몇 번 있는지」는 날의 수를 묻는 말이에요.","4일과 11일 — 두 날이에요.","그래서 2번이에요 — 날짜(몇 월 며칠)와 날의 수를 가려 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#21','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C9',3,'mc','auto','10월 31일의 다음 날은 언제인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X17']::text[],false,'{"seq":21,"concept":"M2-2-u4-C9","difficulty":3,"kind":"mc","stem":"10월 31일의 다음 날은 언제인가요?","options":[{"t":"11월 1일","correct":true},{"t":"10월 32일","mis":"M2-2-u4-X18"},{"t":"11월 2일","mis":"M2-2-u4-X17"}],"explanation":["10월은 31일까지 있어요.","31일 다음 날은 달이 바뀌어요.","그래서 11월 1일이에요."],"asset":{"type":"cal","mon":10,"start":4,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#22','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',3,'mc','auto','스케이트를 탄 날은 2024년 12월 22일이에요. 4개월 후에 배드민턴을 했어요. 배드민턴을 한 날은 언제인가요?',ARRAY['M2-2-u4-X21','M2-2-u4-X14']::text[],false,'{"seq":22,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"스케이트를 탄 날은 2024년 12월 22일이에요. 4개월 후에 배드민턴을 했어요. 배드민턴을 한 날은 언제인가요?","options":[{"t":"2025년 4월 22일","correct":true},{"t":"2024년 4월 22일","mis":"M2-2-u4-X21"},{"t":"2024년 12월 26일","mis":"M2-2-u4-X14"}],"explanation":["12월에서 1개월 뒤는 다음 해 1월이에요.","1월, 2월, 3월, 4월 — 4개월 후는 2025년 4월이에요.","일은 그대로 22일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#23','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C3',4,'essay','teacher','친구가 이 시계를 보고 「12시 55분」이라고 썼어요. 무엇이 잘못되었는지 설명하고 바르게 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C3","difficulty":4,"kind":"essay","stem":"친구가 이 시계를 보고 「12시 55분」이라고 썼어요. 무엇이 잘못되었는지 설명하고 바르게 써 보세요.","answer_guide":{"answer":"예: 짧은바늘이 12에 아주 가까이 있지만 아직 11과 12 사이에 있으므로 시는 11시이다. 긴바늘이 숫자 11을 가리키므로 55분이다. 바른 시각은 11시 55분이다.","scoring_points":["짧은바늘이 아직 11과 12 사이임을 썼는가","시가 11시임을 썼는가","11시 55분이라고 바르게 썼는가"]},"explanation":["짧은바늘은 12에 닿지 않았어요 — 11과 12 사이예요.","그래서 시는 11시예요.","긴바늘이 숫자 11 — 55분, 11시 55분이에요."],"asset":{"type":"clock2","h":11,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#24','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C8',4,'essay','teacher','디데이(D-Day)는 어떤 일을 하기로 한 날이에요. 오늘이 11월 7일이고 연우의 생일이 11월 14일이에요. 연우 생일은 「D-몇」인지 구하고, 달력으로 세는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C8","difficulty":4,"kind":"essay","stem":"디데이(D-Day)는 어떤 일을 하기로 한 날이에요. 오늘이 11월 7일이고 연우의 생일이 11월 14일이에요. 연우 생일은 「D-몇」인지 구하고, 달력으로 세는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 오늘인 7일은 빼고 8일부터 14일까지 하루씩 세면 7일이다. 7일은 1주일이므로 달력에서 7일 바로 아래 칸이 14일이다. 연우 생일은 D-7이다.","scoring_points":["오늘을 빼고 세었는가","7일(1주일)을 바르게 구했는가","D-7로 나타냈는가"]},"explanation":["디데이까지 남은 날은 오늘을 빼고 세요.","8일부터 14일까지 7일이에요.","그래서 D-7이에요 — 1주일 남았어요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"🎂"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_c#25','math',2,2,'u4','','tb_g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',4,'mc','auto','연우 생일은 11월 14일 토요일이에요. 연우 생일의 3주일 후는 몇 월 며칠이고 무슨 요일인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X17','M2-2-u4-X15']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"연우 생일은 11월 14일 토요일이에요. 연우 생일의 3주일 후는 몇 월 며칠이고 무슨 요일인가요?","options":[{"t":"12월 5일 토요일","correct":true},{"t":"11월 35일 토요일","mis":"M2-2-u4-X18"},{"t":"12월 4일 금요일","mis":"M2-2-u4-X17"},{"t":"11월 17일 화요일","mis":"M2-2-u4-X15"}],"explanation":["3주일은 21일이에요.","11월은 30일까지라 14일에서 16일 지나면 30일, 5일 더 지나면 12월 5일이에요.","3주일 뒤는 같은 요일 — 토요일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"🎂"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#1','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C3',1,'mc','auto','시각을 써 보세요. 시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X05','M2-2-u4-X03']::text[],false,'{"seq":1,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시각을 써 보세요. 시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"3시 39분","correct":true},{"t":"3시 41분","mis":"M2-2-u4-X05"},{"t":"4시 39분","mis":"M2-2-u4-X03"}],"explanation":["짧은바늘이 지나온 숫자 3이 시예요.","긴바늘이 가리키는 곳을 가까운 숫자에서부터 작은 눈금으로 세면 39분이에요.","그래서 3시 39분이에요."],"asset":{"type":"clock2","h":3,"m":39}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#2','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C9',1,'match','auto','같은 것끼리 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"M2-2-u4-C9","difficulty":1,"kind":"match","stem":"같은 것끼리 이어 보세요.","pairs":[{"l":"긴바늘 한 바퀴","r":"60분"},{"l":"짧은바늘 두 바퀴","r":"24시간"},{"l":"달력의 한 줄","r":"7일"}],"mis":"M2-2-u4-X20","explanation":["긴바늘이 한 바퀴 돌면 60분이에요.","짧은바늘이 두 바퀴 돌면 하루, 24시간이에요.","달력의 한 줄은 일요일부터 토요일까지 7일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#3','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C4',1,'mc','auto','6시 5분 전은 몇 시 몇 분과 같나요?',ARRAY['M2-2-u4-X08','M2-2-u4-X07']::text[],false,'{"seq":3,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"6시 5분 전은 몇 시 몇 분과 같나요?","options":[{"t":"5시 55분","correct":true},{"t":"6시 5분","mis":"M2-2-u4-X08"},{"t":"6시 55분","mis":"M2-2-u4-X07"}],"explanation":["6시 5분 전은 6시가 되기 5분 전이에요.","6시에서 5분 거꾸로 가면 5시 55분이에요.","「6시 5분 전」과 「6시 5분」은 같지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#4','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C7',1,'mc','auto','세미는 오후 7시에 독서를 시작해서 3시간 동안 했어요. 독서가 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],false,'{"seq":4,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"세미는 오후 7시에 독서를 시작해서 3시간 동안 했어요. 독서가 끝난 시각은 언제인가요?","options":[{"t":"오후 10시","correct":true},{"t":"오후 22시","mis":"M2-2-u4-X12"},{"t":"오전 10시","mis":"M2-2-u4-X12"}],"explanation":["오후 7시에서 3시간 뒤를 세어요.","오후 8시, 9시, 10시 — 오후 10시예요.","밤 12시가 되기 전이라 아직 오후예요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#5','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',1,'mc','auto','슬기는 10시 30분에 등산을 시작해서 11시 40분에 끝냈어요. 슬기가 등산한 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X11']::text[],false,'{"seq":5,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"슬기는 10시 30분에 등산을 시작해서 11시 40분에 끝냈어요. 슬기가 등산한 시간은 몇 분인가요?","options":[{"t":"70분","correct":true},{"t":"110분","mis":"M2-2-u4-X09"},{"t":"11시 40분","mis":"M2-2-u4-X11"}],"explanation":["10시 30분에서 1시간 뒤는 11시 30분이에요.","10분 더 가서 1시간 10분이에요.","60 + 10 = 70 — 70분이에요."],"asset":{"type":"dpair","a":[10,30],"b":[11,40],"la":"시작한 시각","lb":"끝낸 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#6','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C8',1,'mc','auto','11월 달력에 연우 생일(14일 토요일)을 표시했어요. 연우 생일의 1주일 후는 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],false,'{"seq":6,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"11월 달력에 연우 생일(14일 토요일)을 표시했어요. 연우 생일의 1주일 후는 무슨 요일인가요?","options":[{"t":"토요일","correct":true},{"t":"금요일","mis":"M2-2-u4-X17"},{"t":"일요일","mis":"M2-2-u4-X17"}],"explanation":["1주일은 7일이에요.","14 + 7 = 21 — 11월 21일이에요.","같은 요일은 7일마다 돌아와요 — 토요일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"🎂"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#7','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 7시 몇 분인가요? 분만 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 7시 몇 분인가요? 분만 쓰세요.","answer":["15"],"explanation":["짧은바늘이 7과 8 사이 — 7시예요.","긴바늘이 숫자 3 — 5분씩 3번, 15분이에요.","7시 15분이에요."],"asset":{"type":"clock2","h":7,"m":15}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#8','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C5',1,'mc','auto','시간 띠 한 칸이 10분일 때, 1시간은 몇 칸인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X20']::text[],false,'{"seq":8,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"시간 띠 한 칸이 10분일 때, 1시간은 몇 칸인가요?","options":[{"t":"6칸","correct":true},{"t":"10칸","mis":"M2-2-u4-X09"},{"t":"1칸","mis":"M2-2-u4-X20"}],"explanation":["1시간은 60분이에요.","10분씩 6칸이면 60분이에요.","그래서 1시간은 6칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#9','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C2',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],false,'{"seq":9,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"여덟 시 오십오 분","correct":true},{"t":"팔 시 오십오 분","mis":"M2-2-u4-X06"},{"t":"오십오 시 여덟 분","mis":"M2-2-u4-X06"}],"explanation":["「:」 왼쪽 8은 시, 오른쪽 55는 분이에요.","「여덟 시 오십오 분」이라고 읽어요.","9시 5분 전이라고도 해요."],"asset":{"type":"digital","h":8,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#10','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C4',2,'mc','auto','「벌써 1시 50분인가?」 하고 시계를 보았는데 「아니야! 1시 □분 전이야.」 □에 알맞은 수는 무엇인가요?',ARRAY['M2-2-u4-X08','M2-2-u4-X04']::text[],false,'{"seq":10,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"「벌써 1시 50분인가?」 하고 시계를 보았는데 「아니야! 1시 □분 전이야.」 □에 알맞은 수는 무엇인가요?","options":[{"t":"10","correct":true},{"t":"50","mis":"M2-2-u4-X08"},{"t":"5","mis":"M2-2-u4-X04"}],"explanation":["짧은바늘이 12와 1 사이라 12시 50분이에요.","10분이 지나면 1시가 돼요.","그래서 1시 10분 전이에요."],"asset":{"type":"clock2","h":12,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#11','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C5',2,'mc','auto','비행기가 10시 30분에 출발해서 11시 30분에 도착했어요. 그동안 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X10','M2-2-u4-X11']::text[],false,'{"seq":11,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"비행기가 10시 30분에 출발해서 11시 30분에 도착했어요. 그동안 긴바늘은 몇 바퀴 돌았나요?","options":[{"t":"1바퀴","correct":true},{"t":"반 바퀴","mis":"M2-2-u4-X10"},{"t":"11바퀴","mis":"M2-2-u4-X11"}],"explanation":["긴바늘은 숫자 6에서 출발해 다시 6으로 왔어요.","같은 숫자로 돌아오면 한 바퀴예요.","그래서 1바퀴 — 60분, 1시간이에요."],"asset":{"type":"dpair","a":[10,30],"b":[11,30],"la":"출발한 시각","lb":"도착한 시각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#12','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',2,'sa','auto','「음식 만들어 먹기를 하는 데 80분 걸려.」 80분은 1시간 몇 분인가요? 분만 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"sa","stem":"「음식 만들어 먹기를 하는 데 80분 걸려.」 80분은 1시간 몇 분인가요? 분만 쓰세요.","answer":["20","20분"],"explanation":["60분은 1시간이에요.","80분은 60분과 20분이에요.","그래서 1시간 20분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#13','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C7',2,'sa','auto','세미의 생활 계획표예요. 아침 식사, 점심 식사, 저녁 식사를 하는 데 걸린 시간은 모두 몇 시간인가요?','{}'::text[],false,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"세미의 생활 계획표예요. 아침 식사, 점심 식사, 저녁 식사를 하는 데 걸린 시간은 모두 몇 시간인가요?","answer":["3","3시간"],"explanation":["아침 식사, 점심 식사, 저녁 식사는 각각 1시간이에요.","1 + 1 + 1 = 3이에요.","그래서 모두 3시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,8,"😴"],["아침 식사",8,9,"🍚"],["블록 놀이",9,12,"🧱"],["점심 식사",12,13,"🍜"],["박물관 관람",13,18,"🖼️"],["저녁 식사",18,19,"🍲"],["독서",20,22,"📖"],["잠",23,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#14','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C8',2,'sa','auto','10월 달력에서 둘째 토요일은 10월 며칠인가요?','{}'::text[],false,'{"seq":14,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"10월 달력에서 둘째 토요일은 10월 며칠인가요?","answer":["10","10일"],"explanation":["10월 1일이 목요일이라 첫째 토요일은 3일이에요.","1주일 뒤 둘째 토요일은 3 + 7 = 10일이에요.","그래서 10월 10일이에요."],"asset":{"type":"cal","mon":10,"start":4,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#15','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C9',2,'mc','auto','1년 6개월은 몇 개월인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X20']::text[],false,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"mc","stem":"1년 6개월은 몇 개월인가요?","options":[{"t":"18개월","correct":true},{"t":"16개월","mis":"M2-2-u4-X15"},{"t":"7개월","mis":"M2-2-u4-X20"}],"explanation":["1년은 12개월이에요.","1년 6개월은 12개월과 6개월이에요.","12 + 6 = 18 — 18개월이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#16','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',2,'mc','auto','처음 줄넘기를 성공한 날은 2024년 5월 12일이에요. 2개월 후는 언제인가요?',ARRAY['M2-2-u4-X14']::text[],false,'{"seq":16,"concept":"M2-2-u4-C10","difficulty":2,"kind":"mc","stem":"처음 줄넘기를 성공한 날은 2024년 5월 12일이에요. 2개월 후는 언제인가요?","options":[{"t":"2024년 7월 12일","correct":true},{"t":"2024년 5월 14일","mis":"M2-2-u4-X14"},{"t":"2026년 5월 12일","mis":"M2-2-u4-X14"}],"explanation":["2개월 후는 월만 2 커져요.","5월에서 2개월 뒤는 7월이에요.","그래서 2024년 7월 12일 — 처음 두발자전거를 탄 날이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#17','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C3',3,'mc','auto','시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X03','M2-2-u4-X02','M2-2-u4-X01']::text[],false,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 50분","correct":true},{"t":"3시 50분","mis":"M2-2-u4-X03"},{"t":"2시 10분","mis":"M2-2-u4-X02"},{"t":"10시 15분","mis":"M2-2-u4-X01"}],"explanation":["짧은바늘이 3에 가깝지만 아직 2와 3 사이 — 2시예요.","긴바늘이 숫자 10 — 50분이에요.","그래서 2시 50분이에요 — 3시 10분 전이라고도 해요."],"asset":{"type":"clock2","h":2,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#18','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',3,'mc','auto','등산을 9시에 시작해서 80분 뒤에 산 정상에 도착했어요. 도착한 시각은 언제인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"등산을 9시에 시작해서 80분 뒤에 산 정상에 도착했어요. 도착한 시각은 언제인가요?","options":[{"t":"10시 20분","correct":true},{"t":"9시 80분","mis":"M2-2-u4-X09"},{"t":"10시 80분","mis":"M2-2-u4-X09"},{"t":"9시 20분","mis":"M2-2-u4-X10"}],"explanation":["80분은 1시간 20분이에요.","9시에서 1시간 뒤는 10시, 20분 더 가서 10시 20분이에요.","분은 59분까지만 있어요 — 9시 80분은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#19','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C7',3,'mc','auto','어제 오전 9시에 출발해서 26시간 동안 여행했어요. 도착한 시각은 언제인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X12']::text[],false,'{"seq":19,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"어제 오전 9시에 출발해서 26시간 동안 여행했어요. 도착한 시각은 언제인가요?","options":[{"t":"오늘 오전 11시","correct":true},{"t":"어제 오전 11시","mis":"M2-2-u4-X13"},{"t":"오늘 오후 11시","mis":"M2-2-u4-X12"}],"explanation":["어제 오전 9시에서 24시간 뒤는 오늘 오전 9시예요.","2시간 더 가면 오늘 오전 11시예요.","26시간은 하루보다 2시간 더 긴 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#20','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C8',3,'mc','auto','슬기의 음악 줄넘기 날(월요일·수요일)에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u4-X14']::text[],false,'{"seq":20,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"슬기의 음악 줄넘기 날(월요일·수요일)에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"음악 줄넘기를 하는 날은 11월에 9번 있어요","correct":true},{"t":"음악 줄넘기를 하는 날은 11월 9일이에요","mis":"M2-2-u4-X14"},{"t":"음악 줄넘기를 하는 날은 11월에 30번 있어요","mis":"M2-2-u4-X14"}],"explanation":["월요일 5번, 수요일 4번이에요.","모두 9번 — 9일 동안 해요.","「11월 9일」은 하루의 날짜예요 — 날의 수와 날짜를 가려요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"2":"🎵","4":"🎵","9":"🎵","11":"🎵","16":"🎵","18":"🎵","23":"🎵","25":"🎵","30":"🎵"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#21','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C9',3,'mc','auto','「3개월」을 바르게 읽은 것과 「3달」을 바르게 읽은 것을 차례로 고른 것은 어느 것인가요?',ARRAY['M2-2-u4-X23']::text[],false,'{"seq":21,"concept":"M2-2-u4-C9","difficulty":3,"kind":"mc","stem":"「3개월」을 바르게 읽은 것과 「3달」을 바르게 읽은 것을 차례로 고른 것은 어느 것인가요?","options":[{"t":"삼 개월, 세 달","correct":true},{"t":"세 개월, 삼 달","mis":"M2-2-u4-X23"},{"t":"삼 개월, 삼 달","mis":"M2-2-u4-X23"}],"explanation":["「개월」은 한자어라 일, 이, 삼 — 「삼 개월」이에요.","「달」은 고유어라 한, 두, 세 — 「세 달」이에요.","둘 다 기간의 길이를 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#22','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',3,'mc','auto','처음 세발자전거를 탄 날 2022년 5월 12일에서 처음 두발자전거를 탄 날 2024년 7월 12일은 몇 년 몇 개월 후인가요?',ARRAY['M2-2-u4-X14','M2-2-u4-X15']::text[],false,'{"seq":22,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"처음 세발자전거를 탄 날 2022년 5월 12일에서 처음 두발자전거를 탄 날 2024년 7월 12일은 몇 년 몇 개월 후인가요?","options":[{"t":"2년 2개월 후","correct":true},{"t":"2년 7개월 후","mis":"M2-2-u4-X14"},{"t":"2개월 후","mis":"M2-2-u4-X15"}],"explanation":["2022년에서 2024년 — 2년 후예요.","5월에서 7월 — 2개월 후예요.","그래서 2년 2개월 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#23','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C7',4,'essay','teacher','「오전 11시에 친구들을 만나서 2시간 동안 놀았어.」 친구가 헤어진 시각을 「오후 13시」라고 썼어요. 무엇이 잘못되었는지 설명하고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C7","difficulty":4,"kind":"essay","stem":"「오전 11시에 친구들을 만나서 2시간 동안 놀았어.」 친구가 헤어진 시각을 「오후 13시」라고 썼어요. 무엇이 잘못되었는지 설명하고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 시계에는 13시가 없고, 낮 12시를 넘으면 다시 1시부터 센다. 오전 11시에서 1시간 뒤는 낮 12시, 1시간 더 가면 오후 1시이다. 바른 시각은 오후 1시이다.","scoring_points":["13시는 시계에 없다고 썼는가","낮 12시를 지나면 1시부터 다시 센다고 썼는가","오후 1시로 바르게 고쳤는가"]},"explanation":["오전 11시에서 1시간 뒤는 낮 12시예요.","낮 12시를 넘으면 다시 1시부터 세요.","그래서 오후 1시예요."],"asset":{"type":"digital","h":11,"m":0,"ampm":"오전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#24','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',4,'essay','teacher','나만의 성장 이야기를 만들어 보세요. 시작하는 날짜를 정하고 「몇 년 후」, 「몇 개월 후」, 「몇 주 후」를 한 번씩 써서 세 날짜를 차례로 구해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C10","difficulty":4,"kind":"essay","stem":"나만의 성장 이야기를 만들어 보세요. 시작하는 날짜를 정하고 「몇 년 후」, 「몇 개월 후」, 「몇 주 후」를 한 번씩 써서 세 날짜를 차례로 구해 보세요.","answer_guide":{"answer":"예: 2025년 3월 2일 2학년 입학 → 2주 후 2025년 3월 16일 처음 줄넘기 성공 → 3개월 후 2025년 6월 16일 두발자전거 → 1년 후 2026년 6월 16일 수영 대회.","scoring_points":["년·개월·주를 한 번씩 썼는가","주 후는 7일씩 더하고 달의 날수를 따졌는가","개월 후·년 후의 날짜를 바르게 구했는가"]},"explanation":["년 후는 해만, 개월 후는 달만 커져요.","주 후는 7일씩 더하고, 달이 넘어가면 그 달의 날수를 따져요.","날짜를 차례로 이어 나의 이야기를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g2_2_math_u4_review_d#25','math',2,2,'u4','','tb_g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',4,'mc','auto','슬기는 11월 14일부터 2주일마다 등산해요. 12월에 두 번째로 등산하는 날은 언제인가요?',ARRAY['M2-2-u4-X16','M2-2-u4-X15','M2-2-u4-X18']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"슬기는 11월 14일부터 2주일마다 등산해요. 12월에 두 번째로 등산하는 날은 언제인가요?","options":[{"t":"12월 26일","correct":true},{"t":"12월 12일","mis":"M2-2-u4-X16"},{"t":"12월 19일","mis":"M2-2-u4-X15"},{"t":"11월 56일","mis":"M2-2-u4-X18"}],"explanation":["11월 14일, 28일 다음은 12월 12일이에요.","거기서 2주일(14일) 뒤는 12월 26일이에요.","12월에는 12일, 26일에 등산해요."],"asset":{"type":"cal","mon":12,"start":2,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
